import {
  buildDreamtalkInjection,
  executeDreamtalkAnalysis,
  scanCharacterNamesFromContent,
  type CharacterNameEntry,
} from '../../明月秋青脚本/core/dreamtalk';
import { buildDynamicProfileInjection } from '../../明月秋青脚本/core/dynamicProfile';
import { buildNeuralChainInjection } from '../../明月秋青脚本/core/neuralChain';
import { executeGrandSummary, getContentsSinceLast, shouldTriggerSummary } from '../../明月秋青脚本/core/summary';
import type {
  GameMessage,
  GameSave,
  HeroineDynamicProfileState,
  MingyueCapturedContent,
  MingyueDreamtalkData,
  MingyueDynamicProfile,
  MingyueGrandSummary,
  MingyueMemoryState,
  MingyueUserInputRecord,
  PlayerAnalysisState,
} from './types';
import { createId, nowIso, recordDebugPacket } from './save';

const SUMMARY_INTERVAL = 10;

export function createInitialPlayerAnalysisState(): PlayerAnalysisState {
  return {
    placeholderText: '梦呓尚未生成。',
    sourceMessageIds: [],
    sourceOperationIds: [],
  };
}

export function normalizePlayerAnalysisState(raw: unknown): PlayerAnalysisState {
  const fallback = createInitialPlayerAnalysisState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<PlayerAnalysisState>;
  const placeholderText =
    candidate.placeholderText && candidate.placeholderText !== '玩家分析待生成。'
      ? candidate.placeholderText
      : fallback.placeholderText;
  return {
    placeholderText,
    updatedAtIso: candidate.updatedAtIso,
    sourceMessageIds: Array.isArray(candidate.sourceMessageIds) ? candidate.sourceMessageIds : [],
    sourceOperationIds: Array.isArray(candidate.sourceOperationIds) ? candidate.sourceOperationIds : [],
    rawOutput: candidate.rawOutput,
    lastSourceDigest: candidate.lastSourceDigest,
  };
}

export function createInitialMingyueMemoryState(): MingyueMemoryState {
  return {
    capturedContents: [],
    userInputRecords: [],
    summaries: [],
    dynamicProfiles: [],
    dreamtalk: null,
    lastSummaryAtMessageId: 0,
  };
}

function safeArray<T>(value: unknown): T[] {
  return Array.isArray(value) ? (value as T[]) : [];
}

export function normalizeMingyueMemoryState(raw: unknown): MingyueMemoryState {
  const fallback = createInitialMingyueMemoryState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<MingyueMemoryState>;
  return {
    capturedContents: safeArray<MingyueCapturedContent>(candidate.capturedContents),
    userInputRecords: safeArray<MingyueUserInputRecord>(candidate.userInputRecords),
    summaries: safeArray<MingyueGrandSummary>(candidate.summaries),
    dynamicProfiles: safeArray<MingyueDynamicProfile>(candidate.dynamicProfiles),
    dreamtalk: (candidate.dreamtalk as MingyueDreamtalkData | null | undefined) || null,
    lastSummaryAtMessageId: Number.isFinite(candidate.lastSummaryAtMessageId)
      ? Number(candidate.lastSummaryAtMessageId)
      : fallback.lastSummaryAtMessageId,
    lastSyncedAtIso: typeof candidate.lastSyncedAtIso === 'string' ? candidate.lastSyncedAtIso : undefined,
    lastError: typeof candidate.lastError === 'string' ? candidate.lastError : undefined,
  };
}

function compactText(value: string, maxLength = 1200): string {
  const text = value.replace(/\s+/g, ' ').trim();
  return text.length > maxLength ? `${text.slice(0, maxLength)}...` : text;
}

function numericMessageId(index: number): number {
  return index + 1;
}

function buildCapturedContents(messages: GameMessage[]): MingyueCapturedContent[] {
  return messages
    .filter(message => message.role === 'assistant')
    .map((message, index) => ({
      messageId: numericMessageId(index),
      content: message.text,
      capturedAt: message.createdAtIso,
      swipeCount: 0,
    }));
}

function buildUserInputRecords(messages: GameMessage[]): MingyueUserInputRecord[] {
  const records: MingyueUserInputRecord[] = [];
  let pendingUser: GameMessage | null = null;
  let assistantIndex = 0;

  for (const message of messages) {
    if (message.role === 'user') {
      pendingUser = message;
      continue;
    }
    if (message.role !== 'assistant') continue;
    assistantIndex += 1;
    if (!pendingUser) continue;
    records.push({
      messageId: assistantIndex,
      userInput: pendingUser.text,
      aiResponse: message.text,
      rolledResponses: [],
    });
    pendingUser = null;
  }

  return records;
}

function buildSourceDigest(save: GameSave, memory: MingyueMemoryState): string {
  return JSON.stringify({
    messageIds: save.messages.slice(-24).map(message => message.id),
    operationIds: save.operationLog.slice(0, 24).map(entry => entry.id),
    summaryVersion: memory.summaries[memory.summaries.length - 1]?.version || 0,
    dreamtalkVersion: memory.dreamtalk?.version || 0,
    lastSummaryAtMessageId: memory.lastSummaryAtMessageId,
  });
}

function refreshMingyueMemoryFromSave(save: GameSave): MingyueMemoryState {
  const current = normalizeMingyueMemoryState(save.mingyueMemory);
  return {
    ...current,
    capturedContents: buildCapturedContents(save.messages),
    userInputRecords: buildUserInputRecords(save.messages),
    lastSyncedAtIso: nowIso(),
    lastError: undefined,
  };
}

function getLatestSummary(memory: MingyueMemoryState): MingyueGrandSummary | undefined {
  return memory.summaries[memory.summaries.length - 1];
}

function upsertDynamicProfiles(
  currentProfiles: MingyueDynamicProfile[],
  incomingProfiles: MingyueDynamicProfile[],
): MingyueDynamicProfile[] {
  const profileMap = new Map(currentProfiles.map(profile => [profile.characterName, profile]));
  for (const profile of incomingProfiles) {
    profileMap.set(profile.characterName, profile);
  }
  return Array.from(profileMap.values());
}

function findHeroineDynamicProfile(save: GameSave, profiles: MingyueDynamicProfile[]): MingyueDynamicProfile | undefined {
  return profiles.find(profile => profile.characterName === save.heroine.name) || profiles[0];
}

function buildHeroineDynamicState(
  save: GameSave,
  profile: MingyueDynamicProfile | undefined,
  rawOutput: string,
  digest: string,
): HeroineDynamicProfileState {
  if (!profile) {
    return {
      ...save.heroine.dynamicProfile,
      rawOutput,
      lastSourceDigest: digest,
    };
  }

  return {
    placeholderText: profile.dynamicContent,
    updatedAtIso: profile.lastUpdatedAt,
    sourceLogIds: save.messages.filter(message => message.role === 'assistant').slice(-20).map(message => message.id),
    rawOutput,
    lastSourceDigest: digest,
  };
}

function getCharacterEntries(save: GameSave): CharacterNameEntry[] {
  const latestSummary = getLatestSummary(save.mingyueMemory);
  const entries = (latestSummary?.characterMemories || []).map(memory => ({
    name: memory.characterName,
    aliases: memory.aliases,
  }));
  if (save.heroine.name && !entries.some(entry => entry.name === save.heroine.name)) {
    entries.push({ name: save.heroine.name, aliases: [] });
  }
  return entries;
}

function getAllCharacterNames(save: GameSave): string[] {
  return Array.from(
    new Set([
      save.heroine.name,
      ...save.mingyueMemory.dynamicProfiles.map(profile => profile.characterName),
      ...(getLatestSummary(save.mingyueMemory)?.characterMemories || []).map(memory => memory.characterName),
    ].filter(Boolean)),
  );
}

function buildCurrentScanText(save: GameSave, publicOperation = ''): string {
  return [
    publicOperation,
    save.heroine.display.sceneLabel,
    save.heroine.display.actionLabel,
    save.messages[save.messages.length - 1]?.text || '',
    save.messages[save.messages.length - 2]?.text || '',
  ].join('\n');
}

function getCurrentCharacterNames(save: GameSave, publicOperation = ''): string[] {
  const knownNames = getAllCharacterNames(save);
  const entries = getCharacterEntries(save);
  const matched = scanCharacterNamesFromContent(buildCurrentScanText(save, publicOperation), knownNames, entries);
  return matched.length ? matched : [save.heroine.name].filter(Boolean);
}

export function buildMingyueDreamtalkPrompt(save: GameSave, publicOperation = ''): string | null {
  if (!save.mingyueMemory.dreamtalk) return null;
  return buildDreamtalkInjection(save.mingyueMemory.dreamtalk, getCurrentCharacterNames(save, publicOperation));
}

export function buildMingyueDynamicProfilePrompt(save: GameSave, publicOperation = ''): string | null {
  if (!save.mingyueMemory.dynamicProfiles.length) return null;
  return buildDynamicProfileInjection(save.mingyueMemory.dynamicProfiles, getCurrentCharacterNames(save, publicOperation));
}

export function buildMingyueNeuralChainPrompt(save: GameSave, publicOperation = ''): string | null {
  const latestSummary = getLatestSummary(save.mingyueMemory);
  if (!latestSummary?.characterMemories.length) return null;
  return buildNeuralChainInjection(
    latestSummary.characterMemories,
    getCurrentCharacterNames(save, publicOperation),
    save.player?.displayName || '{{user}}',
  );
}

export function buildPlayerAnalysisInput(save: GameSave): string {
  const memory = refreshMingyueMemoryFromSave(save);
  return JSON.stringify(
    {
      userPersonaRaw: save.player?.profileText || '',
      userInputRecords: memory.userInputRecords.slice(-10),
    },
    null,
    2,
  );
}

export function buildHeroineDynamicProfileInput(save: GameSave): string {
  const memory = refreshMingyueMemoryFromSave(save);
  return JSON.stringify(
    {
      previousSummary: getLatestSummary(memory),
      pendingContents: getContentsSinceLast(memory.capturedContents as any, memory.lastSummaryAtMessageId),
    },
    null,
    2,
  );
}

export async function runPlayerAnalysis(save: GameSave): Promise<GameSave> {
  const memory = refreshMingyueMemoryFromSave(save);
  const records = memory.userInputRecords.slice(-10);
  if (!records.length) throw new Error('没有可用于梦呓分析的用户输入记录。');

  const dreamtalk = (typeof generateRaw === 'function'
    ? await executeDreamtalkAnalysis(records as any, save.player?.profileText || '')
    : null) as MingyueDreamtalkData | null;
  const nextMemory: MingyueMemoryState = {
    ...memory,
    dreamtalk,
    lastSyncedAtIso: nowIso(),
  };
  const timestamp = nowIso();
  const preview = dreamtalk
    ? buildDreamtalkInjection(
        dreamtalk,
        dreamtalk.characterInteractions.map(interaction => interaction.characterName),
      )
    : '梦呓需要在酒馆生成环境中调用。';
  const nextSave: GameSave = {
    ...save,
    timestamps: {
      ...save.timestamps,
      lastPlayerAnalysisAtIso: timestamp,
    },
    mingyueMemory: nextMemory,
    playerAnalysis: {
      placeholderText: preview,
      updatedAtIso: timestamp,
      sourceMessageIds: save.messages.slice(-24).map(message => message.id),
      sourceOperationIds: save.operationLog.slice(0, 24).map(entry => entry.id),
      rawOutput: dreamtalk ? JSON.stringify(dreamtalk, null, 2) : preview,
      lastSourceDigest: buildSourceDigest(save, nextMemory),
    },
    analysisLog: [
      {
        id: createId('analysis'),
        kind: 'player_analysis' as const,
        inputPreview: buildPlayerAnalysisInput(save).slice(0, 700),
        outputPreview: preview.slice(0, 700),
        createdAtIso: timestamp,
      },
      ...save.analysisLog,
    ].slice(0, 60),
  };

  return recordDebugPacket(nextSave, {
    title: '梦呓分析生成包',
    body: JSON.stringify({ input: records, output: dreamtalk, promptSource: 'src/明月秋青脚本/core/dreamtalk.ts' }, null, 2),
  });
}

export async function runHeroineDynamicProfile(save: GameSave): Promise<GameSave> {
  const memory = refreshMingyueMemoryFromSave(save);
  const pendingContents = getContentsSinceLast(memory.capturedContents as any, memory.lastSummaryAtMessageId) as any[];
  const fallbackContents = memory.capturedContents.slice(-SUMMARY_INTERVAL) as any[];
  const contentsForSummary = pendingContents.length ? pendingContents : fallbackContents;
  if (!contentsForSummary.length) throw new Error('没有可用于大总结的正文日志。');

  const previousSummary = getLatestSummary(memory);
  const result = typeof generateRaw === 'function'
    ? await executeGrandSummary(contentsForSummary as any, previousSummary as any)
    : null;
  const timestamp = nowIso();
  const incomingSummary = result?.summary as MingyueGrandSummary | undefined;
  const incomingProfiles = (result?.dynamicProfiles || []) as MingyueDynamicProfile[];
  const summaries = incomingSummary ? [...memory.summaries, incomingSummary] : memory.summaries;
  const dynamicProfiles = upsertDynamicProfiles(memory.dynamicProfiles, incomingProfiles);
  const lastSummaryAtMessageId = contentsForSummary[contentsForSummary.length - 1]?.messageId || memory.lastSummaryAtMessageId;
  const nextMemory: MingyueMemoryState = {
    ...memory,
    summaries,
    dynamicProfiles,
    lastSummaryAtMessageId,
    lastSyncedAtIso: timestamp,
  };
  const digest = buildSourceDigest(save, nextMemory);
  const heroineProfile = findHeroineDynamicProfile(save, dynamicProfiles);
  const rawOutput = incomingSummary?.rawText || '大总结需要在酒馆生成环境中调用。';
  const nextSave: GameSave = {
    ...save,
    timestamps: {
      ...save.timestamps,
      lastHeroineProfileUpdatedAtIso: timestamp,
    },
    mingyueMemory: nextMemory,
    heroine: {
      ...save.heroine,
      dynamicProfile: buildHeroineDynamicState(save, heroineProfile, rawOutput, digest),
    },
    analysisLog: [
      {
        id: createId('analysis'),
        kind: 'heroine_dynamic_profile' as const,
        inputPreview: buildHeroineDynamicProfileInput(save).slice(0, 700),
        outputPreview: compactText(rawOutput, 700),
        createdAtIso: timestamp,
      },
      ...save.analysisLog,
    ].slice(0, 60),
  };

  return recordDebugPacket(nextSave, {
    title: '精准大总结生成包',
    body: JSON.stringify(
      {
        input: contentsForSummary,
        summary: incomingSummary,
        dynamicProfiles,
        promptSource: 'src/明月秋青脚本/core/summary.ts',
      },
      null,
      2,
    ),
  });
}

export function shouldAdvancePersonaWorkflow(save: GameSave): boolean {
  const memory = refreshMingyueMemoryFromSave(save);
  const digest = buildSourceDigest(save, memory);
  return digest !== save.playerAnalysis.lastSourceDigest && shouldTriggerSummary(memory.capturedContents as any, memory.lastSummaryAtMessageId, SUMMARY_INTERVAL);
}

export async function advancePersonaWorkflowsIfNeeded(save: GameSave, force = false): Promise<GameSave> {
  if (!force && !shouldAdvancePersonaWorkflow(save)) {
    return {
      ...save,
      mingyueMemory: refreshMingyueMemoryFromSave(save),
    };
  }

  const summarized = await runHeroineDynamicProfile(save);
  return runPlayerAnalysis(summarized);
}
