import type { ActionFactPacket, CultivationActionDefinition, GameSave, ResolvedGameplayAction } from './types';
import { markTimestamp } from './clock';
import { recordOperation } from './save';

export const CULTIVATION_ACTIONS: CultivationActionDefinition[] = [
  {
    id: 'observe',
    label: '观测',
    category: '基础',
    summary: '记录一次观测占位。',
    cost: {},
    progressDelta: 1,
    unlocked: true,
  },
  {
    id: 'practice',
    label: '修炼',
    category: '养成',
    summary: '执行一次修炼占位。',
    cost: { 灵石: 1 },
    progressDelta: 6,
    unlocked: true,
  },
  {
    id: 'rest',
    label: '调息',
    category: '养成',
    summary: '执行一次调息占位。',
    cost: {},
    progressDelta: 2,
    unlocked: true,
  },
];

function hasResources(save: GameSave, action: CultivationActionDefinition): boolean {
  return Object.entries(action.cost).every(([key, amount]) => (save.heroine.cultivation.resources[key] || 0) >= amount);
}

export function getCultivationActions(): CultivationActionDefinition[] {
  return CULTIVATION_ACTIONS;
}

function getVisualPatch(actionId: string) {
  const visualByAction: Record<string, { formalPoseId: string; avatarExpressionId: string; chibiAnimationId: string; expression: string }> = {
    observe: { formalPoseId: 'default', avatarExpressionId: 'thinking', chibiAnimationId: 'blink', expression: '思索' },
    practice: { formalPoseId: 'meditate', avatarExpressionId: 'serious', chibiAnimationId: 'meditate', expression: '认真' },
    rest: { formalPoseId: 'seated', avatarExpressionId: 'relieved', chibiAnimationId: 'sleepyNod', expression: '安心' },
  };
  return visualByAction[actionId] || visualByAction.observe;
}

export function resolveCultivationAction(save: GameSave, actionId: string): ResolvedGameplayAction {
  const action = CULTIVATION_ACTIONS.find(item => item.id === actionId);
  if (!action) throw Error('未知养成行动。');
  if (!action.unlocked) throw Error('该养成行动尚未解锁。');
  if (!hasResources(save, action)) throw Error('资源不足。');

  const resources = { ...save.heroine.cultivation.resources };
  Object.entries(action.cost).forEach(([key, amount]) => {
    resources[key] = (resources[key] || 0) - amount;
  });

  const progressed = Math.min(100, Math.max(0, save.heroine.cultivation.progress + action.progressDelta));
  const visualPatch = getVisualPatch(action.id);
  const nextSave: GameSave = {
    ...save,
    heroine: {
      ...save.heroine,
      display: {
        ...save.heroine.display,
        ...visualPatch,
        actionLabel: action.label,
      },
      cultivation: {
        ...save.heroine.cultivation,
        progress: progressed,
        resources,
      },
    },
  };

  const publicOperation = `玩家操作：让她${action.label}。`;
  const factPacket: ActionFactPacket = {
    actionId: action.id,
    section: 'cultivation',
    publicOperation,
    resultSummary: action.summary,
    stateDelta: {
      修为: `+${action.progressDelta}%`,
      当前修为: progressed,
    },
    frontendResult: {
      outcome: 'success',
      consumed: action.cost,
      rewards: action.progressDelta ? { 修为进度: action.progressDelta } : {},
      notes: ['本轮修炼操作已登记。', '已登记奖励不要再写入 <gain>。'],
    },
    performanceHint: {
      expression: visualPatch.expression,
      action: action.label,
      portrait: visualPatch.formalPoseId,
      chibi: visualPatch.chibiAnimationId,
      scene: nextSave.heroine.display.sceneLabel,
    },
    debugOnly: true,
  };

  return {
    save: recordOperation(markTimestamp(nextSave, 'lastCultivationResolvedAtIso'), {
      actionType: 'CULTIVATION_ACTION',
      label: action.label,
      detail: action.summary,
      section: '修炼',
      publicOperation,
      factPacketPreview: JSON.stringify(factPacket, null, 2),
    }),
    publicOperation,
    factPacket,
  };
}

export function applyCultivationAction(save: GameSave, actionId: string): GameSave {
  return resolveCultivationAction(save, actionId).save;
}
