export const useUiStore = defineStore('cultivation-fairy-girlfriend-ui', () => {
    const mobileTab = ref('story');
    const actionSection = ref('cultivation');
    const showDebug = ref(false);
    const storyLogOpen = ref(false);
    const analysisLogOpen = ref(false);
    function setMobileTab(tab) {
        mobileTab.value = tab;
    }
    function setActionSection(section) {
        actionSection.value = section;
    }
    function toggleDebug() {
        showDebug.value = !showDebug.value;
        if (showDebug.value)
            actionSection.value = 'debug';
    }
    function toggleStoryLog() {
        storyLogOpen.value = !storyLogOpen.value;
    }
    function toggleAnalysisLog() {
        analysisLogOpen.value = !analysisLogOpen.value;
    }
    return {
        mobileTab,
        actionSection,
        showDebug,
        storyLogOpen,
        analysisLogOpen,
        setMobileTab,
        setActionSection,
        toggleDebug,
        toggleStoryLog,
        toggleAnalysisLog,
    };
});
