import type { GameSave, TimestampState } from './types';
import { nowIso } from './save';

export function createInitialTimestampState(createdAtIso = nowIso()): TimestampState {
  return {
    realityIso: createdAtIso,
    cultivationWorldLabel: '开局',
  };
}

export function normalizeTimestampState(raw: unknown): TimestampState {
  const fallback = createInitialTimestampState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<TimestampState>;
  return {
    realityIso: candidate.realityIso || fallback.realityIso,
    cultivationWorldLabel: candidate.cultivationWorldLabel || fallback.cultivationWorldLabel,
    lastStoryGeneratedAtIso: candidate.lastStoryGeneratedAtIso,
    lastCultivationResolvedAtIso: candidate.lastCultivationResolvedAtIso,
    lastPlayerAnalysisAtIso: candidate.lastPlayerAnalysisAtIso,
    lastHeroineProfileUpdatedAtIso: candidate.lastHeroineProfileUpdatedAtIso,
    lastWorldbookSyncedAtIso: candidate.lastWorldbookSyncedAtIso,
  };
}

export function markTimestamp(save: GameSave, key: keyof TimestampState, value = nowIso()): GameSave {
  return {
    ...save,
    timestamps: {
      ...save.timestamps,
      [key]: value,
    },
  };
}

export function setCultivationWorldLabel(save: GameSave, label: string): GameSave {
  return {
    ...save,
    timestamps: {
      ...save.timestamps,
      cultivationWorldLabel: label.trim() || save.timestamps.cultivationWorldLabel,
    },
  };
}

