function normalizeRecipeText(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function inferArtByRequirement(requirements: RecipeRequirement[] | undefined): HundredArtId | null {
  for (const requirement of requirements || []) {
    const category = normalizeRecipeText(requirement.category);
    if (ART_REQUIREMENT_CATEGORY_MAP[category]) return ART_REQUIREMENT_CATEGORY_MAP[category];
    const text = `${requirement.category} ${requirement.name}`;
    if (/丹炉|药鼎|灵火/.test(text)) return 'alchemy';
    if (/锻造|铸|炉锤|砧/.test(text)) return 'forging';
    if (/阵盘|阵旗/.test(text)) return 'formation';
    if (/符笔|符纸|灵墨/.test(text)) return 'talisman';
    if (/药箱|医箱|银针/.test(text)) return 'medicine';
    if (/灵兽|契约|兽/.test(text)) return 'beast_taming';
    if (/傀儡|机巧|核心/.test(text)) return 'puppet';
    if (/灵田|药篓|种子/.test(text)) return 'herbology';
  }
  return null;
}

export function getArtRecipeKindLabel(artId: HundredArtId): string {
  return ART_RECIPE_KIND_LABELS[artId];
}

export function inferRecipeArtId(
  method: Pick<LearnedMethodState | ParsedAcquisitionMethod, 'kind' | 'name' | 'product' | 'requirements'>,
): HundredArtId | null {
  const kind = normalizeRecipeText(method.kind);
  if (ART_RECIPE_KIND_MAP[kind]) return ART_RECIPE_KIND_MAP[kind];
  const productCategory = normalizeRecipeText(method.product?.category);
  if (ART_PRODUCT_CATEGORY_MAP[productCategory]) return ART_PRODUCT_CATEGORY_MAP[productCategory];
  return inferArtByRequirement(method.requirements);
}

function formatRecipeDiscovery(method: Pick<LearnedMethodState | ParsedAcquisitionMethod, 'name' | 'progressLabel' | 'product' | 'executable'>): string {
  const productText = method.product?.name ? `->${method.product.name}` : '';
  const statusText = method.executable ? '可执行' : normalizeRecipeText(method.progressLabel) || '待整理';
  return `${method.name}(${statusText}${productText ? `/${productText}` : ''})`;
}

function replaceKnownRecipe(knownRecipes: string[], recipeName: string, recipeLabel: string): string[] {
  const filtered = knownRecipes.filter(item => item !== recipeName && !item.startsWith(`${recipeName}(`));
  return [recipeLabel, ...filtered].slice(0, 12);
}

function extractToolFromRequirements(requirements: RecipeRequirement[] | undefined): string {
  const toolRequirement = (requirements || []).find(requirement => /工具|丹炉|符笔|阵盘|锻造|药箱|契约|傀儡|药篓|灵田/.test(`${requirement.category}${requirement.name}`));
  return toolRequirement?.name || '';
}

export function applyRecipeDiscoveriesToGrowth(
  growth: HeroineGrowthState,
  methods: Array<LearnedMethodState | ParsedAcquisitionMethod>,
): HeroineGrowthState {
  let nextGrowth = growth;
  for (const method of methods) {
    const artId = inferRecipeArtId(method);
    if (!artId) continue;
    const art = nextGrowth.arts[artId];
    const recipeLabel = formatRecipeDiscovery(method);
    const toolLabel = extractToolFromRequirements(method.requirements);
    nextGrowth = {
      ...nextGrowth,
      arts: {
        ...nextGrowth.arts,
        [artId]: {
          ...art,
          stage: art.stage === '未习得' ? '初识' : art.stage,
          knownRecipes: replaceKnownRecipe(art.knownRecipes, method.name, recipeLabel),
          toolLabel: toolLabel || art.toolLabel,
          lastOutcome: `发现${getArtRecipeKindLabel(artId)}:${method.name}`,
        },
      },
    };
  }
  return nextGrowth;
}

