function normalizeNumber(value: unknown, fallback: number): number {
  return Number.isFinite(value) ? Number(value) : fallback;
}

export function normalizeGrowthState(raw: unknown): HeroineGrowthState {
  const fallback = createInitialGrowthState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<HeroineGrowthState>;
  const rawArts = (candidate.arts || {}) as Partial<Record<HundredArtId, Partial<HeroineArtProgressState>>>;
  return {
    ...fallback,
    ...candidate,
    currentActivity: {
      ...fallback.currentActivity,
      ...(candidate.currentActivity || {}),
    },
    condition: {
      ...fallback.condition,
      ...(candidate.condition || {}),
      stamina: normalizeNumber(candidate.condition?.stamina, fallback.condition.stamina),
      spiritualPower: normalizeNumber(candidate.condition?.spiritualPower, fallback.condition.spiritualPower),
      focus: normalizeNumber(candidate.condition?.focus, fallback.condition.focus),
      fatigue: normalizeNumber(candidate.condition?.fatigue, fallback.condition.fatigue),
      danPoison: normalizeNumber(candidate.condition?.danPoison, fallback.condition.danPoison),
    },
    cultivationTrack: {
      ...fallback.cultivationTrack,
      ...(candidate.cultivationTrack || {}),
      progress: normalizeNumber(candidate.cultivationTrack?.progress, fallback.cultivationTrack.progress),
      foundationStability: normalizeNumber(
        candidate.cultivationTrack?.foundationStability,
        fallback.cultivationTrack.foundationStability,
      ),
      breakthroughReadiness: normalizeNumber(
        candidate.cultivationTrack?.breakthroughReadiness,
        fallback.cultivationTrack.breakthroughReadiness,
      ),
    },
    arts: HUNDRED_ART_IDS.reduce(
      (result, artId) => ({
        ...result,
        [artId]: {
          ...fallback.arts[artId],
          ...(rawArts[artId] || {}),
          id: artId,
          label: ART_LABELS[artId],
          knownRecipes: Array.isArray(rawArts[artId]?.knownRecipes) ? rawArts[artId].knownRecipes : [],
        },
      }),
      {} as Record<HundredArtId, HeroineArtProgressState>,
    ),
    fishing: {
      ...fallback.fishing,
      ...(candidate.fishing || {}),
      journal: Array.isArray(candidate.fishing?.journal) ? candidate.fishing.journal : [],
    },
    activeBoosts: Array.isArray(candidate.activeBoosts) ? candidate.activeBoosts : [],
  };
}

