export type GameAction =
  | { type: 'REALITY_PROFILE_CONFIRM'; displayName: string; profileText: string }
  | { type: 'GAME_INSTALL_DISCOVERED' }
  | { type: 'HEROINE_BOOTSTRAP' }
  | { type: 'STORY_GENERATE'; input: string }
  | { type: 'PAYMENT_APPLY'; productId: string }
  | { type: 'CULTIVATION_ACTION'; actionId: string }
  | {
      type: 'GROWTH_OPERATION';
      operationId: string;
      usePaidMakeup?: boolean;
      purchaseMissingMaterials?: boolean;
      selection?: GrowthOperationSelection;
    }
  | { type: 'RECIPE_CONFIRM'; methodId: string }
  | {
      type: 'RECIPE_EXECUTE';
      methodId: string;
      usePaidMakeup?: boolean;
      purchaseMissingMaterials?: boolean;
      selection?: GrowthOperationSelection;
    }
  | { type: 'SCHEDULE_SET'; slotId: string; actionId: string }
  | { type: 'SCHEDULE_RESOLVE' }
  | { type: 'OFFLINE_IDLE_ASSIGN'; taskId: string }
  | { type: 'OFFLINE_IDLE_SETTLE' }
  | { type: 'EQUIPMENT_EQUIP'; itemId: string; slot?: string }
  | { type: 'EQUIPMENT_UNEQUIP'; slot: string }
  | { type: 'WARDROBE_APPLY'; itemId: string; slot?: string }
  | { type: 'HEROINE_STATUS_UPDATE'; label: string }
  | { type: 'PLAYER_ANALYSIS_RUN' }
  | { type: 'HEROINE_DYNAMIC_PROFILE_RUN' }
  | { type: 'PERSONA_AUTO_ADVANCE'; force?: boolean }
  | {
      type: 'WORLD_WORKSHOP_SEARCH';
      search?: string;
      kind?: WorldWorkshopContentKind;
      tag?: string;
      reviewStatus?: WorldWorkshopReviewStatus;
    }
  | { type: 'WORLD_WORKSHOP_DOWNLOAD'; moduleId: string }
  | { type: 'WORLD_WORKSHOP_ROLLBACK'; moduleId: string; version?: string }
  | { type: 'WORLD_WORKSHOP_UPDATE_DIGEST' }
  | { type: 'WORLD_WORKSHOP_SUBMIT'; submission: WorldWorkshopModuleSubmission }
  | { type: 'HEROINE_SNAPSHOT_UPLOAD' }
  | { type: 'HEROINE_SNAPSHOT_SEARCH'; search?: string }
  | { type: 'INVITED_SNAPSHOT_INSTALL'; snapshotId: string }
  | { type: 'REWARD_PACKAGE_FETCH' }
  | { type: 'REWARD_PACKAGE_CLAIM'; packageId: string; selection?: ClaimableRewardSelection }
  | { type: 'REWARD_PACKAGE_DISCARD'; packageId: string }
  | { type: 'TRADE_FETCH' }
  | { type: 'TRADE_SEND'; tradePackage?: TradePackage; targetSnapshotId?: string; note?: string }
  | { type: 'TRADE_ACCEPT'; tradeId: string }
  | { type: 'TRADE_REJECT'; tradeId: string }
  | { type: 'TRADE_CANCEL'; tradeId: string }
  | { type: 'ONLINE_REALM_COLLABORATION_START'; mode?: 'snapshot_link' | 'live_link'; snapshotIds?: string[] }
  | { type: 'ONLINE_REALM_COLLABORATION_STOP'; snapshotId?: string }
  | { type: 'PROMPT_INJECT_PREVIEW'; publicOperation: string }
  | { type: 'GAMEPLAY_LOGIC_CHECK' }
  | { type: 'WORLD_NETWORK_PREVIEW' }
  | { type: 'HEROINE_SNAPSHOT_PREVIEW' }
  | { type: 'WORLD_NETWORK_LOGIC_CHECK' }
  | { type: 'WORLDBOOK_PLACEHOLDER_PREVIEW' }
  | { type: 'WORLDBOOK_PLACEHOLDER_SYNC' }
  | { type: 'DEBUG_FORCE_TIMESTAMP'; label: string }
  | { type: 'DEBUG_FORCE_UNLOCK' };

function success(save: GameSave, message?: string): ActionResult {
  return { ok: true, save, message };
}

function failure(save: GameSave, error: unknown): ActionResult {
  const nextSave = recordDebugError(save, error);
  return { ok: false, save: nextSave, error: error instanceof Error ? error.message : String(error) };
}

function confirmRecipe(save: GameSave, methodId: string): GameSave {
  const inventory = confirmRecipeMethod(save.inventory, methodId);
  const method = inventory.methods.find(item => item.id === methodId);
  if (!method) throw Error('配方整理失败。');
  const nextSave: GameSave = {
    ...save,
    inventory,
    heroine: {
      ...save.heroine,
      growth: applyRecipeDiscoveriesToGrowth(save.heroine.growth, [method]),
    },
  };
  return recordOperation(recordMessage(nextSave, 'script', 'system', `已整理${method.kind}：${method.name}。`), {
    actionType: 'RECIPE_CONFIRM',
    label: `整理${method.kind}`,
    detail: `${method.name} 已标记为可执行配方。`,
    section: '百艺',
  });
}

function defaultRewardSelection(rewardPackage: ClaimableRewardPackage): ClaimableRewardSelection {
  return {
    itemIndexes: rewardPackage.selectable.items.map((_, index) => index),
    methodIndexes: rewardPackage.selectable.methods.map((_, index) => index),
    equipIndexes: rewardPackage.selectable.equip.map((_, index) => index),
    resourceKeys: Object.keys(rewardPackage.selectable.resources),
    keepStorySummary: true,
    keepRelationshipNotes: true,
    keepTitleNotes: true,
  };
}

function updateTradeStatus(save: GameSave, tradeId: string, status: TradePackage['status'], receiptPackageId?: string): GameSave {
  return {
    ...save,
    worldNetwork: {
      ...save.worldNetwork,
      tradePackages: save.worldNetwork.tradePackages.map(trade =>
        trade.tradeId === tradeId
          ? {
              ...trade,
              status,
              receiptPackageId: receiptPackageId || trade.receiptPackageId,
            }
          : trade,
      ),
      lastSyncedAtIso: nowIso(),
    },
  };
}

function isOutgoingTrade(save: GameSave, trade: TradePackage): boolean {
  return trade.fromUserName === (save.player?.displayName || '{{user}}');
}

function acceptTradeOfferLocally(save: GameSave, tradeId: string, receiptPackageId?: string): GameSave {
  const target = save.worldNetwork.tradePackages.find(trade => trade.tradeId === tradeId);
  if (!target) throw Error('未找到交易包。');
  if (target.status !== 'sent') throw Error('该交易包当前不可接受。');
  if (isOutgoingTrade(save, target)) throw Error('不能接受自己发出的交易包，只能撤回。');

  const timestamp = nowIso();
  const selected = target.offer;
  const packet: ParsedAcquisitionPacket = {
    schema: 'fairy_inventory_parse_v1',
    items: selected.items || [],
    methods: selected.methods || [],
    equip: selected.equip || [],
    resources: selected.resources || {},
    notes: target.note ? [`交易备注: ${target.note}`] : [],
    sourceActionId: target.tradeId,
  };
  const nextResources = { ...save.heroine.cultivation.resources };
  for (const [key, value] of Object.entries(selected.resources || {})) {
    nextResources[key] = (nextResources[key] || 0) + value;
  }

  return {
    ...save,
    heroine: {
      ...save.heroine,
      cultivation: {
        ...save.heroine.cultivation,
        resources: nextResources,
      },
    },
    inventory: applyParsedAcquisitionPacket(save.inventory, packet, JSON.stringify(packet), timestamp),
    operationLog: [
      {
        id: `trade_accept_${tradeId}`,
        actionType: 'TRADE_ACCEPT',
        label: '接受交易',
        detail: `来自 ${target.fromUserName} 的交易已写入本地。`,
        section: 'world_network',
        factPacketPreview: JSON.stringify(packet, null, 2),
        createdAtIso: timestamp,
      },
      ...save.operationLog,
    ].slice(0, 80),
    worldNetwork: {
      ...save.worldNetwork,
      tradePackages: save.worldNetwork.tradePackages.map(trade =>
        trade.tradeId === tradeId
          ? {
              ...trade,
              status: 'accepted' as const,
              receiptPackageId: receiptPackageId || trade.receiptPackageId,
            }
          : trade,
      ),
      lastSyncedAtIso: timestamp,
    },
  };
}

export async function dispatchGameAction(save: GameSave, action: GameAction): Promise<ActionResult> {
  const actionSave: GameSave = {
    ...save,
    debug: {
      ...save.debug,
      lastAction: action.type,
    },
  };

  try {
    switch (action.type) {
      case 'REALITY_PROFILE_CONFIRM': {
        const displayName = action.displayName.trim() || '{{user}}';
        const profileText = action.profileText.trim() || '玩家现实设定占位。';
        const profileSave: GameSave = {
          ...actionSave,
          stage: 'profile_ready',
          player: {
            displayName,
            profileText,
            confirmedAtIso: nowIso(),
          },
        };
        return success(recordMessage(profileSave, 'script', 'system', '玩家现实设定占位已记录。'), '玩家现实设定占位已记录。');
      }

      case 'GAME_INSTALL_DISCOVERED':
        return success(
          recordOperation(
            recordMessage(
              {
                ...actionSave,
                stage: 'game_discovered',
              },
              'script',
              'system',
              '修仙游戏出现事件占位已记录。',
            ),
            {
              actionType: action.type,
              label: '游戏出现',
              detail: '修仙游戏出现事件占位。',
            },
          ),
          '修仙游戏出现事件占位已记录。',
        );

      case 'HEROINE_BOOTSTRAP':
        return success(recordMessage(initializeHeroine(actionSave), 'script', 'system', '女主初始化占位已记录。'), '女主初始化占位已记录。');

      case 'STORY_GENERATE':
        return success(await generateStoryPlaceholder(actionSave, action.input), '正文生成占位已记录。');

      case 'PAYMENT_APPLY':
        {
          const resolved = resolvePaymentProduct(actionSave, action.productId);
          return success(await generateStoryForResolvedAction(resolved.save, resolved.factPacket), '资源投放已结算并连接正文。');
        }

      case 'CULTIVATION_ACTION':
        {
          const resolved = resolveCultivationAction(actionSave, action.actionId);
          return success(await generateStoryForResolvedAction(resolved.save, resolved.factPacket), '修炼操作已结算并连接正文。');
        }

      case 'GROWTH_OPERATION':
        {
          const resolved = resolveGrowthOperation(actionSave, action.operationId, {
            usePaidMakeup: action.usePaidMakeup,
            purchaseMissingMaterials: action.purchaseMissingMaterials,
            selection: action.selection,
          });
          return success(await generateStoryForResolvedAction(resolved.save, resolved.factPacket), '玩法操作已结算并连接正文。');
        }

      case 'RECIPE_CONFIRM':
        return success(confirmRecipe(actionSave, action.methodId), '配方已整理为可执行。');

      case 'RECIPE_EXECUTE':
        {
          const resolved = resolveRecipeCraft(actionSave, action.methodId, {
            usePaidMakeup: action.usePaidMakeup,
            purchaseMissingMaterials: action.purchaseMissingMaterials,
            selection: action.selection,
          });
          return success(await generateStoryForResolvedAction(resolved.save, resolved.factPacket), '配方制作已结算并连接正文。');
        }

      case 'SCHEDULE_SET':
        return success(
          recordOperation(
            {
              ...actionSave,
              schedule: actionSave.schedule.map(slot =>
                slot.id === action.slotId ? { ...slot, assignedActionId: action.actionId } : slot,
              ),
            },
            {
              actionType: action.type,
              label: '日程安排',
              detail: `${action.slotId}: ${action.actionId}`,
            },
          ),
          '日程占位已更新。',
        );

      case 'SCHEDULE_RESOLVE':
        return success(recordOperation(actionSave, { actionType: action.type, label: '日程结算', detail: '日程结算占位。' }), '日程结算占位已记录。');

      case 'OFFLINE_IDLE_ASSIGN':
        return success(
          recordOperation(assignOfflineIdleTask(actionSave, action.taskId), {
            actionType: action.type,
            label: '离线挂机安排',
            detail: `已安排离线任务：${action.taskId}`,
            section: '生活',
          }),
          '离线挂机任务已安排。',
        );

      case 'OFFLINE_IDLE_SETTLE':
        {
          const resolved = resolveOfflineIdle(actionSave);
          return success(await generateStoryForResolvedAction(resolved.save, resolved.factPacket), '离线挂机已结算并连接正文。');
        }

      case 'EQUIPMENT_EQUIP':
        {
          const resolved = equipInventoryItem(actionSave, action.itemId, action.slot);
          return success(await generateStoryForResolvedAction(resolved.save, resolved.factPacket), '装备已切换并连接正文。');
        }

      case 'EQUIPMENT_UNEQUIP':
        {
          const resolved = unequipSlot(actionSave, action.slot);
          return success(await generateStoryForResolvedAction(resolved.save, resolved.factPacket), '装备已卸下并连接正文。');
        }

      case 'WARDROBE_APPLY':
        {
          const resolved = applyWardrobeItem(actionSave, action.itemId, action.slot || '时装');
          return success(await generateStoryForResolvedAction(resolved.save, resolved.factPacket), '时装已切换并连接正文。');
        }

      case 'HEROINE_STATUS_UPDATE':
        return success(updateHeroineDisplay(actionSave, action.label), '女主展示状态占位已更新。');

      case 'PLAYER_ANALYSIS_RUN':
        return success(await runPlayerAnalysis(actionSave), '梦呓已按明月秋青脚本生成并写回内置上下文。');

      case 'HEROINE_DYNAMIC_PROFILE_RUN':
        return success(await runHeroineDynamicProfile(actionSave), '精准大总结与动态人设已按明月秋青脚本生成并写回内置上下文。');

      case 'PERSONA_AUTO_ADVANCE':
        return success(await advancePersonaWorkflowsIfNeeded(actionSave, action.force), '大总结、动态人设与梦呓推进检查已完成。');

      case 'WORLD_WORKSHOP_SEARCH':
        {
          const result = await searchWorldWorkshopModules(
            {
              pageSize: 50,
              search: action.search,
              kind: action.kind,
              tag: action.tag,
              reviewStatus: action.reviewStatus || 'approved',
            },
            actionSave.worldWorkshop.endpointBase,
          );
          const timestamp = nowIso();
          let nextWorldWorkshop = actionSave.worldWorkshop;
          const installed: string[] = [];

          for (const summary of result.modules.filter(module => (module.reviewStatus || 'approved') === 'approved')) {
            const current = nextWorldWorkshop.installedModules.find(module => module.id === summary.id);
            if (current?.version === summary.version) continue;
            const module = await downloadWorldWorkshopModule(summary.id, summary.version, actionSave.worldWorkshop.endpointBase);
            nextWorldWorkshop = installWorldWorkshopModule(nextWorldWorkshop, module);
            installed.push(`${summary.title}@${summary.version}`);
          }

          return success(
            recordDebugPacket(
              {
                ...actionSave,
                worldWorkshop: {
                  ...nextWorldWorkshop,
                  searchResults: result.modules,
                  lastSearchTotal: result.total,
                  lastSearchAtIso: timestamp,
                  lastError: undefined,
                },
              },
              {
                title: '世界模块自动同步结果',
                body: JSON.stringify({ result, installed }, null, 2),
              },
            ),
            `世界模块自动同步完成：${result.total} 个结果，安装/更新 ${installed.length} 个。`,
          );
        }

      case 'WORLD_WORKSHOP_DOWNLOAD':
        {
          const module = await downloadWorldWorkshopModule(action.moduleId, undefined, actionSave.worldWorkshop.endpointBase);
          const nextWorldWorkshop = installWorldWorkshopModule(actionSave.worldWorkshop, module);
          return success(
            recordDebugPacket(
              {
                ...actionSave,
                worldWorkshop: nextWorldWorkshop,
              },
              {
                title: '世界模块已安装',
                body: JSON.stringify(module, null, 2),
              },
            ),
            `已安装世界模块：${module.title}。`,
          );
        }

      case 'WORLD_WORKSHOP_ROLLBACK':
        {
          const nextWorldWorkshop = rollbackWorldWorkshopModule(actionSave.worldWorkshop, action.moduleId, action.version);
          return success(
            recordDebugPacket(
              {
                ...actionSave,
                worldWorkshop: nextWorldWorkshop,
              },
              {
                title: '世界模块已回退',
                body: buildWorldWorkshopUpdateDigest(nextWorldWorkshop),
              },
            ),
            '世界模块已回退到旧版本。',
          );
        }

      case 'WORLD_WORKSHOP_UPDATE_DIGEST':
        return success(
          recordDebugPacket(actionSave, {
            title: '世界模块更新策略预览',
            body: buildWorldWorkshopUpdateDigest(actionSave.worldWorkshop),
          }),
          '世界模块更新提示、回退、依赖与冲突摘要已生成。',
        );

      case 'WORLD_WORKSHOP_SUBMIT':
        {
          const result = await submitWorldWorkshopModuleForReview(action.submission, actionSave.worldWorkshop.endpointBase);
          return success(
            recordDebugPacket(
              {
                ...actionSave,
                worldWorkshop: {
                  ...actionSave.worldWorkshop,
                  lastSubmissionId: result.submissionId,
                },
              },
              {
                title: '世界模块投稿已提交',
                body: JSON.stringify({ submission: action.submission, result }, null, 2),
              },
            ),
            `世界模块已提交审核：${result.submissionId}。`,
          );
        }

      case 'HEROINE_SNAPSHOT_UPLOAD':
        {
          const snapshot = createHeroinePublicSnapshot(actionSave);
          const result = await uploadHeroinePublicSnapshot(snapshot, actionSave.worldNetwork.endpointBase);
          return success(
            recordDebugPacket(
              {
                ...actionSave,
                worldNetwork: {
                  ...actionSave.worldNetwork,
                  uploadedSnapshotId: result.snapshotId,
                  lastSyncedAtIso: nowIso(),
                  lastError: undefined,
                },
              },
              {
                title: '老婆公开快照已上传',
                body: JSON.stringify(snapshot, null, 2),
              },
            ),
            `老婆快照已上传：${result.snapshotId}。`,
          );
        }

      case 'HEROINE_SNAPSHOT_SEARCH':
        {
          const result = await searchHeroinePublicSnapshots(
            {
              pageSize: 12,
              search: action.search,
            },
            actionSave.worldNetwork.endpointBase,
          );
          return success(
            recordDebugPacket(
              {
                ...actionSave,
                worldNetwork: {
                  ...actionSave.worldNetwork,
                  snapshotSearchResults: result.snapshots,
                  lastSnapshotSearchTotal: result.total,
                  lastSyncedAtIso: nowIso(),
                  lastError: undefined,
                },
              },
              {
                title: '老婆快照搜索结果',
                body: JSON.stringify(result, null, 2),
              },
            ),
            `老婆快照搜索完成：${result.total} 个结果。`,
          );
        }

      case 'INVITED_SNAPSHOT_INSTALL':
        {
          const snapshot = await downloadHeroinePublicSnapshot(action.snapshotId, actionSave.worldNetwork.endpointBase);
          return success(
            recordDebugPacket(
              {
                ...actionSave,
                worldNetwork: installInvitedHeroineSnapshot(actionSave.worldNetwork, snapshot, true),
                onlineRealm: activateSnapshotCollaboration(actionSave.onlineRealm, [snapshot.snapshotId], `已邀请 ${snapshot.heroineName} 进入协作正文。`),
              },
              {
                title: '同行老婆快照已安装',
                body: JSON.stringify(snapshot, null, 2),
              },
            ),
            `已邀请同行快照：${snapshot.heroineName}。`,
          );
        }

      case 'REWARD_PACKAGE_FETCH':
        {
          const [rewardPackages, reports, trades] = await Promise.all([
            fetchClaimableRewardPackages(actionSave.worldNetwork.endpointBase),
            fetchExternalAdventureReports(actionSave.worldNetwork.endpointBase),
            fetchTradePackages(actionSave.worldNetwork.endpointBase),
          ]);
          return success(
            {
              ...actionSave,
              worldNetwork: {
                ...actionSave.worldNetwork,
                claimableRewardPackages: rewardPackages,
                externalReports: reports,
                tradePackages: trades,
                lastSyncedAtIso: nowIso(),
                lastError: undefined,
              },
            },
            `已同步奖励包 ${rewardPackages.length} 个、剧情摘要 ${reports.length} 条、交易 ${trades.length} 个。`,
          );
        }

      case 'REWARD_PACKAGE_CLAIM':
        {
          const target = actionSave.worldNetwork.claimableRewardPackages.find(item => item.packageId === action.packageId);
          if (!target) throw Error('未找到奖励包。');
          const selection = action.selection || defaultRewardSelection(target);
          await claimRemoteRewardPackage(action.packageId, selection, actionSave.worldNetwork.endpointBase);
          return success(claimRewardPackage(actionSave, action.packageId, selection), '奖励包已按勾选内容保存。');
        }

      case 'REWARD_PACKAGE_DISCARD':
        await discardRemoteRewardPackage(action.packageId, actionSave.worldNetwork.endpointBase);
        return success(discardRewardPackage(actionSave, action.packageId), '奖励包已丢弃。');

      case 'TRADE_FETCH':
        {
          const tradePackages = await fetchTradePackages(actionSave.worldNetwork.endpointBase);
          return success(
            {
              ...actionSave,
              worldNetwork: {
                ...actionSave.worldNetwork,
                tradePackages,
                lastSyncedAtIso: nowIso(),
              },
            },
            `交易列表已同步：${tradePackages.length} 个。`,
          );
        }

      case 'TRADE_SEND':
        {
          const draft =
            action.tradePackage ||
            createTradePackage({
              mode: action.targetSnapshotId ? 'save_mail' : 'online_trade',
              fromUserName: actionSave.player?.displayName || '{{user}}',
              targetSnapshotId: action.targetSnapshotId,
              note: action.note || '交易请求：等待对方确认。',
            });
          const sent: TradePackage = { ...draft, status: 'sent' };
          const result = await submitTradePackage(sent, actionSave.worldNetwork.endpointBase);
          return success(
            recordDebugPacket(
              {
                ...actionSave,
                worldNetwork: {
                  ...actionSave.worldNetwork,
                  tradePackages: [
                    { ...sent, tradeId: result.tradeId },
                    ...actionSave.worldNetwork.tradePackages.filter(item => item.tradeId !== result.tradeId),
                  ].slice(0, 60),
                  lastSyncedAtIso: nowIso(),
                },
              },
              {
                title: '交易包已发送',
                body: JSON.stringify(sent, null, 2),
              },
            ),
            `交易包已发送：${result.tradeId}。`,
          );
        }

      case 'TRADE_ACCEPT':
        {
          const target = actionSave.worldNetwork.tradePackages.find(trade => trade.tradeId === action.tradeId);
          if (!target) throw Error('未找到交易包。');
          if (isOutgoingTrade(actionSave, target)) throw Error('自己发出的交易只能撤回，不能接受。');
          const result = await acceptRemoteTradePackage(action.tradeId, actionSave.worldNetwork.endpointBase);
          return success(acceptTradeOfferLocally(actionSave, action.tradeId, result.receiptPackageId), '交易已接受并写入本地。');
        }

      case 'TRADE_REJECT':
        await rejectRemoteTradePackage(action.tradeId, actionSave.worldNetwork.endpointBase);
        return success(updateTradeStatus(actionSave, action.tradeId, 'rejected'), '交易已拒绝。');

      case 'TRADE_CANCEL':
        await cancelRemoteTradePackage(action.tradeId, actionSave.worldNetwork.endpointBase);
        return success(updateTradeStatus(actionSave, action.tradeId, 'cancelled'), '交易已取消。');

      case 'ONLINE_REALM_COLLABORATION_START':
        {
          const snapshotIds = action.snapshotIds?.length
            ? action.snapshotIds
            : actionSave.worldNetwork.activeInvitedSnapshotIds;
          const onlineRealm =
            action.mode === 'live_link'
              ? activateLiveCollaboration(actionSave.onlineRealm, snapshotIds, '无房间联动正文已开启。')
              : activateSnapshotCollaboration(actionSave.onlineRealm, snapshotIds, '快照同行协作正文已开启。');
          return success(
            recordOperation(
              {
                ...actionSave,
                onlineRealm,
              },
              {
                actionType: action.type,
                label: action.mode === 'live_link' ? '无房间联动正文' : '快照同行正文',
                detail: `同行快照: ${snapshotIds.join('、') || '无'}`,
                section: '联动',
              },
            ),
            action.mode === 'live_link' ? '无房间联动正文已开启。' : '快照同行正文已开启。',
          );
        }

      case 'ONLINE_REALM_COLLABORATION_STOP':
        return success(
          recordOperation(
            {
              ...actionSave,
              onlineRealm: deactivateSnapshotCollaboration(actionSave.onlineRealm, action.snapshotId),
            },
            {
              actionType: action.type,
              label: '关闭联动正文',
              detail: action.snapshotId ? `移除 ${action.snapshotId}` : '关闭全部联动',
              section: '联动',
            },
          ),
          '联动正文已关闭。',
        );

      case 'PROMPT_INJECT_PREVIEW':
        return success(
          recordDebugPacket(actionSave, {
            title: '本轮提示词注入预览',
            body: buildPromptInjectPreview(actionSave, action.publicOperation),
          }),
          '提示词注入预览已生成。',
        );

      case 'GAMEPLAY_LOGIC_CHECK':
        {
          const check = runGameplayLogicCheck(actionSave);
          const nextSave = recordDebugPacket(actionSave, {
              title: check.ok ? '玩法脚本逻辑自检通过' : '玩法脚本逻辑自检失败',
              body: check.report,
            });
          return {
            ok: check.ok,
            save: nextSave,
            message: check.ok ? '玩法脚本逻辑自检通过。' : '玩法脚本逻辑自检发现问题。',
            error: check.ok ? undefined : '玩法脚本逻辑自检失败。',
          };
        }

      case 'WORLD_NETWORK_PREVIEW':
        {
          const previewText = buildWorldNetworkPreview(actionSave);
          return success(
            recordDebugPacket(
              {
                ...actionSave,
                worldNetwork: {
                  ...actionSave.worldNetwork,
                  lastPreviewText: previewText,
                },
              },
              {
                title: '世界工坊与联机网络预览',
                body: previewText,
              },
            ),
            '世界工坊与联机网络预览已生成。',
          );
        }

      case 'HEROINE_SNAPSHOT_PREVIEW':
        return success(
          recordDebugPacket(actionSave, {
            title: '老婆公开快照预览',
            body: JSON.stringify(createHeroinePublicSnapshot(actionSave), null, 2),
          }),
          '老婆公开快照预览已生成。',
        );

      case 'WORLD_NETWORK_LOGIC_CHECK':
        {
          const check = runWorldNetworkLogicCheck(actionSave);
          const nextSave = recordDebugPacket(check.save, {
            title: check.ok ? '世界工坊联机脚本自检通过' : '世界工坊联机脚本自检失败',
            body: check.report,
          });
          return {
            ok: check.ok,
            save: nextSave,
            message: check.ok ? '世界工坊联机脚本自检通过。' : '世界工坊联机脚本自检发现问题。',
            error: check.ok ? undefined : '世界工坊联机脚本自检失败。',
          };
        }

      case 'WORLDBOOK_PLACEHOLDER_PREVIEW':
        return success(previewWorldbookPlaceholders(actionSave), '世界书占位预览已生成。');

      case 'WORLDBOOK_PLACEHOLDER_SYNC':
        return success(await syncWorldbookPlaceholders(actionSave), '世界书占位同步已执行。');

      case 'DEBUG_FORCE_TIMESTAMP':
        return success(setCultivationWorldLabel(actionSave, action.label), '时间戳占位已修改。');

      case 'DEBUG_FORCE_UNLOCK':
        return success(recordOperation(actionSave, { actionType: action.type, label: '调试解锁', detail: '调试解锁占位。' }), '调试解锁占位已记录。');

      default:
        return failure(actionSave, '未知 Action。');
    }
  } catch (error) {
    return failure(actionSave, error);
  }
}
