export function createInitialOfflineIdleState(createdAtIso = nowIso()): OfflineIdleState {
  return {
    enabled: true,
    assignments: [
      {
        id: createId('offline-assignment'),
        taskId: 'offline_rest',
        label: '离线休息',
        assignedAtIso: createdAtIso,
      },
    ],
    lastSettledAtIso: createdAtIso,
    maxSettleHours: 12,
    settlementLog: [],
  };
}

export function normalizeOfflineIdleState(raw: unknown, createdAtIso = nowIso()): OfflineIdleState {
  const fallback = createInitialOfflineIdleState(createdAtIso);
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<OfflineIdleState>;
  return {
    enabled: candidate.enabled ?? fallback.enabled,
    assignments: Array.isArray(candidate.assignments) ? candidate.assignments : fallback.assignments,
    lastSettledAtIso: typeof candidate.lastSettledAtIso === 'string' ? candidate.lastSettledAtIso : fallback.lastSettledAtIso,
    maxSettleHours: Number.isFinite(candidate.maxSettleHours) ? Number(candidate.maxSettleHours) : fallback.maxSettleHours,
    settlementLog: Array.isArray(candidate.settlementLog) ? candidate.settlementLog : [],
  };
}

export function getOfflineIdleTasks(): OfflineIdleTaskDefinition[] {
  return OFFLINE_IDLE_TASKS;
}

export function assignOfflineIdleTask(save: GameSave, taskId: string): GameSave {
  const task = OFFLINE_IDLE_TASKS.find(item => item.id === taskId);
  if (!task) throw new Error('未知离线挂机任务。');
  const assignment: OfflineIdleAssignment = {
    id: createId('offline-assignment'),
    taskId,
    label: task.label,
    assignedAtIso: nowIso(),
  };
  return {
    ...save,
    offlineIdle: {
      ...save.offlineIdle,
      enabled: true,
      assignments: [assignment],
    },
  };
}

function elapsedHours(fromIso: string, toIso: string, maxHours: number): number {
  const from = new Date(fromIso).getTime();
  const to = new Date(toIso).getTime();
  if (!Number.isFinite(from) || !Number.isFinite(to) || to <= from) return 0;
  return Math.min(maxHours, Math.floor((to - from) / HOUR_MS));
}

function scaleRewards(task: OfflineIdleTaskDefinition, hours: number): Record<string, number> {
  return Object.entries(task.rewardsPerHour).reduce<Record<string, number>>((result, [key, value]) => {
    result[key] = Math.max(0, Math.floor(value * hours));
    return result;
  }, {});
}

function applyOfflineRewards(save: GameSave, rewards: Record<string, number>, task: OfflineIdleTaskDefinition, hours: number): GameSave {
  const resources = { ...save.heroine.cultivation.resources };
  Object.entries(rewards).forEach(([key, value]) => {
    if (/修为进度/.test(key)) return;
    if (/体力恢复/.test(key)) return;
    resources[key] = (resources[key] || 0) + value;
  });
  const stamina = Math.max(0, Math.min(100, save.heroine.growth.condition.stamina - task.staminaCostPerHour * hours));
  const fatigue = Math.max(0, Math.min(100, save.heroine.growth.condition.fatigue + task.fatiguePerHour * hours));
  const progressDelta = rewards.修为进度 || 0;

  return {
    ...save,
    heroine: {
      ...save.heroine,
      display: {
        ...save.heroine.display,
        actionLabel: task.label,
        emotionStatus: task.kind === 'rest' ? '稍微恢复' : hours >= 6 ? '累到想抱怨' : '有点不满',
      },
      cultivation: {
        ...save.heroine.cultivation,
        progress: save.heroine.cultivation.progress + progressDelta,
        resources,
      },
      growth: {
        ...save.heroine.growth,
        currentActivity: {
          ...save.heroine.growth.currentActivity,
          section: task.kind === 'fishing' || task.kind === 'resource_gathering' || task.kind === 'world_explore' ? 'life' : task.kind === 'art_practice' ? 'arts' : 'cultivation',
          operationId: task.id,
          label: task.label,
          phase: 'cooldown',
          lastResolvedAtIso: nowIso(),
        },
        condition: {
          ...save.heroine.growth.condition,
          stamina,
          fatigue,
          moodTag: task.kind === 'rest' ? '缓和' : '被离线安排后不满',
        },
        cultivationTrack: {
          ...save.heroine.growth.cultivationTrack,
          progress: save.heroine.growth.cultivationTrack.progress + progressDelta,
        },
        fishing:
          task.kind === 'fishing'
            ? {
                ...save.heroine.growth.fishing,
                fishCaughtTotal: save.heroine.growth.fishing.fishCaughtTotal + (rewards.鱼获 || 0),
                proficiency: save.heroine.growth.fishing.proficiency + (rewards.钓鱼熟练度 || 0),
                journal: [`离线钓鱼 ${hours} 小时，鱼获 ${rewards.鱼获 || 0}`, ...save.heroine.growth.fishing.journal].slice(0, 20),
              }
            : save.heroine.growth.fishing,
      },
    },
  };
}

export function resolveOfflineIdle(save: GameSave, now = nowIso()): ResolvedGameplayAction {
  if (!save.offlineIdle.enabled) throw new Error('离线挂机未开启。');
  const assignment = save.offlineIdle.assignments[0];
  if (!assignment) throw new Error('尚未安排离线挂机任务。');
  const task = OFFLINE_IDLE_TASKS.find(item => item.id === assignment.taskId);
  if (!task) throw new Error('离线挂机任务不存在。');
  const hours = elapsedHours(save.offlineIdle.lastSettledAtIso, now, Math.min(save.offlineIdle.maxSettleHours, task.maxHours));
  if (hours <= 0) throw new Error('离线时间不足 1 小时，暂不结算。');

  const rewards = scaleRewards(task, hours);
  const startedAtIso = save.offlineIdle.lastSettledAtIso;
  let nextSave = applyOfflineRewards(save, rewards, task, hours);
  const logEntry: OfflineIdleSettlementLogEntry = {
    id: createId('offline-log'),
    taskId: task.id,
    label: task.label,
    hours,
    rewards,
    startedAtIso,
    settledAtIso: now,
    publicOperation: task.publicOperation,
  };

  nextSave = {
    ...nextSave,
    offlineIdle: {
      ...nextSave.offlineIdle,
      lastSettledAtIso: now,
      settlementLog: [logEntry, ...nextSave.offlineIdle.settlementLog].slice(0, 40),
    },
    money: {
      ...nextSave.money,
      ledger: [
        {
          id: createId('money'),
          kind: 'offline' as const,
          label: `离线挂机：${task.label}`,
          amount: 0,
          createdAtIso: now,
        },
        ...nextSave.money.ledger,
      ].slice(0, 120),
    },
  };

  const publicOperation = `${task.publicOperation}现实离线约 ${hours} 小时，她被持续安排执行“${task.label}”。`;
  const factPacket: ActionFactPacket = {
    actionId: `offline_${task.id}`,
    section: task.kind === 'art_practice' ? 'arts' : task.kind === 'cultivation' ? 'cultivation' : 'life',
    publicOperation,
    resultSummary: `离线挂机 ${hours} 小时，已登记收益与疲劳。`,
    stateDelta: {
      离线小时: hours,
      ...rewards,
      体力: nextSave.heroine.growth.condition.stamina,
      疲劳: nextSave.heroine.growth.condition.fatigue,
    },
    frontendResult: {
      outcome: 'success',
      rewards,
      notes: [
        '现实时间离线结算已完成。',
        '正文应写她上线后的反应，可以抱怨被安排干活、吐槽没良心或表达委屈。',
        '已登记收益不要重复写入 <gain>。',
      ],
    },
    performanceHint: {
      expression: task.kind === 'rest' ? '放松' : '不满',
      action: task.label,
      portrait: nextSave.heroine.display.formalPoseId,
      chibi: task.kind === 'rest' ? 'idle' : 'tired',
      scene: nextSave.heroine.display.sceneLabel,
    },
    debugOnly: true,
  };

  return {
    save: recordOfflineOperation(nextSave, {
      actionType: 'OFFLINE_IDLE_SETTLE',
      label: `离线挂机：${task.label}`,
      detail: `现实离线 ${hours} 小时。`,
      section: '生活',
      publicOperation,
      factPacketPreview: JSON.stringify(factPacket, null, 2),
    }),
    publicOperation,
    factPacket,
  };
}
