import type { ActionFactPacket, EmbeddedContextBlock, GameSave, HundredArtId } from './types';
import { getArtLabel, HUNDRED_ART_IDS } from './growthGameplay';

interface ArtPromptRuleDefinition {
  artId: HundredArtId;
  tagName: string;
  index: number;
  recipeKind: string;
  outputCategory: string;
  yamlText: string;
}

function gameplayRuleBlock(
  id: string,
  tagName: string,
  index: number,
  label: string,
  yamlText: string,
  slot: EmbeddedContextBlock['slot'],
  priority: number,
  matchReason: string,
): EmbeddedContextBlock {
  return {
    id,
    kind: 'gameplay_rule',
    slot,
    tagName,
    wrapTag: `${tagName}_idx${index}`,
    index,
    label,
    yamlText,
    priority,
    matchReason,
    source: 'built_in',
  };
}

function inferArtFromAction(actionId: string, publicOperation: string): HundredArtId | null {
  const recipeMatch = actionId.match(/^recipe_(.+?)_/);
  if (recipeMatch && (HUNDRED_ART_IDS as string[]).includes(recipeMatch[1])) return recipeMatch[1] as HundredArtId;
  const suffix = actionId.replace(/^learn_/, '').replace(/^practice_/, '');
  if ((HUNDRED_ART_IDS as string[]).includes(suffix)) return suffix as HundredArtId;

  const text = `${actionId}\n${publicOperation}`;
  const keywordMap: Array<[HundredArtId, RegExp]> = [
    ['alchemy', /炼丹|丹方|丹药|丹炉/],
    ['forging', /炼器|器图|法宝|灵器|锻造/],
    ['formation', /阵法|阵图|阵盘|阵旗|布阵/],
    ['talisman', /符箓|符法|符纸|灵墨|制符/],
    ['medicine', /医术|医方|疗伤|解毒|诊治/],
    ['beast_taming', /驭兽|兽谱|灵兽|契约|喂养/],
    ['puppet', /傀儡|傀儡图谱|傀儡件|机关/],
    ['herbology', /种植|采药|灵田|种子|药材/],
  ];
  return keywordMap.find(([, pattern]) => pattern.test(text))?.[0] || null;
}

function isFishingAction(actionId: string, publicOperation: string): boolean {
  return /fishing|钓鱼|鱼获|鱼竿|鱼饵|观水|抛竿/.test(`${actionId}\n${publicOperation}`);
}

function createRuntimeRuleBlock(save: GameSave, factPacket?: ActionFactPacket): EmbeddedContextBlock {
  const result = factPacket?.frontendResult;
  const operation = factPacket?.publicOperation || save.heroine.growth.currentActivity.label || '本轮操作';
  return gameplayRuleBlock(
    'gameplay_art_runtime_rule',
    'gameplay_art_runtime_rule',
    120,
    '玩法规则：百艺与钓鱼结算约束',
    [
      '百艺与钓鱼结算约束:',
      `  本轮操作: ${operation}`,
      `  本轮成败: ${result?.outcome || '以本轮结算记录为准'}`,
      `  自然成功率: ${result?.naturalSuccessRate ?? result?.successRate ?? '以本轮结算记录为准'}`,
      `  最终成功率: ${result?.successRate ?? '以本轮结算记录为准'}`,
      `  是否补材: ${result?.materialPurchased ? '是' : '否'}`,
      `  是否补满: ${result?.paidSupplement ? '是' : '否'}`,
      '  叙事边界:',
      '    - 每次回复只对应一次操作结果，不把一次按钮操作扩写成多轮连续结算。',
      '    - 成败、消耗、奖励、补材、补满、成功率、熟练度变化均承认本轮结算记录。',
      '    - 可解释为什么会成或为什么会失败，但不重新判定、不额外补发已登记奖励。',
      '    - 材料和工具只按本轮结算记录中的已选项描写；缺材购买只作为现实资金投放后的到位材料处理。',
      '    - 已登记奖励不要写入隐藏获得；只有结算记录之外的新发现、新配方、新传闻或额外物品才写隐藏获得。',
      '  新配方记录:',
      '    - 出现丹方、器图、阵图、符法、医方、兽谱、傀儡图谱、种植图谱时，必须同步写产物与需求。',
      '    - 需求要写分类、名称、数量、单位、品级、品质或工具门槛，方便后续制作。',
      '    - 残缺配方可以出现，但需明确缺失内容，不能直接当作可执行配方。',
    ].join('\n'),
    'runtime_context',
    960,
    '百艺或钓鱼操作命中时注入',
  );
}

