function createArtRuleBlock(artId: HundredArtId, save: GameSave): EmbeddedContextBlock {
  const definition = ART_PROMPT_RULES[artId];
  const art = save.heroine.growth.arts[artId];
  return gameplayRuleBlock(
    `gameplay_${artId}_rule`,
    definition.tagName,
    definition.index,
    `玩法规则：${getArtLabel(artId)}`,
    [
      definition.yamlText,
      '本局百艺状态:',
      `  名称: ${art.label}`,
      `  是否习得: ${art.learned ? '是' : '否'}`,
      `  阶段: ${art.stage}`,
      `  熟练度: ${art.proficiency}`,
      `  已知${definition.recipeKind}: ${art.knownRecipes.length ? art.knownRecipes.join('、') : '无'}`,
      `  推荐工具: ${art.toolLabel}`,
      `  主要产出分类: ${definition.outputCategory}`,
    ].join('\n'),
    'world_info_after',
    935,
    `${getArtLabel(artId)}操作命中时注入`,
  );
}

