export function buildGameplayPromptRuleBlocks(
  save: GameSave,
  publicOperation: string,
  factPacket?: ActionFactPacket,
): EmbeddedContextBlock[] {
  const actionId = factPacket?.actionId || '';
  const blocks: EmbeddedContextBlock[] = [];
  const artId = inferArtFromAction(actionId, publicOperation);
  const fishing = isFishingAction(actionId, publicOperation);

  if (!artId && !fishing) return blocks;
  blocks.push(createRuntimeRuleBlock(save, factPacket));
  if (artId) blocks.push(createArtRuleBlock(artId, save));
  if (fishing) blocks.push(createFishingRuleBlock(save, factPacket));
  return blocks;
}
