import {
  PROJECT_NAME,
  SAVE_SCHEMA_VERSION,
  SAVE_VARIABLE_KEY,
  type DebugPacket,
  type GameMessage,
  type GameSave,
  type OperationLogEntry,
} from './types';
import { createInitialHeroineState, normalizeHeroineState } from './heroine';
import {
  createInitialMingyueMemoryState,
  createInitialPlayerAnalysisState,
  normalizeMingyueMemoryState,
  normalizePlayerAnalysisState,
} from './playerAnalysis';
import { createInitialTimestampState, normalizeTimestampState } from './clock';
import { createInitialWorldbookState, normalizeWorldbookState } from './worldbook';
import { createInitialWorldWorkshopState, normalizeWorldWorkshopState } from './worldWorkshop';
import { createInitialWorldNetworkState, normalizeWorldNetworkState } from './worldNetwork';
import { createInitialOnlineRealmState, normalizeOnlineRealmState } from './onlineRealm';
import { createInitialInventoryState, normalizeInventoryState } from './inventory';
import { createInitialOfflineIdleState, normalizeOfflineIdleState } from './offlineIdle';

let fallbackSave: GameSave | null = null;

export function nowIso(): string {
  return new Date().toISOString();
}

export function createId(prefix: string): string {
  const randomId =
    typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function'
      ? crypto.randomUUID()
      : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
  return `${prefix}-${randomId}`;
}

function cloneSave(save: GameSave): GameSave {
  return JSON.parse(JSON.stringify(save)) as GameSave;
}

export function createInitialSchedule() {
  return [
    { id: 'morning', label: '晨间' },
    { id: 'daytime', label: '白日' },
    { id: 'night', label: '夜间' },
  ];
}

export function createInitialGameSave(): GameSave {
  const createdAtIso = nowIso();
  const saveId = createId('save');
  return {
    schemaVersion: SAVE_SCHEMA_VERSION,
    saveId,
    saveName: `${PROJECT_NAME} 存档`,
    stage: 'empty',
    createdAtIso,
    updatedAtIso: createdAtIso,
    timestamps: createInitialTimestampState(createdAtIso),
    money: {
      balance: 10000000,
      spentTotal: 0,
      ledger: [],
    },
    heroine: createInitialHeroineState(),
    inventory: createInitialInventoryState(),
    playerAnalysis: createInitialPlayerAnalysisState(),
    mingyueMemory: createInitialMingyueMemoryState(),
    schedule: createInitialSchedule(),
    messages: [],
    operationLog: [],
    analysisLog: [],
    worldbook: createInitialWorldbookState(`${PROJECT_NAME}_${saveId}`),
    worldWorkshop: createInitialWorldWorkshopState(),
    worldNetwork: createInitialWorldNetworkState(),
    onlineRealm: createInitialOnlineRealmState(),
    offlineIdle: createInitialOfflineIdleState(createdAtIso),
    lastStoryFeedbackMeta: undefined,
    debug: {
      errors: [],
      packets: [],
    },
  };
}

function normalizeString(value: unknown, fallback = ''): string {
  return typeof value === 'string' ? value : fallback;
}

export function normalizeGameSave(raw: unknown): GameSave {
  if (!raw || typeof raw !== 'object') throw Error('导入内容不是有效存档。');
  const candidate = raw as Partial<GameSave>;
  if (candidate.schemaVersion !== SAVE_SCHEMA_VERSION || !candidate.saveId) throw Error('存档版本不匹配。');

  const fallback = createInitialGameSave();
  return {
    ...fallback,
    ...candidate,
    schemaVersion: SAVE_SCHEMA_VERSION,
    saveId: normalizeString(candidate.saveId, fallback.saveId),
    saveName: normalizeString(candidate.saveName, fallback.saveName),
    stage: candidate.stage || fallback.stage,
    createdAtIso: normalizeString(candidate.createdAtIso, fallback.createdAtIso),
    updatedAtIso: normalizeString(candidate.updatedAtIso, nowIso()),
    timestamps: normalizeTimestampState(candidate.timestamps),
    money: {
      balance: Number.isFinite(candidate.money?.balance) ? Number(candidate.money?.balance) : fallback.money.balance,
      spentTotal: Number.isFinite(candidate.money?.spentTotal) ? Number(candidate.money?.spentTotal) : 0,
      ledger: Array.isArray(candidate.money?.ledger) ? candidate.money!.ledger : [],
    },
    heroine: normalizeHeroineState(candidate.heroine),
    inventory: normalizeInventoryState(candidate.inventory),
    playerAnalysis: normalizePlayerAnalysisState(candidate.playerAnalysis),
    mingyueMemory: normalizeMingyueMemoryState(candidate.mingyueMemory),
    schedule: Array.isArray(candidate.schedule) && candidate.schedule.length ? candidate.schedule : fallback.schedule,
    messages: Array.isArray(candidate.messages) ? candidate.messages : [],
    operationLog: Array.isArray(candidate.operationLog) ? candidate.operationLog : [],
    analysisLog: Array.isArray(candidate.analysisLog) ? candidate.analysisLog : [],
    worldbook: normalizeWorldbookState(candidate.worldbook, `${PROJECT_NAME}_${candidate.saveId || fallback.saveId}`),
    worldWorkshop: normalizeWorldWorkshopState(candidate.worldWorkshop),
    worldNetwork: normalizeWorldNetworkState(candidate.worldNetwork),
    onlineRealm: normalizeOnlineRealmState(candidate.onlineRealm),
    offlineIdle: normalizeOfflineIdleState(candidate.offlineIdle, candidate.createdAtIso || fallback.createdAtIso),
    lastStoryFeedbackMeta: candidate.lastStoryFeedbackMeta,
    debug: {
      lastAction: candidate.debug?.lastAction,
      errors: Array.isArray(candidate.debug?.errors) ? candidate.debug!.errors : [],
      packets: Array.isArray(candidate.debug?.packets) ? candidate.debug!.packets : [],
    },
  };
}

function readChatVariableSave(): GameSave | null {
  if (typeof getVariables !== 'function') return fallbackSave;
  const variables = getVariables({ type: 'chat' });
  const stored = variables[SAVE_VARIABLE_KEY];
  const parsed = typeof stored === 'string' ? JSON.parse(stored) : stored;
  return parsed ? normalizeGameSave(parsed) : null;
}

export function loadGameSave(): GameSave {
  try {
    const existing = readChatVariableSave();
    if (existing) return existing;
  } catch {
    // Broken save data is handled from the debug panel after a clean save boots.
  }
  return persistGameSave(createInitialGameSave());
}

export function persistGameSave(save: GameSave): GameSave {
  const nextSave = cloneSave({
    ...save,
    updatedAtIso: nowIso(),
  });
  fallbackSave = nextSave;

  if (typeof getVariables === 'function' && typeof replaceVariables === 'function') {
    const variables = getVariables({ type: 'chat' });
    variables[SAVE_VARIABLE_KEY] = nextSave;
    replaceVariables(variables, { type: 'chat' });
  }

  return nextSave;
}

export function exportGameSaveText(save: GameSave): string {
  return JSON.stringify(
    {
      kind: 'cultivation_fairy_girlfriend_save',
      exportedAtIso: nowIso(),
      save,
    },
    null,
    2,
  );
}

export function importGameSaveText(rawText: string): GameSave {
  const parsed = JSON.parse(rawText);
  return normalizeGameSave(parsed?.save || parsed);
}

export function recordMessage(save: GameSave, kind: GameMessage['kind'], role: GameMessage['role'], text: string): GameSave {
  return {
    ...save,
    messages: [
      ...save.messages,
      {
        id: createId('msg'),
        kind,
        role,
        text,
        createdAtIso: nowIso(),
      },
    ],
  };
}

export function recordOperation(save: GameSave, entry: Omit<OperationLogEntry, 'id' | 'createdAtIso'>): GameSave {
  return {
    ...save,
    operationLog: [
      {
        ...entry,
        id: createId('op'),
        createdAtIso: nowIso(),
      },
      ...save.operationLog,
    ].slice(0, 80),
  };
}

export function recordDebugError(save: GameSave, error: unknown): GameSave {
  const text = error instanceof Error ? error.message : String(error);
  return {
    ...save,
    debug: {
      ...save.debug,
      errors: [text, ...save.debug.errors].slice(0, 30),
    },
  };
}

export function recordDebugPacket(save: GameSave, packet: Omit<DebugPacket, 'createdAtIso'>): GameSave {
  return {
    ...save,
    debug: {
      ...save.debug,
      packets: [
        {
          ...packet,
          createdAtIso: nowIso(),
        },
        ...save.debug.packets,
      ].slice(0, 20),
    },
  };
}
