import type {
  WorldWorkshopContentKind,
  WorldWorkshopModule,
  WorldWorkshopModuleEntry,
  WorldWorkshopModuleSummary,
  WorldWorkshopModuleSubmission,
  WorldWorkshopState,
  WorldWorkshopUpdateNotice,
} from './types';

export const WORLD_WORKSHOP_API_BASE = 'https://sanmingyue.zeabur.app';
export const WORLD_WORKSHOP_AUTH_TOKEN_KEY = 'workshop-auth-token';

export interface WorldWorkshopSearchParams {
  page?: number;
  pageSize?: number;
  kind?: WorldWorkshopContentKind;
  search?: string;
  tag?: string;
  officialOnly?: boolean;
  reviewStatus?: 'pending_review' | 'approved' | 'rejected';
}

export interface WorldWorkshopSearchResponse {
  modules: WorldWorkshopModuleSummary[];
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
}

function timestamp(): string {
  return new Date().toISOString();
}

function createNotice(input: Omit<WorldWorkshopUpdateNotice, 'id' | 'createdAtIso'>): WorldWorkshopUpdateNotice {
  return {
    id: `world-update-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`,
    createdAtIso: timestamp(),
    ...input,
  };
}

function safeArray<T>(value: unknown): T[] {
  return Array.isArray(value) ? (value as T[]) : [];
}

function getHostStorage(): Storage | null {
  if (typeof window === 'undefined') return null;
  try {
    return window.parent?.localStorage || window.localStorage;
  } catch {
    return null;
  }
}

export function getWorldWorkshopAuthToken(): string | null {
  try {
    return getHostStorage()?.getItem(WORLD_WORKSHOP_AUTH_TOKEN_KEY) || null;
  } catch {
    return null;
  }
}

async function worldWorkshopRequest<T>(
  path: string,
  opts: RequestInit = {},
  endpointBase = WORLD_WORKSHOP_API_BASE,
): Promise<T> {
  const token = getWorldWorkshopAuthToken();
  const headers: Record<string, string> = {
    ...((opts.headers as Record<string, string> | undefined) || {}),
  };

  if (token) headers.Authorization = `Bearer ${token}`;
  if (!(opts.body instanceof FormData)) headers['Content-Type'] = 'application/json';

  const response = await fetch(`${endpointBase}${path}`, {
    ...opts,
    headers,
  });

  if (!response.ok) {
    const data = await response.json().catch(() => ({ error: `HTTP ${response.status}` }));
    throw new Error(data.error || `世界工坊请求失败：${response.status}`);
  }

  return response.json() as Promise<T>;
}

export function createInitialWorldWorkshopState(): WorldWorkshopState {
  return {
    endpointBase: WORLD_WORKSHOP_API_BASE,
    selectedModuleIds: [],
    installedModules: [],
    entryCache: [],
    searchResults: [],
    versionHistory: [],
    updateNotices: [],
    dependencyWarnings: [],
    conflictWarnings: [],
    lastScanText: '',
  };
}

export function normalizeWorldWorkshopState(raw: unknown): WorldWorkshopState {
  const fallback = createInitialWorldWorkshopState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<WorldWorkshopState>;
  return {
    endpointBase: typeof candidate.endpointBase === 'string' ? candidate.endpointBase : fallback.endpointBase,
    selectedModuleIds: safeArray<string>(candidate.selectedModuleIds).filter(Boolean),
    installedModules: safeArray<WorldWorkshopModuleSummary>(candidate.installedModules),
    entryCache: safeArray<WorldWorkshopModuleEntry>(candidate.entryCache),
    searchResults: safeArray<WorldWorkshopModuleSummary>(candidate.searchResults),
    versionHistory: safeArray<WorldWorkshopModule>(candidate.versionHistory),
    updateNotices: safeArray<WorldWorkshopUpdateNotice>(candidate.updateNotices),
    dependencyWarnings: safeArray<string>(candidate.dependencyWarnings),
    conflictWarnings: safeArray<string>(candidate.conflictWarnings),
    lastSearchTotal: Number.isFinite(candidate.lastSearchTotal) ? Number(candidate.lastSearchTotal) : undefined,
    lastSearchAtIso: typeof candidate.lastSearchAtIso === 'string' ? candidate.lastSearchAtIso : undefined,
    lastDownloadedAtIso:
      typeof candidate.lastDownloadedAtIso === 'string' ? candidate.lastDownloadedAtIso : undefined,
    lastSubmissionId: typeof candidate.lastSubmissionId === 'string' ? candidate.lastSubmissionId : undefined,
    lastScanText: typeof candidate.lastScanText === 'string' ? candidate.lastScanText : '',
    lastError: typeof candidate.lastError === 'string' ? candidate.lastError : undefined,
  };
}

export async function searchWorldWorkshopModules(
  params: WorldWorkshopSearchParams = {},
  endpointBase = WORLD_WORKSHOP_API_BASE,
): Promise<WorldWorkshopSearchResponse> {
  const searchParams = new URLSearchParams();
  if (params.page) searchParams.set('page', String(params.page));
  if (params.pageSize) searchParams.set('page_size', String(params.pageSize));
  if (params.kind) searchParams.set('kind', params.kind);
  if (params.search) searchParams.set('search', params.search);
  if (params.tag) searchParams.set('tag', params.tag);
  if (params.officialOnly !== undefined) searchParams.set('official_only', String(params.officialOnly));
  if (params.reviewStatus) searchParams.set('review_status', params.reviewStatus);

  const query = searchParams.toString();
  return worldWorkshopRequest(`/api/cultivation-world/modules${query ? `?${query}` : ''}`, {}, endpointBase);
}

export async function downloadWorldWorkshopModule(
  moduleId: string,
  version?: string,
  endpointBase = WORLD_WORKSHOP_API_BASE,
): Promise<WorldWorkshopModule> {
  const query = version ? `?version=${encodeURIComponent(version)}` : '';
  return worldWorkshopRequest(
    `/api/cultivation-world/modules/${encodeURIComponent(moduleId)}/download${query}`,
    {},
    endpointBase,
  );
}

export async function submitWorldWorkshopModuleForReview(
  submission: WorldWorkshopModuleSubmission,
  endpointBase = WORLD_WORKSHOP_API_BASE,
): Promise<{ submissionId: string; reviewStatus: 'pending_review' }> {
  return worldWorkshopRequest('/api/cultivation-world/submissions', {
    method: 'POST',
    body: JSON.stringify(submission),
  }, endpointBase);
}

export function validateWorldWorkshopModule(module: WorldWorkshopModule): WorldWorkshopModule {
  if (module.content?.schema !== 'cultivation_world_module_v1') {
    throw new Error('世界模块 schema 不匹配。');
  }
  const reviewStatus = module.reviewStatus || 'approved';
  if (reviewStatus !== 'approved') {
    throw new Error('世界模块尚未通过审核，不能安装到公共世界。');
  }
  if (!module.id || !module.version || !module.title) {
    throw new Error('世界模块缺少必要标识。');
  }
  return {
    ...module,
    reviewStatus,
    tags: safeArray<string>(module.tags),
    content: {
      ...module.content,
      dependencies: safeArray<string>(module.content.dependencies),
      entries: safeArray<WorldWorkshopModuleEntry>(module.content.entries).map(entry => ({
        ...entry,
        sourceModuleId: entry.sourceModuleId || module.id,
        yamlText: typeof entry.yamlText === 'string' ? entry.yamlText : '',
        tags: safeArray<string>(entry.tags),
      })),
    },
  };
}

function detectDependencyWarnings(state: WorldWorkshopState, module: WorldWorkshopModule): string[] {
  const installedIds = new Set(state.installedModules.map(item => item.id));
  return (module.content.dependencies || [])
    .filter(dependencyId => !installedIds.has(dependencyId) && dependencyId !== module.id)
    .map(dependencyId => `${module.title} 依赖 ${dependencyId}，当前尚未安装。`);
}

function detectConflictWarnings(state: WorldWorkshopState, module: WorldWorkshopModule): string[] {
  const nextEntryIds = new Set(module.content.entries.map(entry => entry.id));
  const conflicts = state.entryCache.filter(entry => entry.sourceModuleId !== module.id && nextEntryIds.has(entry.id));
  return conflicts.map(entry => `${module.title} 的条目 ${entry.id} 与已安装模块 ${entry.sourceModuleId || 'unknown'} 冲突。`);
}

function summarizeModuleDiff(previousEntries: WorldWorkshopModuleEntry[], nextEntries: WorldWorkshopModuleEntry[]): string {
  const previousById = new Map(previousEntries.map(entry => [entry.id, entry]));
  const nextById = new Map(nextEntries.map(entry => [entry.id, entry]));
  const added = nextEntries.filter(entry => !previousById.has(entry.id)).map(entry => entry.label || entry.id);
  const removed = previousEntries.filter(entry => !nextById.has(entry.id)).map(entry => entry.label || entry.id);
  const changed = nextEntries
    .filter(entry => {
      const previous = previousById.get(entry.id);
      return previous && (previous.yamlText !== entry.yamlText || previous.label !== entry.label || previous.kind !== entry.kind);
    })
    .map(entry => entry.label || entry.id);
  const lines = [
    added.length ? `新增 ${added.length}: ${added.slice(0, 6).join('、')}` : '',
    changed.length ? `变更 ${changed.length}: ${changed.slice(0, 6).join('、')}` : '',
    removed.length ? `移除 ${removed.length}: ${removed.slice(0, 6).join('、')}` : '',
  ].filter(Boolean);
  return lines.join('；') || '条目无显著差异。';
}

export function buildWorldWorkshopScanText(state: WorldWorkshopState, moduleIds = state.selectedModuleIds): string {
  const selected = new Set(moduleIds);
  const entries = state.entryCache.filter(entry => selected.has(entry.sourceModuleId || ''));

  const body = entries.length
    ? entries
        .map(
          entry => [
            `  - id: ${entry.id}`,
            `    类型: ${entry.kind}`,
            `    名称: ${entry.label}`,
            `    来源模块: ${entry.sourceModuleId}`,
            `    标签: [${entry.tags.join(', ')}]`,
            '    内容: |',
            ...entry.yamlText.split('\n').map(line => `      ${line}`),
          ].join('\n'),
        )
        .join('\n')
    : '  - 暂无已选择的服务器世界模块';

  return `<worldworkshop_idx300>\n世界模块:\n${body}\n</worldworkshop_idx300>`;
}

export function installWorldWorkshopModule(state: WorldWorkshopState, module: WorldWorkshopModule): WorldWorkshopState {
  const validated = validateWorldWorkshopModule(module);
  const previousSummary = state.installedModules.find(item => item.id === validated.id);
  const previousFullModule = state.versionHistory.find(item => item.id === validated.id && item.version === previousSummary?.version);
  const previousEntries = state.entryCache.filter(entry => entry.sourceModuleId === validated.id);
  const diffSummary = previousSummary ? summarizeModuleDiff(previousEntries, validated.content.entries) : `首次安装 ${validated.content.entries.length} 条内容。`;
  const dependencyWarnings = detectDependencyWarnings(state, validated);
  const conflictWarnings = detectConflictWarnings(state, validated);
  const notices: WorldWorkshopUpdateNotice[] = [
    createNotice({
      moduleId: validated.id,
      title: validated.title,
      kind: previousSummary ? 'updated' : 'installed',
      fromVersion: previousSummary?.version,
      toVersion: validated.version,
      detail: previousSummary
        ? `世界模块从 ${previousSummary.version} 更新到 ${validated.version}。差异：${diffSummary}`
        : `世界模块 ${validated.version} 已安装。${diffSummary}`,
    }),
    ...dependencyWarnings.map(detail =>
      createNotice({
        moduleId: validated.id,
        title: validated.title,
        kind: 'dependency_warning' as const,
        toVersion: validated.version,
        detail,
      }),
    ),
    ...conflictWarnings.map(detail =>
      createNotice({
        moduleId: validated.id,
        title: validated.title,
        kind: 'conflict' as const,
        toVersion: validated.version,
        detail,
      }),
    ),
  ];
  const installedModules = [
    ...state.installedModules.filter(item => item.id !== validated.id),
    {
      id: validated.id,
      version: validated.version,
      title: validated.title,
      kind: validated.kind,
      tags: validated.tags,
      authorName: validated.authorName,
      description: validated.description,
      updatedAtIso: validated.updatedAtIso,
      reviewStatus: validated.reviewStatus,
      reviewedBy: validated.reviewedBy,
      reviewedAtIso: validated.reviewedAtIso,
    },
  ];
  const entryCache = [
    ...state.entryCache.filter(entry => entry.sourceModuleId !== validated.id),
    ...validated.content.entries,
  ];
  const selectedModuleIds = Array.from(new Set([...state.selectedModuleIds, validated.id]));
  const nextState = {
    ...state,
    selectedModuleIds,
    installedModules,
    entryCache,
    versionHistory: [
      validated,
      ...(previousFullModule ? [previousFullModule] : []),
      ...state.versionHistory.filter(
        item =>
          !(
            item.id === validated.id &&
            (item.version === validated.version || item.version === previousFullModule?.version)
          ),
      ),
    ].slice(0, 80),
    updateNotices: [...notices, ...state.updateNotices].slice(0, 80),
    dependencyWarnings: Array.from(new Set([...dependencyWarnings, ...state.dependencyWarnings])).slice(0, 80),
    conflictWarnings: Array.from(new Set([...conflictWarnings, ...state.conflictWarnings])).slice(0, 80),
    lastDownloadedAtIso: timestamp(),
    lastError: undefined,
  };

  return {
    ...nextState,
    lastScanText: buildWorldWorkshopScanText(nextState),
  };
}

export function buildWorldWorkshopUpdateDigest(state: WorldWorkshopState): string {
  const notices = state.updateNotices.slice(0, 12);
  return [
    '世界模块更新策略:',
    '  自动同步: 搜索服务器已审核模块时，自动下载新增版本并安装。',
    '  更新提示: 每次安装、更新、依赖缺失、冲突和回退都会写入 updateNotices。',
    '  旧版回退: versionHistory 保留旧版本完整模块，可按模块 id 与版本回退。',
    '  差异提示: 更新提示里记录新增、变更、移除条目摘要。',
    '  依赖处理:',
    ...(state.dependencyWarnings.length ? state.dependencyWarnings.slice(0, 8).map(item => `    - ${item}`) : ['    - 暂无依赖缺失']),
    '  冲突处理:',
    ...(state.conflictWarnings.length ? state.conflictWarnings.slice(0, 8).map(item => `    - ${item}`) : ['    - 暂无条目冲突']),
    '  最近提示:',
    ...(notices.length
      ? notices.map(notice => `    - [${notice.kind}] ${notice.title}: ${notice.detail}`)
      : ['    - 暂无更新提示']),
  ].join('\n');
}

export function rollbackWorldWorkshopModule(
  state: WorldWorkshopState,
  moduleId: string,
  targetVersion?: string,
): WorldWorkshopState {
  const candidates = state.versionHistory.filter(item => item.id === moduleId);
  const target = targetVersion
    ? candidates.find(item => item.version === targetVersion)
    : candidates.find(item => item.version !== state.installedModules.find(module => module.id === moduleId)?.version);
  if (!target) throw new Error('没有可回退的世界模块版本。');
  const nextState = installWorldWorkshopModule(state, target);
  return {
    ...nextState,
    updateNotices: [
      createNotice({
        moduleId: target.id,
        title: target.title,
        kind: 'rollback',
        toVersion: target.version,
        detail: `已回退到 ${target.version}。`,
      }),
      ...nextState.updateNotices,
    ].slice(0, 80),
  };
}
