import type { GameSave } from './types';

export function buildDebugReport(save: GameSave) {
  return {
    schemaVersion: save.schemaVersion,
    saveId: save.saveId,
    stage: save.stage,
    updatedAtIso: save.updatedAtIso,
    timestamps: save.timestamps,
    messageCount: save.messages.length,
    operationCount: save.operationLog.length,
    analysisCount: save.analysisLog.length,
    worldbookName: save.worldbook.worldbookName,
    worldWorkshopModuleCount: save.worldWorkshop.installedModules.length,
    invitedSnapshotCount: save.worldNetwork.invitedSnapshots.length,
    activeInvitedSnapshotCount: save.worldNetwork.activeInvitedSnapshotIds.length,
    pendingRewardPackageCount: save.worldNetwork.claimableRewardPackages.filter(item => item.status === 'pending').length,
    tradePackageCount: save.worldNetwork.tradePackages.length,
    onlineRealmRoomId: save.onlineRealm.activeRoomId,
    onlineRealmStatus: save.onlineRealm.roomStatus,
    lastAction: save.debug.lastAction,
    latestError: save.debug.errors[0] || '',
  };
}
