import type { GameSave, HeroineState } from './types';
import { createInitialGrowthState, normalizeGrowthState } from './growthGameplay';
import { nowIso } from './save';

export function createInitialHeroineState(): HeroineState {
  return {
    initialized: false,
    name: '仙子',
    baseProfilePlaceholder: '初始女主人设占位。',
    display: {
      portraitId: 'heroine-placeholder',
      formalPoseId: 'default',
      avatarExpressionId: 'neutral',
      chibiAnimationId: 'idleBreath',
      expression: '平静',
      actionLabel: '等待观测',
      appearanceLabel: '默认立绘占位',
      sceneLabel: '修仙游戏界面',
      bodyStatus: '未初始化',
      emotionStatus: '未初始化',
    },
    cultivation: {
      realm: '未入道',
      progress: 0,
      resources: {
        灵石: 0,
        丹药: 0,
        悟性: 0,
      },
      schedule: [],
      flags: [],
    },
    growth: createInitialGrowthState(),
    dynamicProfile: {
      placeholderText: '女主动态人设占位。',
      sourceLogIds: [],
    },
  };
}

export function normalizeHeroineState(raw: unknown): HeroineState {
  const fallback = createInitialHeroineState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<HeroineState>;
  return {
    ...fallback,
    ...candidate,
    display: {
      ...fallback.display,
      ...candidate.display,
    },
    cultivation: {
      ...fallback.cultivation,
      ...candidate.cultivation,
      resources: {
        ...fallback.cultivation.resources,
        ...(candidate.cultivation?.resources || {}),
      },
      schedule: Array.isArray(candidate.cultivation?.schedule) ? candidate.cultivation!.schedule : [],
      flags: Array.isArray(candidate.cultivation?.flags) ? candidate.cultivation!.flags : [],
    },
    growth: normalizeGrowthState(candidate.growth),
    dynamicProfile: {
      ...fallback.dynamicProfile,
      ...candidate.dynamicProfile,
      sourceLogIds: Array.isArray(candidate.dynamicProfile?.sourceLogIds) ? candidate.dynamicProfile!.sourceLogIds : [],
    },
  };
}

export function initializeHeroine(save: GameSave): GameSave {
  return {
    ...save,
    stage: 'heroine_ready',
    heroine: {
      ...save.heroine,
      initialized: true,
      display: {
        ...save.heroine.display,
        bodyStatus: '占位状态',
        emotionStatus: '占位情绪',
      },
      growth: {
        ...save.heroine.growth,
        condition: {
          ...save.heroine.growth.condition,
          injury: '无',
          moodTag: '平静',
        },
      },
      dynamicProfile: {
        ...save.heroine.dynamicProfile,
        updatedAtIso: save.heroine.dynamicProfile.updatedAtIso || nowIso(),
      },
    },
  };
}

export function updateHeroineDisplay(save: GameSave, label: string): GameSave {
  return {
    ...save,
    heroine: {
      ...save.heroine,
      display: {
        ...save.heroine.display,
        actionLabel: label || save.heroine.display.actionLabel,
      },
    },
  };
}
