import { teleportStyle } from '@util/script';
import App from './App.vue';
import './styles/global.css';
$(() => {
    const parentDoc = window.parent.document;
    const pinia = createPinia();
    let app = null;
    let iframeEl = null;
    let styleDestroy = null;
    let viewportDestroy = null;
    function getParentViewport() {
        const visualViewport = window.parent.visualViewport;
        const fallbackWidth = parentDoc.documentElement.clientWidth || window.parent.innerWidth || window.innerWidth;
        const fallbackHeight = parentDoc.documentElement.clientHeight || window.parent.innerHeight || window.innerHeight;
        return {
            width: Math.max(320, Math.floor(visualViewport?.width || fallbackWidth)),
            height: Math.max(360, Math.floor(visualViewport?.height || fallbackHeight)),
            left: Math.floor(visualViewport?.offsetLeft || 0),
            top: Math.floor(visualViewport?.offsetTop || 0),
        };
    }
    function syncViewportToIframe() {
        if (!iframeEl)
            return;
        const viewport = getParentViewport();
        iframeEl.style.left = `${viewport.left}px`;
        iframeEl.style.top = `${viewport.top}px`;
        iframeEl.style.width = `${viewport.width}px`;
        iframeEl.style.height = `${viewport.height}px`;
    }
    function bindVisualViewport() {
        if (viewportDestroy)
            viewportDestroy();
        const visualViewport = window.parent.visualViewport;
        const update = () => syncViewportToIframe();
        visualViewport?.addEventListener('resize', update);
        visualViewport?.addEventListener('scroll', update);
        window.parent.addEventListener('resize', update);
        window.parent.addEventListener('orientationchange', update);
        viewportDestroy = () => {
            visualViewport?.removeEventListener('resize', update);
            visualViewport?.removeEventListener('scroll', update);
            window.parent.removeEventListener('resize', update);
            window.parent.removeEventListener('orientationchange', update);
        };
        update();
    }
    function unmountClient() {
        if (viewportDestroy) {
            viewportDestroy();
            viewportDestroy = null;
        }
        if (app) {
            app.unmount();
            app = null;
        }
        if (styleDestroy) {
            styleDestroy();
            styleDestroy = null;
        }
        if (iframeEl) {
            iframeEl.remove();
            iframeEl = null;
        }
    }
    function mountAppIntoIframe(iframe) {
        if (app || iframeEl !== iframe)
            return;
        const iframeDoc = iframe.contentDocument;
        if (!iframeDoc?.body)
            return;
        syncViewportToIframe();
        const { destroy } = teleportStyle(iframeDoc.head);
        styleDestroy = destroy;
        app = createApp(App, { onExit: unmountClient }).use(pinia);
        app.mount(iframeDoc.body);
    }
    function mountClient() {
        if (app || iframeEl)
            return;
        const iframe = document.createElement('iframe');
        iframe.setAttribute('script_id', getScriptId());
        iframe.setAttribute('frameborder', '0');
        iframe.setAttribute('title', '我的养成仙子女友');
        iframe.style.cssText = [
            'position:fixed',
            'left:0',
            'top:0',
            'width:100vw',
            'height:100dvh',
            'z-index:99999',
            'border:none',
            'background:#0d1016',
        ].join(';');
        iframe.addEventListener('load', () => mountAppIntoIframe(iframe));
        iframeEl = iframe;
        bindVisualViewport();
        parentDoc.body.appendChild(iframe);
        window.setTimeout(() => mountAppIntoIframe(iframe), 0);
    }
    replaceScriptButtons([{ name: '进入我的养成仙子女友', visible: true }]);
    eventOn(getButtonEvent('进入我的养成仙子女友'), mountClient);
    mountClient();
    $(window).on('pagehide', () => {
        unmountClient();
    });
});
