const DEFAULT_PRESET_ADAPTER: PromptPresetAdapter = 'mingyue_qiuqing_bad_end';

const PROMPT_SLOT_ORDER: Array<{ slot: PromptModuleSlot; label: string }> = [
  { slot: 'world_info_before', label: 'World Info (before) - 角色定义之前' },
  { slot: 'char_description', label: 'Char Description - 角色描述' },
  { slot: 'persona_description', label: 'Persona Description - 玩家描述' },
  { slot: 'char_personality', label: 'Char Personality - 角色性格' },
  { slot: 'scenario', label: 'Scenario - 情景' },
  { slot: 'world_info_after', label: 'World Info (after) - 角色定义之后' },
  { slot: 'runtime_context', label: 'Runtime Context - 本轮运行记录' },
];

function normalizeOperation(input: string): string {
  const trimmed = input.trim();
  return trimmed.startsWith('玩家操作：') ? trimmed : `玩家操作：${trimmed}`;
}

function wrapContextBlock(block: EmbeddedContextBlock): string {
  const tag = block.wrapTag || `${block.tagName}_idx${block.index}`;
  if (block.preserveContent) {
    return [`<${tag}>`, block.yamlText, `</${tag}>`].join('\n');
  }
  return [
    `<${tag}>`,
    `块名: ${block.label}`,
    `模块槽: ${block.slot}`,
    `内容类型: ${block.kind}`,
    `来源: ${block.source}`,
    `用途: ${block.matchReason}`,
    '内容:',
    block.yamlText,
    `</${tag}>`,
  ].join('\n');
}

export function wrapPublicOperationForPrompt(publicOperation: string): string {
  return ['<player_action>', publicOperation, '</player_action>'].join('\n');
}

function wrapPromptSlot(slot: PromptModuleSlot, label: string, promptText: string): string {
  return [`<prompt_slot id="${slot}" label="${label}">`, promptText, '</prompt_slot>'].join('\n');
}

function wrapForMingyueQiuqingBadEnd(slotText: string): string {
  return ['<observed_piece class="设定">', slotText, '</observed_piece>'].join('\n');
}

function createPresetInjection(adapter: PromptPresetAdapter, slotText: string): EmbeddedPromptInjection {
  return {
    position: 'in_chat',
    depth: 0,
    role: 'system',
    content: adapter === 'mingyue_qiuqing_bad_end' ? wrapForMingyueQiuqingBadEnd(slotText) : slotText,
    should_scan: false,
  };
}

function inferWorldbookPlaceholderSlot(entry: { tagName: string; label: string }): PromptModuleSlot {
  const text = `${entry.tagName}\n${entry.label}`;
  if (/玩家/.test(text)) return 'persona_description';
  if (/性格|动态|心境|人设/.test(text)) return 'char_personality';
  if (/角色|女主|老婆|立绘|外观/.test(text)) return 'char_description';
  if (/情景|场景|开局|主线/.test(text)) return 'scenario';
  if (/世界观|境界|规则|修仙/.test(text)) return 'world_info_before';
  return 'world_info_after';
}

function splitSearchText(text: string): string[] {
  return text
    .split(/[\s,，。；;、/|]+/)
    .map(item => item.trim())
    .filter(item => item.length >= 2);
}

function entryMatches(entry: WorldWorkshopModuleEntry, publicOperation: string, sceneLabel: string): boolean {
  const searchText = `${publicOperation}\n${sceneLabel}`;
  const labels = [entry.label, entry.kind, ...entry.tags].filter(Boolean);
  return (
    labels.some(label => searchText.includes(label)) ||
    splitSearchText(entry.yamlText).some(word => searchText.includes(word))
  );
}

