function createWorldModuleBlocks(save: GameSave, publicOperation: string): EmbeddedContextBlock[] {
  const sceneLabel = save.heroine.display.sceneLabel;
  const selectedIds = new Set(save.worldWorkshop.selectedModuleIds);
  const selectedEntries = save.worldWorkshop.entryCache.filter(entry => selectedIds.has(entry.sourceModuleId || ''));
  const matchedEntries = selectedEntries.filter(entry => entryMatches(entry, publicOperation, sceneLabel));
  const entries = matchedEntries.length ? matchedEntries : selectedEntries.slice(0, 6);

  return entries.map((entry, offset) => ({
    id: `world_module_${entry.sourceModuleId || 'unknown'}_${entry.id}`,
    kind: 'world_module',
    slot: 'world_info_after',
    tagName: 'world_module',
    index: 300 + offset,
    label: entry.label,
    priority: matchedEntries.includes(entry) ? 880 - offset : 620 - offset,
    matchReason: matchedEntries.includes(entry) ? '命中本轮操作或当前场景' : '已启用世界模块兜底',
    source: 'workshop',
    yamlText: [
      '世界模块:',
      `  id: ${entry.id}`,
      `  类型: ${entry.kind}`,
      `  名称: ${entry.label}`,
      `  来源模块: ${entry.sourceModuleId || ''}`,
      `  标签: [${entry.tags.join(', ')}]`,
      '  内容: |',
      ...entry.yamlText.split('\n').map(line => `    ${line}`),
    ].join('\n'),
  }));
}

