function isCriticalPromptBlock(block: EmbeddedContextBlock): boolean {
  return block.priority >= 900 || block.id === 'frontend_rule' || block.id.startsWith('action_fact_');
}

function selectPromptBlocks(blocks: EmbeddedContextBlock[], maxBlocks: number): EmbeddedContextBlock[] {
  const sorted = [...blocks].sort((left, right) => right.priority - left.priority);
  const critical = sorted.filter(isCriticalPromptBlock);
  const criticalIds = new Set(critical.map(block => block.id));
  const optional = sorted.filter(block => !criticalIds.has(block.id));
  const selected = [...critical, ...optional.slice(0, Math.max(0, maxBlocks - critical.length))];
  return selected.sort((left, right) => right.priority - left.priority);
}

export function buildEmbeddedPromptAssembly(save: GameSave, request: PromptComposeRequest): EmbeddedPromptAssembly {
  const adapter = request.adapter || DEFAULT_PRESET_ADAPTER;
  const publicOperation = normalizeOperation(request.publicOperation);
  const blocks = [
    createFrontendRuleBlock(publicOperation),
    createHeroineProfileBlock(save),
    ...[createMingyueDynamicProfileBlock(save, publicOperation)].filter((block): block is EmbeddedContextBlock => Boolean(block)),
    ...[createMingyueNeuralChainBlock(save, publicOperation)].filter((block): block is EmbeddedContextBlock => Boolean(block)),
    createHeroineStateBlock(save),
    createInventoryStateBlock(save),
    createEquipmentWardrobeBlock(save),
    ...[createPlayerAnalysisBlock(save, publicOperation)].filter((block): block is EmbeddedContextBlock => Boolean(block)),
    ...FIXED_WORLDVIEW_BLOCKS,
    ...buildGameplayPromptRuleBlocks(save, publicOperation, request.factPacket),
    ...createWorldbookPlaceholderBlocks(save),
    ...createWorldModuleBlocks(save, publicOperation),
    ...createInvitedSnapshotBlocks(save),
    ...[buildKeywordScanBlock(save, publicOperation)].filter((block): block is EmbeddedContextBlock => Boolean(block)),
    ...(request.factPacket ? [createActionFactBlock(request.factPacket)] : []),
    ...[createOnlineRealmBlock(save)].filter((block): block is EmbeddedContextBlock => Boolean(block)),
  ];
  const selectedBlocks = selectPromptBlocks(blocks, request.maxBlocks || 24);

  const modules = PROMPT_SLOT_ORDER.map(({ slot, label }) => {
    const slotBlocks = selectedBlocks.filter(block => block.slot === slot);
    if (!slotBlocks.length) return null;
    const promptText = wrapPromptSlot(slot, label, slotBlocks.map(wrapContextBlock).join('\n\n'));
    const inject = createPresetInjection(adapter, promptText);
    return {
      slot,
      label,
      blocks: slotBlocks,
      promptText,
      injectionText: inject.content,
      inject,
    };
  }).filter((module): module is NonNullable<typeof module> => Boolean(module));
  const injects: EmbeddedPromptInjection[] = modules.map(module => module.inject);
  const promptText = modules.map(module => module.promptText).join('\n\n');
  const injectionText = modules.map(module => module.injectionText).join('\n\n');

  return {
    adapter,
    publicOperation,
    modules,
    blocks: selectedBlocks,
    promptText,
    injectionText,
    injects,
    maxChatHistory: request.maxChatHistory || 'all',
    debugSummary: selectedBlocks.map(block => `[${block.slot}] ${block.label}: ${block.matchReason}`).join('\n'),
  };
}

export function buildTavernPresetGenerateConfig(save: GameSave, request: PromptComposeRequest) {
  const assembly = buildEmbeddedPromptAssembly(save, request);
  return {
    user_input: wrapPublicOperationForPrompt(assembly.publicOperation),
    injects: assembly.injects,
    max_chat_history: assembly.maxChatHistory,
  };
}

export function buildPromptInjectPreview(save: GameSave, publicOperation: string): string {
  const assembly = buildEmbeddedPromptAssembly(save, {
    task: 'story',
    publicOperation,
  });
  return [
    '本轮 generate 注入预览:',
    `  adapter: ${assembly.adapter}`,
    `  user_input: ${wrapPublicOperationForPrompt(assembly.publicOperation).replace(/\n/g, '\\n')}`,
    `  injects: ${assembly.injects.length}`,
    `  max_chat_history: ${assembly.maxChatHistory}`,
    '',
    '命中块:',
    assembly.blocks
      .map(
        block =>
          `  - <${block.wrapTag || `${block.tagName}_idx${block.index}`}> [${block.slot}] ${block.label} / ${block.matchReason}`,
      )
      .join('\n'),
    '',
    '模块摘要:',
    assembly.modules.map(module => `  - ${module.slot}: ${module.blocks.length} 块`).join('\n'),
    '',
    '完整注入文本:',
    assembly.injectionText,
  ].join('\n');
}

export function buildEmbeddedWorldbookPreview(save: GameSave): string {
  return [
    '固定世界观:',
    buildFixedWorldviewPreview(),
    '内置设定占位:',
    save.worldbook.entries.map(wrapWorldbookPlaceholder).join('\n\n'),
    save.worldWorkshop.lastScanText,
  ]
    .filter(Boolean)
    .join('\n\n');
}
