export function buildPublicOperation(userInput: string): string {
  return userInput.startsWith('玩家操作：') ? userInput : `玩家操作：${userInput}`;
}

function buildPlaceholderFactPacket(save: GameSave, publicOperation: string): ActionFactPacket {
  return {
    actionId: 'free_story_input',
    section: 'cultivation',
    publicOperation,
    resultSummary: '自由正文操作占位，正式结算由对应操作写入。',
    stateDelta: {},
    performanceHint: {
      expression: save.heroine.display.expression,
      action: save.heroine.display.actionLabel,
      portrait: save.heroine.display.formalPoseId,
      chibi: save.heroine.display.chibiAnimationId,
      scene: save.heroine.display.sceneLabel,
    },
    debugOnly: true,
  };
}

export function buildGenerationInputPacketWithFact(
  save: GameSave,
  task: GenerateTaskKind,
  publicOperation: string,
  factPacket: ActionFactPacket,
): string {
  const embeddedPrompt = buildEmbeddedPromptAssembly(save, {
    task,
    publicOperation,
    factPacket,
  });
  return JSON.stringify(
    {
      task,
      publicOperation,
      taggedUserInput: wrapPublicOperationForPrompt(publicOperation),
      rule:
        '正文公开输入只写本轮操作；结算步骤、状态旧值新值和演出建议只进入隐藏结算记录；已登记奖励不重复写入 <gain>，只有结算记录之外的新获得才写短行隐藏记录；正文末尾可写 <feedback> 隐藏演出块。',
      hiddenFactPacket: factPacket,
      embeddedPrompt: {
        mode: 'frontend_builtin_worldbook',
        adapter: embeddedPrompt.adapter,
        modules: embeddedPrompt.modules.map(module => ({
          slot: module.slot,
          label: module.label,
          blockIds: module.blocks.map(block => block.id),
        })),
        matchedBlocks: embeddedPrompt.blocks.map(block => ({
          id: block.id,
          label: block.label,
          kind: block.kind,
          slot: block.slot,
          source: block.source,
          matchReason: block.matchReason,
        })),
        promptText: embeddedPrompt.promptText,
        injectionText: embeddedPrompt.injectionText,
        tavernGenerateConfig: buildTavernPresetGenerateConfig(save, {
          task,
          publicOperation,
          factPacket,
        }),
      },
      timestamps: save.timestamps,
      heroine: {
        rightPanelDisplay: save.heroine.display,
        cultivation: save.heroine.cultivation,
        growth: save.heroine.growth,
        dynamicProfile: save.heroine.dynamicProfile.placeholderText,
      },
      inventory: save.inventory,
      playerAnalysis: save.playerAnalysis.placeholderText,
      recentMessages: save.messages.slice(-8),
    },
    null,
    2,
  );
}

export function buildGenerationInputPacket(save: GameSave, task: GenerateTaskKind, userInput: string): string {
  const publicOperation = buildPublicOperation(userInput);
  return buildGenerationInputPacketWithFact(save, task, publicOperation, buildPlaceholderFactPacket(save, publicOperation));
}

function packetHasContent(packet: ParsedAcquisitionPacket): boolean {
  return Boolean(
    packet.items?.length ||
      packet.methods?.length ||
      packet.equip?.length ||
      Object.keys(packet.resources || {}).length ||
      packet.notes?.length,
  );
}

function normalizeRewardKey(value: string): string {
  return value.trim().toLowerCase();
}

function collectRegisteredRewardKeys(factPacket?: ActionFactPacket): Set<string> {
  const result = new Set<string>();
  for (const key of Object.keys(factPacket?.frontendResult?.rewards || {})) {
    result.add(normalizeRewardKey(key));
  }
  for (const key of Object.keys(factPacket?.frontendResult?.materialPurchases || {})) {
    result.add(normalizeRewardKey(key));
  }
  return result;
}

function isFrontendAuthoritativeEquipAction(factPacket?: ActionFactPacket): boolean {
  return factPacket?.section === 'equipment' || factPacket?.section === 'wardrobe';
}

function filterAlreadyRegisteredAcquisitions(
  packet: ParsedAcquisitionPacket,
  factPacket?: ActionFactPacket,
): { packet: ParsedAcquisitionPacket; removed: string[] } {
  const rewardKeys = collectRegisteredRewardKeys(factPacket);
  const authoritativeEquip = isFrontendAuthoritativeEquipAction(factPacket);
  const authoritativeSlot = normalizeRewardKey(String(factPacket?.stateDelta?.槽位 || ''));
  const authoritativeItem = normalizeRewardKey(String(factPacket?.stateDelta?.当前物品 || ''));

  const removed: string[] = [];
  const items = (packet.items || []).filter(item => {
    const duplicated = rewardKeys.has(normalizeRewardKey(item.name));
    if (duplicated) removed.push(`物品:${item.name}`);
    return !duplicated;
  });
  const methods = (packet.methods || []).filter(method => {
    const duplicated = rewardKeys.has(normalizeRewardKey(method.name));
    if (duplicated) removed.push(`功法:${method.name}`);
    return !duplicated;
  });
  const resources = Object.entries(packet.resources || {}).reduce<Record<string, number>>((result, [key, value]) => {
    const duplicated = rewardKeys.has(normalizeRewardKey(key));
    if (duplicated) removed.push(`资源:${key}`);
    if (!duplicated) result[key] = value;
    return result;
  }, {});
  const equip = (packet.equip || []).filter(change => {
    const duplicated =
      authoritativeEquip ||
      (normalizeRewardKey(change.slot) === authoritativeSlot && normalizeRewardKey(change.name) === authoritativeItem);
    if (duplicated) removed.push(`装备:${change.slot}/${change.name}`);
    return !duplicated;
  });

  return {
    packet: {
      ...packet,
      items,
      methods,
      equip,
      resources,
      notes: removed.length ? [...(packet.notes || []), `已过滤重复登记: ${removed.join('、')}`] : packet.notes,
    },
    removed,
  };
}

function applyParsedResources(save: GameSave, packet: ParsedAcquisitionPacket): GameSave {
  const resources = packet.resources || {};
  if (!Object.keys(resources).length) return save;
  return {
    ...save,
    heroine: {
      ...save.heroine,
      cultivation: {
        ...save.heroine.cultivation,
        resources: Object.entries(resources).reduce<Record<string, number>>(
          (result, [key, value]) => ({
            ...result,
            [key]: (result[key] || 0) + value,
          }),
          { ...save.heroine.cultivation.resources },
        ),
      },
    },
  };
}

function applyParsedRecipeDiscoveries(save: GameSave, packet: ParsedAcquisitionPacket): GameSave {
  if (!packet.methods?.length) return save;
  return {
    ...save,
    heroine: {
      ...save.heroine,
      growth: applyRecipeDiscoveriesToGrowth(save.heroine.growth, packet.methods),
    },
  };
}

function normalizeFeedbackValue(value: unknown, fallback: string): string {
  return typeof value === 'string' && value.trim() ? value.trim() : fallback;
}

function createFallbackFeedbackMeta(save: GameSave, factPacket?: ActionFactPacket): StoryFeedbackMeta {
  return {
    timestamp: save.timestamps.realityIso || new Date().toISOString(),
    expression: factPacket?.performanceHint.expression || save.heroine.display.expression,
    action: factPacket?.performanceHint.action || save.heroine.display.actionLabel,
    portrait: factPacket?.performanceHint.portrait || save.heroine.display.formalPoseId,
    chibi: factPacket?.performanceHint.chibi || save.heroine.display.chibiAnimationId,
    scene: factPacket?.performanceHint.scene || save.heroine.display.sceneLabel,
    statusDelta: {},
  };
}

function parseFeedbackLines(raw: string, fallback: StoryFeedbackMeta): StoryFeedbackMeta {
  const meta: StoryFeedbackMeta = {
    ...fallback,
    statusDelta: { ...fallback.statusDelta },
    rawHiddenParse: raw,
  };
  const keyMap: Record<string, keyof Pick<StoryFeedbackMeta, 'timestamp' | 'expression' | 'action' | 'portrait' | 'chibi' | 'scene'>> = {
    时间戳: 'timestamp',
    时间: 'timestamp',
    表情: 'expression',
    心情表情: 'expression',
    动作: 'action',
    行动: 'action',
    立绘: 'portrait',
    姿势立绘: 'portrait',
    Q版: 'chibi',
    q版: 'chibi',
    小人: 'chibi',
    场景: 'scene',
    地点: 'scene',
  };

  raw
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean)
    .forEach(line => {
      const parts = line.includes('|') ? line.split('|').map(part => part.trim()) : line.split(/[:：]/).map(part => part.trim());
      if (parts.length < 2) return;
      const key = parts[0];
      if (key === '状态' && parts.length >= 3) {
        meta.statusDelta[parts[1]] = parts.slice(2).join('|');
        return;
      }
      const mappedKey = keyMap[key];
      if (mappedKey) {
        meta[mappedKey] = parts.slice(1).join('|');
        return;
      }
      if (/状态|心境|心绪|情绪|伤势|身体|体况/.test(key)) {
        meta.statusDelta[key] = parts.slice(1).join('|');
      }
    });

  return meta;
}

function parseStoryFeedbackBlock(
  assistantText: string,
  save: GameSave,
  factPacket?: ActionFactPacket,
): { visibleText: string; meta?: StoryFeedbackMeta; rawBlock?: string; error?: string } {
  const blockPattern = /<(?:frontend_feedback|story_feedback|feedback)(?:\s[^>]*)?>([\s\S]*?)<\/(?:frontend_feedback|story_feedback|feedback)>/i;
  const matched = assistantText.match(blockPattern);
  if (!matched) return { visibleText: assistantText };
  const rawBlock = matched[0];
  const rawContent = matched[1].trim();
  const fallback = createFallbackFeedbackMeta(save, factPacket);

  try {
    const parsed = rawContent.startsWith('{')
      ? (() => {
          const json = JSON.parse(rawContent) as Partial<StoryFeedbackMeta>;
          return {
            ...fallback,
            ...json,
            statusDelta: {
              ...fallback.statusDelta,
              ...(json.statusDelta || {}),
            },
            rawHiddenParse: rawContent,
          };
        })()
      : parseFeedbackLines(rawContent, fallback);
    const meta: StoryFeedbackMeta = {
      ...parsed,
      timestamp: normalizeFeedbackValue(parsed.timestamp, fallback.timestamp),
      expression: normalizeFeedbackValue(parsed.expression, fallback.expression),
      action: normalizeFeedbackValue(parsed.action, fallback.action),
      portrait: normalizeFeedbackValue(parsed.portrait, fallback.portrait),
      chibi: normalizeFeedbackValue(parsed.chibi, fallback.chibi),
      scene: normalizeFeedbackValue(parsed.scene, fallback.scene),
      statusDelta: parsed.statusDelta || {},
      rawHiddenParse: rawContent,
    };
    return {
      visibleText: assistantText.replace(rawBlock, '').trim(),
      meta,
      rawBlock,
    };
  } catch (error) {
    return {
      visibleText: assistantText.replace(rawBlock, '').trim(),
      rawBlock,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

function applyStoryFeedbackMeta(save: GameSave, meta: StoryFeedbackMeta): GameSave {
  const status = meta.statusDelta || {};
  const bodyStatus =
    String(status['伤势'] || status['身体'] || status['体况'] || '').trim() || save.heroine.display.bodyStatus;
  const emotionStatus =
    String(status['心境'] || status['心绪'] || status['情绪'] || status['心情'] || '').trim() || save.heroine.display.emotionStatus;
  return {
    ...save,
    lastStoryFeedbackMeta: meta,
    heroine: {
      ...save.heroine,
      display: {
        ...save.heroine.display,
        expression: meta.expression,
        actionLabel: meta.action,
        formalPoseId: meta.portrait,
        avatarExpressionId: meta.expression,
        chibiAnimationId: meta.chibi,
        sceneLabel: meta.scene,
        bodyStatus,
        emotionStatus,
      },
      growth: {
        ...save.heroine.growth,
        condition: {
          ...save.heroine.growth.condition,
          injury: bodyStatus,
          moodTag: emotionStatus,
        },
      },
    },
  };
}

async function requestStoryText(save: GameSave, publicOperation: string, factPacket: ActionFactPacket): Promise<string> {
  const config = buildTavernPresetGenerateConfig(save, {
    task: 'story',
    publicOperation,
    factPacket,
  });

  if (typeof generate === 'function') {
    return generate(config);
  }

  return `正文反馈占位：已接收${publicOperation}。`;
}

export function recordAssistantStoryOutput(save: GameSave, assistantText: string, factPacket?: ActionFactPacket): GameSave {
  const parseResult = extractHiddenAcquisitionPacket(assistantText);
  const feedbackResult = parseStoryFeedbackBlock(parseResult.visibleText, save, factPacket);
  let nextSave = save;
  const filteredResult = parseResult.packet ? filterAlreadyRegisteredAcquisitions(parseResult.packet, factPacket) : null;

  if (filteredResult?.packet && packetHasContent(filteredResult.packet)) {
    nextSave = applyParsedRecipeDiscoveries(
      applyParsedResources(
        {
          ...nextSave,
          inventory: applyParsedAcquisitionPacket(nextSave.inventory, filteredResult.packet, parseResult.rawBlock),
        },
        filteredResult.packet,
      ),
      filteredResult.packet,
    );
  } else if (parseResult.error && parseResult.rawBlock) {
    nextSave = {
      ...nextSave,
      inventory: recordInventoryParseError(nextSave.inventory, parseResult.rawBlock, parseResult.error),
    };
  }

  if (feedbackResult.meta) {
    nextSave = applyStoryFeedbackMeta(nextSave, feedbackResult.meta);
  }

  nextSave = recordMessage(nextSave, 'assistant', 'assistant', feedbackResult.visibleText || '正文反馈已返回，隐藏解析块已移除。');

  if (parseResult.rawBlock || parseResult.error || feedbackResult.rawBlock || feedbackResult.error) {
    nextSave = recordDebugPacket(nextSave, {
      title: '正文隐藏解析块',
      body: JSON.stringify(
        {
          rawBlock: parseResult.rawBlock,
          parsed: parseResult.packet,
          filtered: filteredResult?.packet,
          removedDuplicatedRewards: filteredResult?.removed || [],
          error: parseResult.error,
          feedbackRawBlock: feedbackResult.rawBlock,
          feedbackMeta: feedbackResult.meta,
          feedbackError: feedbackResult.error,
        },
        null,
        2,
      ),
    });
  }

  return nextSave;
}

export async function generateStoryPlaceholder(save: GameSave, userInput: string): Promise<GameSave> {
  const trimmed = userInput.trim();
  if (!trimmed) throw Error('正文输入不能为空。');

  const publicOperation = buildPublicOperation(trimmed);
  const factPacket = buildPlaceholderFactPacket(save, publicOperation);
  const inputPacket = buildGenerationInputPacketWithFact(save, 'story', publicOperation, factPacket);
  const assistantText = await requestStoryText(save, publicOperation, factPacket);
  const storySave = await advancePersonaWorkflowsIfNeeded(
    recordAssistantStoryOutput(
      {
        ...recordMessage(save, 'player', 'user', publicOperation),
        onlineRealm: recordCooperativePublicOperation(save.onlineRealm, publicOperation),
      },
      assistantText,
      factPacket,
    ),
  );
  const nextSave = markTimestamp(
    recordDebugPacket(
      storySave,
      {
        title: '正文生成输入包',
        body: inputPacket,
      },
    ),
    'lastStoryGeneratedAtIso',
  );
  return nextSave;
}

export async function generateStoryForResolvedAction(save: GameSave, factPacket: ActionFactPacket): Promise<GameSave> {
  const inputPacket = buildGenerationInputPacketWithFact(save, 'story', factPacket.publicOperation, factPacket);
  const assistantText = await requestStoryText(save, factPacket.publicOperation, factPacket);
  const storySave = await advancePersonaWorkflowsIfNeeded(
    recordAssistantStoryOutput(
      {
        ...recordMessage(save, 'player', 'user', factPacket.publicOperation),
        onlineRealm: recordCooperativePublicOperation(save.onlineRealm, factPacket.publicOperation),
      },
      assistantText,
      factPacket,
    ),
  );
  return markTimestamp(
    recordDebugPacket(storySave, {
      title: '正文生成输入包',
      body: inputPacket,
    }),
    'lastStoryGeneratedAtIso',
  );
}
