function qFrame(actionName: string, frame: number): string {
  return asset(
    `2026-05-17_批次001_Q版LIVE2D关键帧_动态_${actionName}_帧${String(frame).padStart(2, '0')}_512内_v1.png`,
  );
}

function qFrames(actionName: string, count: number): string[] {
  return Array.from({ length: count }, (_, index) => qFrame(actionName, index + 1));
}

function qFrameRange(actionName: string, firstFrame: number, lastFrame: number): string[] {
  return Array.from({ length: lastFrame - firstFrame + 1 }, (_, index) => qFrame(actionName, firstFrame + index));
}

