const HIDDEN_PARSE_BLOCK_RE = /<gain(?:\s+[^>]*)?>([\s\S]*?)<\/gain>/gi;

function currentIso(): string {
  return new Date().toISOString();
}

function normalizeText(value: unknown, fallback = ''): string {
  return typeof value === 'string' && value.trim() ? value.trim() : fallback;
}

function normalizeNumber(value: unknown, fallback: number): number {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : fallback;
}

function normalizeStringArray(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.map(item => normalizeText(item)).filter(Boolean);
}

function normalizeRecipeCategory(value: unknown): InventoryCategory | string {
  const text = normalizeText(value, '其他');
  if ((INVENTORY_CATEGORY_ORDER as string[]).includes(text)) return text as InventoryCategory;
  return CATEGORY_ALIASES[text] || text;
}

function normalizeRecipeRequirement(raw: Partial<RecipeRequirement>): RecipeRequirement | null {
  const name = normalizeText(raw.name);
  if (!name) return null;
  return {
    category: normalizeRecipeCategory(raw.category),
    name,
    count: Math.max(1, normalizeNumber(raw.count, 1)),
    unit: normalizeText(raw.unit, '份'),
    grade: normalizeText(raw.grade, '未定阶'),
    quality: normalizeText(raw.quality, '普通'),
    optional: Boolean(raw.optional),
  };
}

function normalizeRecipeProduct(raw: Partial<RecipeProduct> | undefined): RecipeProduct | undefined {
  const name = normalizeText(raw?.name);
  if (!name) return undefined;
  return {
    category: raw?.category ? normalizeRecipeCategory(raw.category) : undefined,
    name,
    count: Math.max(1, normalizeNumber(raw?.count, 1)),
    unit: normalizeText(raw?.unit, '个'),
    grade: normalizeText(raw?.grade, '未定阶'),
    quality: normalizeText(raw?.quality, '普通'),
  };
}

function formatRecipeRequirement(requirement: RecipeRequirement): string {
  const optional = requirement.optional ? '(可选)' : '';
  return `${requirement.category}:${requirement.name}x${requirement.count || 1}${requirement.unit || '份'}@${requirement.grade || '未定阶'}${optional}`;
}

function formatRecipeProduct(product: RecipeProduct): string {
  const category = product.category ? `${product.category}:` : '';
  return `${category}${product.name}x${product.count || 1}${product.unit || '个'}@${product.grade || '未定阶'}`;
}

function stableKey(text: string): string {
  return text
    .trim()
    .toLowerCase()
    .replace(/[^\w\u4e00-\u9fa5]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function createInventoryItemId(item: Pick<InventoryItem, 'category' | 'name' | 'grade' | 'quality' | 'unit'>): string {
  const key = stableKey([item.category, item.name, item.grade, item.quality, item.unit].filter(Boolean).join('_'));
  return `item_${key || 'unknown'}`;
}

function createMethodId(method: Pick<LearnedMethodState, 'kind' | 'name' | 'grade'>): string {
  const key = stableKey([method.kind, method.name, method.grade].filter(Boolean).join('_'));
  return `method_${key || 'unknown'}`;
}

export function normalizeInventoryCategory(value: unknown): InventoryCategory {
  const text = normalizeText(value, '其他');
  if ((INVENTORY_CATEGORY_ORDER as string[]).includes(text)) return text as InventoryCategory;
  return CATEGORY_ALIASES[text] || '其他';
}

export function normalizeMethodKind(value: unknown): LearnedMethodKind {
  const text = normalizeText(value, '术法');
  if ((METHOD_KIND_ORDER as string[]).includes(text)) return text as LearnedMethodKind;
  return METHOD_KIND_ALIASES[text] || '术法';
}

function normalizeInventoryItem(raw: Partial<InventoryItem>, timestamp: string): InventoryItem | null {
  const name = normalizeText(raw.name);
  if (!name) return null;
  const category = normalizeInventoryCategory(raw.category);
  const item: InventoryItem = {
    id: normalizeText(raw.id),
    name,
    category,
    count: Math.max(0, normalizeNumber(raw.count, 1)),
    unit: normalizeText(raw.unit, '个'),
    grade: normalizeText(raw.grade, '未定阶'),
    quality: normalizeText(raw.quality, '普通'),
    description: normalizeText(raw.description),
    tags: normalizeStringArray(raw.tags),
    source: normalizeText(raw.source, '系统'),
    locked: Boolean(raw.locked),
    equipped: Boolean(raw.equipped),
    updatedAtIso: normalizeText(raw.updatedAtIso, timestamp),
  };
  return {
    ...item,
    id: item.id || createInventoryItemId(item),
  };
}

function normalizeMethod(raw: Partial<LearnedMethodState>, timestamp: string): LearnedMethodState | null {
  const name = normalizeText(raw.name);
  if (!name) return null;
  const requirements = Array.isArray(raw.requirements)
    ? raw.requirements
        .map(requirement => normalizeRecipeRequirement(requirement))
        .filter((requirement): requirement is RecipeRequirement => Boolean(requirement))
    : [];
  const method: LearnedMethodState = {
    id: normalizeText(raw.id),
    name,
    kind: normalizeMethodKind(raw.kind),
    grade: normalizeText(raw.grade, '未定阶'),
    progressLabel: normalizeText(raw.progressLabel, '已记录'),
    totalLayers: raw.totalLayers === undefined ? undefined : normalizeNumber(raw.totalLayers, 0),
    learnedLayers: raw.learnedLayers === undefined ? undefined : normalizeNumber(raw.learnedLayers, 0),
    source: normalizeText(raw.source, '系统'),
    description: normalizeText(raw.description),
    tags: normalizeStringArray(raw.tags),
    learnedAtIso: normalizeText(raw.learnedAtIso, timestamp),
    requirements: requirements.length ? requirements : undefined,
    product: normalizeRecipeProduct(raw.product),
    executable: Boolean(raw.executable),
  };
  return {
    ...method,
    id: method.id || createMethodId(method),
  };
}

