export function normalizeInventoryState(raw: unknown): InventoryState {
  const fallback = createInitialInventoryState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<InventoryState>;
  const timestamp = currentIso();
  return {
    ...fallback,
    items: Array.isArray(candidate.items)
      ? candidate.items
          .map(item => normalizeInventoryItem(item, timestamp))
          .filter((item): item is InventoryItem => Boolean(item))
      : fallback.items,
    methods: Array.isArray(candidate.methods)
      ? candidate.methods
          .map(method => normalizeMethod(method, timestamp))
          .filter((method): method is LearnedMethodState => Boolean(method))
      : fallback.methods,
    equipped: {
      ...DEFAULT_EQUIPPED_SLOTS,
      ...(candidate.equipped || {}),
    },
    lastParsedAtIso: candidate.lastParsedAtIso,
    lastParseRaw: candidate.lastParseRaw,
    lastParseError: candidate.lastParseError,
  };
}

function itemFromParsed(raw: ParsedAcquisitionItem, timestamp: string): InventoryItem | null {
  return normalizeInventoryItem(
    {
      name: raw.name,
      category: normalizeInventoryCategory(raw.category),
      count: Math.max(1, normalizeNumber(raw.count, 1)),
      unit: normalizeText(raw.unit, '个'),
      grade: normalizeText(raw.grade, '未定阶'),
      quality: normalizeText(raw.quality, '普通'),
      description: normalizeText(raw.description),
      tags: normalizeStringArray(raw.tags),
      source: normalizeText(raw.source, '正文隐藏解析'),
      updatedAtIso: timestamp,
    },
    timestamp,
  );
}

function methodFromParsed(raw: ParsedAcquisitionMethod, timestamp: string): LearnedMethodState | null {
  return normalizeMethod(
    {
      name: raw.name,
      kind: normalizeMethodKind(raw.kind),
      grade: normalizeText(raw.grade, '未定阶'),
      progressLabel: normalizeText(raw.progressLabel, raw.learnedLayers ? `已习得${raw.learnedLayers}层` : '已记录'),
      totalLayers: raw.totalLayers,
      learnedLayers: raw.learnedLayers,
      description: normalizeText(raw.description),
      tags: normalizeStringArray(raw.tags),
      source: normalizeText(raw.source, '正文隐藏解析'),
      learnedAtIso: timestamp,
      requirements: raw.requirements,
      product: raw.product,
      executable: raw.executable,
    },
    timestamp,
  );
}

function mergeRecipeRequirements(
  current: RecipeRequirement[] | undefined,
  incoming: RecipeRequirement[] | undefined,
): RecipeRequirement[] | undefined {
  const merged = [...(current || [])];
  for (const requirement of incoming || []) {
    const normalized = normalizeRecipeRequirement(requirement);
    if (!normalized) continue;
    const exists = merged.some(
      item =>
        item.category === normalized.category &&
        item.name === normalized.name &&
        item.grade === normalized.grade &&
        item.quality === normalized.quality &&
        item.unit === normalized.unit,
    );
    if (!exists) merged.push(normalized);
  }
  return merged.length ? merged : undefined;
}

export function addInventoryItem(state: InventoryState, rawItem: ParsedAcquisitionItem, timestamp = currentIso()): InventoryState {
  const normalizedState = normalizeInventoryState(state);
  const item = itemFromParsed(rawItem, timestamp);
  if (!item) return normalizedState;
  const existingIndex = normalizedState.items.findIndex(
    existing =>
      existing.name === item.name &&
      existing.category === item.category &&
      existing.grade === item.grade &&
      existing.quality === item.quality &&
      existing.unit === item.unit,
  );
  const items =
    existingIndex >= 0
      ? normalizedState.items.map((existing, index) =>
          index === existingIndex
            ? {
                ...existing,
                count: existing.count + item.count,
                source: item.source,
                description: item.description || existing.description,
                tags: Array.from(new Set([...existing.tags, ...item.tags])),
                updatedAtIso: timestamp,
              }
            : existing,
        )
      : [item, ...normalizedState.items];

  return {
    ...normalizedState,
    items,
  };
}

export function addLearnedMethod(state: InventoryState, rawMethod: ParsedAcquisitionMethod, timestamp = currentIso()): InventoryState {
  const normalizedState = normalizeInventoryState(state);
  const method = methodFromParsed(rawMethod, timestamp);
  if (!method) return normalizedState;
  const existingIndex = normalizedState.methods.findIndex(existing => existing.name === method.name && existing.kind === method.kind);
  const methods =
    existingIndex >= 0
      ? normalizedState.methods.map((existing, index) =>
          index === existingIndex
            ? {
                ...existing,
                grade: method.grade || existing.grade,
                progressLabel: method.progressLabel || existing.progressLabel,
                totalLayers: method.totalLayers ?? existing.totalLayers,
                learnedLayers: Math.max(existing.learnedLayers || 0, method.learnedLayers || 0) || existing.learnedLayers,
                description: method.description || existing.description,
                tags: Array.from(new Set([...existing.tags, ...method.tags])),
                source: method.source,
                requirements: mergeRecipeRequirements(existing.requirements, method.requirements),
                product: method.product || existing.product,
                executable: existing.executable || method.executable,
              }
            : existing,
        )
      : [method, ...normalizedState.methods];
  const equipped = rawMethod.autoEquip
    ? {
        ...normalizedState.equipped,
        [method.kind]: method.name,
      }
    : normalizedState.equipped;

  return {
    ...normalizedState,
    methods,
    equipped,
  };
}

export function confirmRecipeMethod(state: InventoryState, methodId: string, timestamp = currentIso()): InventoryState {
  const normalizedState = normalizeInventoryState(state);
  const target = normalizedState.methods.find(method => method.id === methodId);
  if (!target) throw Error('找不到这条配方或图谱。');
  if (!target.product) throw Error('这条配方缺少产物，不能整理为可执行配方。');
  if (!target.requirements?.length) throw Error('这条配方缺少需求清单，不能整理为可执行配方。');

  return {
    ...normalizedState,
    methods: normalizedState.methods.map(method =>
      method.id === methodId
        ? {
            ...method,
            progressLabel: '已确认',
            executable: true,
            tags: Array.from(new Set([...method.tags, '可执行配方'])),
            learnedAtIso: timestamp,
          }
        : method,
    ),
    lastParsedAtIso: timestamp,
    lastParseRaw: `整理配方:${target.name}`,
    lastParseError: undefined,
  };
}

export function applyParsedAcquisitionPacket(
  state: InventoryState,
  packet: ParsedAcquisitionPacket,
  rawBlock?: string,
  timestamp = currentIso(),
): InventoryState {
  let nextState = normalizeInventoryState(state);
  for (const item of packet.items || []) {
    nextState = addInventoryItem(nextState, item, timestamp);
  }
  for (const method of packet.methods || []) {
    nextState = addLearnedMethod(nextState, method, timestamp);
  }
  const equipped = { ...nextState.equipped };
  for (const change of packet.equip || []) {
    const slot = normalizeText(change.slot);
    const name = normalizeText(change.name);
    if (slot && name) equipped[slot] = name;
  }
  return {
    ...nextState,
    equipped,
    lastParsedAtIso: timestamp,
    lastParseRaw: rawBlock || JSON.stringify(packet),
    lastParseError: undefined,
  };
}

export function recordInventoryParseError(state: InventoryState, rawBlock: string, error: string, timestamp = currentIso()): InventoryState {
  const normalizedState = normalizeInventoryState(state);
  return {
    ...normalizedState,
    lastParsedAtIso: timestamp,
    lastParseRaw: rawBlock,
    lastParseError: error,
  };
}

export function stripHiddenFrontendParse(text: string): string {
  HIDDEN_PARSE_BLOCK_RE.lastIndex = 0;
  return text.replace(HIDDEN_PARSE_BLOCK_RE, '').trim();
}

function mergePackets(packets: ParsedAcquisitionPacket[]): ParsedAcquisitionPacket {
  return {
    schema: 'fairy_inventory_parse_v1',
    items: packets.flatMap(packet => packet.items || []),
    methods: packets.flatMap(packet => packet.methods || []),
    equip: packets.flatMap(packet => packet.equip || []),
    resources: packets.reduce<Record<string, number>>((result, packet) => {
      for (const [key, value] of Object.entries(packet.resources || {})) {
        result[key] = (result[key] || 0) + normalizeNumber(value, 0);
      }
      return result;
    }, {}),
    notes: packets.flatMap(packet => packet.notes || []),
    sourceActionId: packets.map(packet => packet.sourceActionId).filter(Boolean).join(',') || undefined,
  };
}

function parseLayerText(layerText: string): Pick<ParsedAcquisitionMethod, 'learnedLayers' | 'totalLayers' | 'progressLabel'> {
  const text = normalizeText(layerText);
  if (!text) return {};
  const match = text.match(/^(\d+)\/(\d+|\?)$/);
  if (!match) return { progressLabel: text };
  return {
    learnedLayers: normalizeNumber(match[1], 0),
    totalLayers: match[2] === '?' ? undefined : normalizeNumber(match[2], 0),
    progressLabel: `已习得${match[1]}/${match[2]}`,
  };
}

function parseRecipeProductToken(token: string): RecipeProduct | undefined {
  const text = normalizeText(token);
  if (!text || text === '无') return undefined;
  const [categoryText, rawBody = categoryText] = /[:：]/.test(text) ? text.split(/[:：](.+)/).filter(Boolean) : ['', text];
  const [bodyWithoutQuality, qualityText] = rawBody.split('#');
  const [nameAmountText, gradeText] = bodyWithoutQuality.split('@');
  const amountMatch = nameAmountText.match(/^(.+?)[x×](\d+(?:\.\d+)?)(.*)$/);
  const name = normalizeText(amountMatch?.[1] || nameAmountText);
  if (!name) return undefined;
  return normalizeRecipeProduct({
    category: normalizeText(categoryText) || undefined,
    name,
    count: amountMatch ? normalizeNumber(amountMatch[2], 1) : 1,
    unit: normalizeText(amountMatch?.[3], '个'),
    grade: normalizeText(gradeText, '未定阶'),
    quality: normalizeText(qualityText, '普通'),
  });
}

function parseGainLinePacket(rawBlock: string): ParsedAcquisitionPacket {
  const packet: ParsedAcquisitionPacket = {
    schema: 'fairy_inventory_parse_v1',
    items: [],
    methods: [],
    equip: [],
    resources: {},
    notes: [],
  };
  const recipeMethods = new Map<string, ParsedAcquisitionMethod>();
  let lastRecipeName = '';
  const lines = rawBlock
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(line => line && !line.startsWith('#'));

  for (const [index, line] of lines.entries()) {
    const parts = line.split('|').map(part => part.trim());
    const head = parts[0];
    if (head === '方') {
      if (parts.length < 3) throw Error(`第 ${index + 1} 行配方记录缺少类型或名称。`);
      const progressLabel = normalizeText(parts[4], '待整理');
      const method: ParsedAcquisitionMethod = {
        kind: normalizeText(parts[1], '丹方'),
        name: parts[2],
        grade: normalizeText(parts[3], '未定阶'),
        progressLabel,
        product: parseRecipeProductToken(parts[5] || ''),
        source: normalizeText(parts[6], '正文隐藏记录'),
        requirements: [],
        tags: ['配方'],
        executable: /可执行|已验证|已确认/.test(progressLabel),
      };
      packet.methods!.push(method);
      recipeMethods.set(method.name, method);
      lastRecipeName = method.name;
      continue;
    }

    if (head === '需') {
      if (parts.length < 5) throw Error(`第 ${index + 1} 行需求记录至少需要：需|方名|分类|名称|数量。`);
      const recipeName = parts[1] && parts[1] !== '上条' ? parts[1] : lastRecipeName;
      const method = recipeMethods.get(recipeName);
      if (!method) throw Error(`第 ${index + 1} 行需求记录找不到对应配方：${recipeName || '未指定'}`);
      const requirement = normalizeRecipeRequirement({
        category: parts[2],
        name: parts[3],
        count: normalizeNumber(parts[4], 1),
        unit: normalizeText(parts[5], '份'),
        grade: normalizeText(parts[6], '未定阶'),
        quality: normalizeText(parts[7], '普通'),
        optional: /可选|optional/i.test(parts[8] || ''),
      });
      if (requirement) method.requirements = [...(method.requirements || []), requirement];
      continue;
    }

    if (head === '法') {
      if (parts.length < 3) throw Error(`第 ${index + 1} 行功法记录缺少类型或名称。`);
      const layer = parseLayerText(parts[4] || '');
      packet.methods!.push({
        kind: parts[1],
        name: parts[2],
        grade: normalizeText(parts[3], '未定阶'),
        ...layer,
        progressLabel: normalizeText(parts[6], layer.progressLabel || '已记录'),
        source: normalizeText(parts[5], '正文隐藏记录'),
      });
      continue;
    }

    if (head === '装') {
      if (parts.length < 3) throw Error(`第 ${index + 1} 行装备记录缺少槽位或名称。`);
      packet.equip!.push({
        slot: parts[1],
        name: parts[2],
      });
      continue;
    }

    if (head === '资') {
      if (parts.length < 3) throw Error(`第 ${index + 1} 行资源记录缺少名称或数量。`);
      packet.resources![parts[1]] = (packet.resources![parts[1]] || 0) + normalizeNumber(parts[2], 0);
      continue;
    }

    if (head === '注') {
      packet.notes!.push(parts.slice(1).join('|'));
      continue;
    }

    if (parts.length < 3) throw Error(`第 ${index + 1} 行物品记录至少需要：分类|名称|数量。`);
    packet.items!.push({
      category: normalizeInventoryCategory(head),
      name: parts[1],
      count: normalizeNumber(parts[2], 1),
      unit: normalizeText(parts[3], '个'),
      grade: normalizeText(parts[4], '未定阶'),
      quality: normalizeText(parts[5], '普通'),
      source: normalizeText(parts[6], '正文隐藏记录'),
    });
  }

  return packet;
}

export function extractHiddenAcquisitionPacket(text: string): FrontendParseResult {
  HIDDEN_PARSE_BLOCK_RE.lastIndex = 0;
  const matches = Array.from(text.matchAll(HIDDEN_PARSE_BLOCK_RE));
  const visibleText = stripHiddenFrontendParse(text);
  if (!matches.length) return { visibleText };

  const rawBlocks = matches.map(match => match[1].trim()).filter(Boolean);
  try {
    const packets = rawBlocks.map(parseGainLinePacket);
    return {
      visibleText,
      rawBlock: rawBlocks.join('\n\n'),
      packet: mergePackets(packets),
    };
  } catch (error) {
    return {
      visibleText,
      rawBlock: rawBlocks.join('\n\n'),
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

export interface InventoryCategorySummary {
  category: InventoryCategory;
  totalKinds: number;
  totalCount: number;
}

export function summarizeInventoryCategories(state: InventoryState): InventoryCategorySummary[] {
  const normalizedState = normalizeInventoryState(state);
  return INVENTORY_CATEGORY_ORDER.map(category => {
    const items = normalizedState.items.filter(item => item.category === category);
    return {
      category,
      totalKinds: items.length,
      totalCount: items.reduce((sum, item) => sum + item.count, 0),
    };
  }).filter(summary => summary.totalKinds > 0);
}

export function buildInventoryPromptYaml(state: InventoryState): string {
  const normalizedState = normalizeInventoryState(state);
  const categories = summarizeInventoryCategories(normalizedState);
  const equippedLines = Object.entries(normalizedState.equipped)
    .filter(([, value]) => Boolean(value))
    .map(([slot, value]) => `    ${slot}: ${value}`);
  const itemLines = categories.flatMap(summary => {
    const items = normalizedState.items
      .filter(item => item.category === summary.category)
      .slice(0, 8)
      .map(item => `      - ${item.name} x${item.count}${item.unit} / ${item.grade} / ${item.quality}`);
    return [`    ${summary.category}:`, ...items];
  });
  const methodLines = normalizedState.methods.slice(0, 12).map(method => {
    const layerText =
      method.totalLayers || method.learnedLayers ? ` / 层数 ${method.learnedLayers || 0}/${method.totalLayers || '?'}` : '';
    const requirementText = method.requirements?.length
      ? ` / 需求 ${method.requirements.map(formatRecipeRequirement).join('; ')}`
      : '';
    const productText = method.product ? ` / 产物 ${formatRecipeProduct(method.product)}` : '';
    const executableText = method.executable ? ' / 可执行' : '';
    return `    - ${method.kind}: ${method.name} / ${method.grade} / ${method.progressLabel}${layerText}${productText}${requirementText}${executableText}`;
  });

  return [
    '背包与功法库:',
    '  记录原则: 系统已记录储物戒、装备位、功法库和术法库，正文只参考，不直接改写可见数值',
    '  装备位:',
    ...(equippedLines.length ? equippedLines : ['    无']),
    '  物品摘要:',
    ...(itemLines.length ? itemLines : ['    无']),
    '  功法术法:',
    ...(methodLines.length ? methodLines : ['    无']),
  ].join('\n');
}

