export function getPaymentProducts(): PaymentProductDefinition[] {
  return PAYMENT_PRODUCTS;
}

function getVisualPatch(product: PaymentProductDefinition) {
  const visualByProduct: Record<string, { formalPoseId: string; avatarExpressionId: string; chibiAnimationId: string; expression: string }> = {
    spirit_stone_pack: { formalPoseId: 'happyStand', avatarExpressionId: 'expect', chibiAnimationId: 'happyJump', expression: '期待' },
    pill_pack: { formalPoseId: 'eatFruit', avatarExpressionId: 'relieved', chibiAnimationId: 'eatFruit', expression: '安心' },
    hundred_art_material_box: { formalPoseId: 'readScroll', avatarExpressionId: 'thinking', chibiAnimationId: 'crafting', expression: '认真' },
    hundred_art_tool_box: { formalPoseId: 'casting', avatarExpressionId: 'firm', chibiAnimationId: 'crafting', expression: '坚定' },
    insight_pack: { formalPoseId: 'casting', avatarExpressionId: 'firm', chibiAnimationId: 'casting', expression: '坚定' },
  };
  const visualByCategory: Record<string, { formalPoseId: string; avatarExpressionId: string; chibiAnimationId: string; expression: string }> = {
    daily: { formalPoseId: 'happyStand', avatarExpressionId: 'relieved', chibiAnimationId: 'happyJump', expression: '放松' },
    cultivation: { formalPoseId: 'casting', avatarExpressionId: 'firm', chibiAnimationId: 'casting', expression: '认真' },
    hundred_arts: { formalPoseId: 'readScroll', avatarExpressionId: 'thinking', chibiAnimationId: 'crafting', expression: '专注' },
    equipment: { formalPoseId: 'casting', avatarExpressionId: 'firm', chibiAnimationId: 'equip', expression: '警觉' },
    wardrobe: { formalPoseId: 'happyStand', avatarExpressionId: 'expect', chibiAnimationId: 'dressUp', expression: '别扭' },
    offline: { formalPoseId: 'readScroll', avatarExpressionId: 'thinking', chibiAnimationId: 'tired', expression: '不满' },
    support: { formalPoseId: 'eatFruit', avatarExpressionId: 'relieved', chibiAnimationId: 'idle', expression: '缓和' },
    luxury: { formalPoseId: 'happyStand', avatarExpressionId: 'expect', chibiAnimationId: 'happyJump', expression: '动摇' },
  };
  return visualByProduct[product.id] || visualByCategory[product.category || 'daily'] || visualByProduct.spirit_stone_pack;
}

export function resolvePaymentProduct(save: GameSave, productId: string): ResolvedGameplayAction {
  const product = PAYMENT_PRODUCTS.find(item => item.id === productId);
  if (!product) throw Error('未知资源投放项目。');
  if (!product.unlocked) throw Error('该项目尚未解锁。');
  if (save.money.balance < product.price) throw Error('现实资金不足。');

  const resources = { ...save.heroine.cultivation.resources };
  Object.entries(product.resourceDelta).forEach(([key, amount]) => {
    resources[key] = (resources[key] || 0) + amount;
  });
  const inventory = product.inventoryItems?.length
    ? applyParsedAcquisitionPacket(save.inventory, {
        schema: 'fairy_inventory_parse_v1',
        items: product.inventoryItems,
      })
    : save.inventory;
  const itemRewards = (product.inventoryItems || []).reduce<Record<string, number>>((result, item) => {
    result[item.name] = (result[item.name] || 0) + (item.count || 1);
    return result;
  }, {});

  const timestamp = nowIso();
  const visualPatch = getVisualPatch(product);
  const feedbackNotes = [
    '本轮资源投放已登记。',
    '已登记奖励不要再写入 <gain>。',
    `商城分类: ${product.category || '未分类'}`,
    ...(product.tags?.length ? [`商城标签: ${product.tags.join('、')}`] : []),
    ...(product.heroineReactionHint ? [`女主反馈倾向: ${product.heroineReactionHint}`] : []),
    ...(product.analysisTags?.length ? [`玩家分析标签: ${product.analysisTags.join('、')}`] : []),
  ];
  const nextSave: GameSave = {
    ...save,
    money: {
      ...save.money,
      balance: save.money.balance - product.price,
      spentTotal: save.money.spentTotal + product.price,
      ledger: [
        {
          id: createId('money'),
          kind: 'payment' as const,
          label: `${product.label}（${product.tier}）`,
          amount: product.price,
          createdAtIso: timestamp,
        },
        ...save.money.ledger,
      ].slice(0, 160),
    },
    heroine: {
      ...save.heroine,
      display: {
        ...save.heroine.display,
        ...visualPatch,
        actionLabel: product.label,
      },
      cultivation: {
        ...save.heroine.cultivation,
        resources,
      },
    },
    inventory,
  };

  const publicOperation = `玩家操作：给她投放${product.label}。`;
  const factPacket: ActionFactPacket = {
    actionId: product.id,
    section: 'resources',
    publicOperation,
    resultSummary: `${product.label}已投放，系统已登记资源变化。`,
    stateDelta: {
      balance: nextSave.money.balance,
      ...product.resourceDelta,
      ...itemRewards,
    },
    frontendResult: {
      outcome: 'success',
      consumed: { 现实资金: product.price },
      rewards: {
        ...product.resourceDelta,
        ...itemRewards,
      },
      notes: feedbackNotes,
    },
    performanceHint: {
      expression: visualPatch.expression,
      action: product.label,
      portrait: visualPatch.formalPoseId,
      chibi: visualPatch.chibiAnimationId,
      scene: nextSave.heroine.display.sceneLabel,
    },
    debugOnly: true,
  };

  return {
    save: recordOperation(nextSave, {
      actionType: 'PAYMENT_APPLY',
      label: product.label,
      detail: [
        product.summary,
        `价格: ${product.price}`,
        `分类: ${product.category || '未分类'}`,
        product.tags?.length ? `标签: ${product.tags.join('、')}` : '',
        product.heroineReactionHint ? `反馈: ${product.heroineReactionHint}` : '',
      ]
        .filter(Boolean)
        .join(' / '),
      section: '资源',
      publicOperation,
      factPacketPreview: JSON.stringify(factPacket, null, 2),
    }),
    publicOperation,
    factPacket,
  };
}

export function applyPaymentProduct(save: GameSave, productId: string): GameSave {
  return resolvePaymentProduct(save, productId).save;
}
