function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

function roundRate(value: number): number {
  return Math.round(value * 100) / 100;
}

function percent(value: number): number {
  return Math.round(value * 100);
}

function factorLine(label: string, delta: number): string {
  const sign = delta >= 0 ? '+' : '';
  return `${label} ${sign}${percent(delta)}%`;
}

function getArtIdFromOperation(operationId: string): HundredArtId | null {
  const recipeMatch = operationId.match(/^recipe_(.+?)_/);
  if (recipeMatch && (HUNDRED_ART_IDS as string[]).includes(recipeMatch[1])) return recipeMatch[1] as HundredArtId;
  const suffix = operationId.replace(/^learn_/, '').replace(/^practice_/, '');
  return (HUNDRED_ART_IDS as string[]).includes(suffix) ? (suffix as HundredArtId) : null;
}

function getRealmTier(save: GameSave): number {
  const text = `${save.heroine.growth.cultivationTrack.realm} ${save.heroine.cultivation.realm}`;
  const tiers = ['未入道', '练气', '筑基', '金丹', '元婴', '化神', '炼虚', '合体', '大乘', '渡劫'];
  const index = tiers.findIndex(tier => text.includes(tier));
  return Math.max(0, index);
}

function getStageBonus(stage: string): number {
  const bonuses: Record<string, number> = {
    未习得: -0.18,
    初识: 0.02,
    入门: 0.06,
    熟练: 0.12,
    精通: 0.18,
    小成: 0.24,
    大成: 0.3,
  };
  return bonuses[stage] ?? 0;
}

function getGradeBonus(grade: string): number {
  if (/神|仙|天级/.test(grade)) return 0.06;
  if (/地级/.test(grade)) return 0.045;
  if (/玄级/.test(grade)) return 0.035;
  if (/黄级上品/.test(grade)) return 0.028;
  if (/黄级中品/.test(grade)) return 0.022;
  if (/黄级下品/.test(grade)) return 0.016;
  if (/凡/.test(grade)) return 0.006;
  return 0.012;
}

function resolveGradePrice(rawGrade: string): { label: string; unitPrice: number; order: number } {
  const matched = GRADE_UNIT_PRICES.find(rule => rule.pattern.test(rawGrade));
  return matched || { label: rawGrade || '黄级下品', unitPrice: FALLBACK_SUCCESS_RATE_POINT_PRICE, order: 3 };
}

function resolveMaterialPurchasePrice(rawGrade: string): { label: string; unitPrice: number; order: number } {
  const matched = MATERIAL_PURCHASE_GRADE_PRICES.find(rule => rule.pattern.test(rawGrade));
  return matched || { label: rawGrade || '黄级下品', unitPrice: FALLBACK_MATERIAL_PURCHASE_PRICE, order: 3 };
}

function getHigherGrade(left: string, right: string): string {
  return resolveGradePrice(left).order >= resolveGradePrice(right).order ? left : right;
}

function getRiskMultiplier(riskLevel: GrowthOperationDefinition['riskLevel']): number {
  const multipliers: Record<GrowthOperationDefinition['riskLevel'], number> = {
    none: 0.7,
    low: 1,
    medium: 1.35,
    high: 1.8,
  };
  return multipliers[riskLevel];
}

function getBreakthroughGradeByRealm(save: GameSave): string {
  const grades = ['黄级上品', '玄级下品', '玄级中品', '地级下品', '地级中品', '天级下品', '天级中品', '天级上品', '圣级', '仙级'];
  return grades[Math.min(getRealmTier(save), grades.length - 1)];
}

function getOperationDefaultGrade(save: GameSave, operation: GrowthOperationDefinition): string {
  if (operation.id === 'cultivation_breakthrough') return getBreakthroughGradeByRealm(save);
  if (operation.id === 'cultivation_meditate') return '凡物';
  if (operation.id === 'cultivation_breath_cycle') return '黄级下品';
  if (operation.id === 'cultivation_heal') return '黄级下品';
  if (operation.id.startsWith('learn_')) return '黄级下品';
  if (operation.id.startsWith('practice_')) return '黄级下品';
  if (operation.id.startsWith('recipe_')) {
    return operation.paidBoostSlots.find(slot => slot.startsWith('品级:'))?.replace(/^品级:/, '') || '黄级下品';
  }
  if (operation.id === 'fishing_inspect_water') return '凡物';
  if (operation.id === 'fishing_cast') return '黄级下品';
  return '黄级下品';
}

function getOperationMakeupGrade(save: GameSave, operation: GrowthOperationDefinition, materialItems: InventoryItem[]): string {
  return materialItems.reduce((grade, item) => getHigherGrade(grade, item.grade), getOperationDefaultGrade(save, operation));
}

function getMaterialUnit(category: string): string {
  const units: Record<string, string> = {
    药材: '株',
    矿石: '块',
    丹药: '枚',
    符纸: '张',
    灵墨: '份',
    灵材: '份',
    阵旗: '面',
    饲料: '份',
    傀儡件: '枚',
    种子: '粒',
    鱼饵: '份',
  };
  return units[category] || '份';
}

function getPurchasedMaterialName(category: string): string {
  const names: Record<string, string> = {
    药材: '应急药材包',
    矿石: '应急矿石包',
    丹药: '应急丹药',
    符纸: '应急符纸',
    灵墨: '应急灵墨',
    灵材: '应急灵材',
    阵旗: '应急阵旗',
    饲料: '应急灵饲',
    傀儡件: '应急傀儡件',
    种子: '应急灵种',
    鱼饵: '应急鱼饵',
  };
  return names[category] || `应急${category}`;
}

function createMaterialPurchasePreviews(
  categories: string[],
  grade: string,
): MaterialPurchasePreview[] {
  const price = resolveMaterialPurchasePrice(grade);
  const grouped = categories.reduce<Record<string, number>>((result, category) => {
    result[category] = (result[category] || 0) + 1;
    return result;
  }, {});
  return Object.entries(grouped).map(([category, count]) => ({
    category,
    itemName: getPurchasedMaterialName(category),
    count,
    unit: getMaterialUnit(category),
    grade: price.label,
    unitPrice: price.unitPrice,
    totalPrice: price.unitPrice * count,
  }));
}

function getQualityBonus(quality: string): number {
  if (/极品|完美/.test(quality)) return 0.05;
  if (/上乘|精良/.test(quality)) return 0.035;
  if (/新鲜|纯净/.test(quality)) return 0.025;
  if (/普通/.test(quality)) return 0.012;
  if (/粗糙|陈旧/.test(quality)) return -0.018;
  if (/受损|污染/.test(quality)) return -0.04;
  return 0.008;
}

function itemScore(item: InventoryItem): number {
  return getGradeBonus(item.grade) + getQualityBonus(item.quality);
}

function toCandidatePreview(item: InventoryItem): CostItemCandidatePreview {
  return {
    id: item.id,
    name: item.name,
    category: item.category,
    count: item.count,
    unit: item.unit,
    grade: item.grade,
    quality: item.quality,
    score: Math.round(itemScore(item) * 1000) / 1000,
  };
}

function getCostItemCandidatesForCategory(items: InventoryItem[], rawCategory: string): InventoryItem[] {
  const category = normalizeInventoryCategory(rawCategory);
  return [...items].filter(item => item.category === category && item.count > 0).sort((left, right) => itemScore(right) - itemScore(left));
}

function getCostItemForCategory(
  items: InventoryItem[],
  rawCategory: string,
  selection: GrowthOperationSelection = {},
): InventoryItem | null {
  const category = normalizeInventoryCategory(rawCategory);
  const candidates = getCostItemCandidatesForCategory(items, category);
  const selectedId = selection.inventoryItemIdsByCategory?.[category];
  return candidates.find(item => item.id === selectedId) || candidates[0] || null;
}

function createCostSlots(
  inventoryItems: InventoryItem[],
  operation: GrowthOperationDefinition,
  selection: GrowthOperationSelection = {},
): CostSlotPreview[] {
  const grouped = (operation.cost.inventoryCategories || []).reduce<Record<string, number>>((result, rawCategory) => {
    const category = normalizeInventoryCategory(rawCategory);
    result[category] = (result[category] || 0) + 1;
    return result;
  }, {});

  return Object.entries(grouped).map(([category, requiredCount]) => {
    const candidates = getCostItemCandidatesForCategory(inventoryItems, category);
    const selected = candidates.find(item => item.id === selection.inventoryItemIdsByCategory?.[category]) || candidates[0];
    const availableCount = candidates.reduce((sum, item) => sum + item.count, 0);
    return {
      category,
      requiredCount,
      selectedItemId: selected?.id || '',
      selectedItemName: selected?.name || '',
      candidates: candidates.map(toCandidatePreview),
      missingCount: Math.max(0, requiredCount - availableCount),
    };
  });
}

function splitToolTokens(requiredTool: string): string[] {
  return requiredTool
    .split(/[、，,\/\s]|或|和/g)
    .map(token => token.trim())
    .filter(token => token.length >= 2);
}

function itemMatchesTool(item: InventoryItem, tokens: string[]): boolean {
  const text = `${item.category} ${item.name} ${item.tags.join(' ')} ${item.description}`;
  return tokens.some(token => text.includes(token));
}

function createToolSlot(
  save: GameSave,
  operation: GrowthOperationDefinition,
  selection: GrowthOperationSelection = {},
): ToolSlotPreview | undefined {
  const requiredTool = operation.cost.requiredTool?.trim();
  if (!requiredTool) return undefined;
  const inventory = normalizeInventoryState(save.inventory);
  const tokens = splitToolTokens(requiredTool);
  const candidates = inventory.items
    .filter(item => item.count > 0 && itemMatchesTool(item, tokens))
    .sort((left, right) => itemScore(right) - itemScore(left));
  const selected = candidates.find(item => item.id === selection.toolItemId) || candidates[0];
  const equippedText = Object.values(inventory.equipped).join(' ');
  const equippedMatched = tokens.some(token => equippedText.includes(token));
  return {
    requiredTool,
    selectedItemId: selected?.id || '',
    selectedItemName: selected?.name || (equippedMatched ? '已装备匹配工具' : ''),
    candidates: candidates.map(toCandidatePreview),
    matched: Boolean(selected || equippedMatched),
  };
}

function inspectCost(
  save: GameSave,
  operation: GrowthOperationDefinition,
  selection: GrowthOperationSelection = {},
): CostInspection {
  const inventory = normalizeInventoryState(save.inventory);
  let availableItems = inventory.items.map(item => ({ ...item }));
  const consumedPreview: Record<string, number> = {};
  const blockingReasons: string[] = [];
  const nonPurchasableBlockingReasons: string[] = [];
  const materialItems: InventoryItem[] = [];
  const missingMaterialCategories: string[] = [];
  const costSlots = createCostSlots(inventory.items, operation, selection);
  const toolSlot = createToolSlot(save, operation, selection);

  for (const [key, amount] of Object.entries(operation.cost.resources || {})) {
    const current = save.heroine.cultivation.resources[key] || 0;
    consumedPreview[key] = amount;
    if (current < amount) {
      const reason = `缺少${key} ${amount - current}`;
      blockingReasons.push(reason);
      nonPurchasableBlockingReasons.push(reason);
    }
  }

  for (const rawCategory of operation.cost.inventoryCategories || []) {
    const category = normalizeInventoryCategory(rawCategory);
    const item = getCostItemForCategory(availableItems, category, selection);
    if (!item) {
      blockingReasons.push(`缺少${category}`);
      missingMaterialCategories.push(category);
      consumedPreview[category] = (consumedPreview[category] || 0) + 1;
      continue;
    }
    materialItems.push(item);
    availableItems = availableItems
      .map(current => (current.id === item.id ? { ...current, count: current.count - 1 } : current))
      .filter(current => current.count > 0);
    consumedPreview[item.name || category] = (consumedPreview[item.name || category] || 0) + 1;
  }

  return {
    canRun: blockingReasons.length === 0,
    blockingReasons,
    nonPurchasableBlockingReasons,
    consumedPreview,
    materialItems,
    missingMaterialCategories,
    costSlots,
    toolSlot,
  };
}

function getRequiredToolDelta(
  save: GameSave,
  operation: GrowthOperationDefinition,
  selection: GrowthOperationSelection = {},
): { delta: number; line?: string; toolSlot?: ToolSlotPreview } {
  const requiredTool = operation.cost.requiredTool?.trim();
  if (!requiredTool) return { delta: 0 };

  const toolSlot = createToolSlot(save, operation, selection);
  const matched = Boolean(toolSlot?.matched);
  const selectedLabel = toolSlot?.selectedItemName ? `:${toolSlot.selectedItemName}` : '';

  if (matched) return { delta: 0.06, line: factorLine(`工具匹配(${requiredTool}${selectedLabel})`, 0.06), toolSlot };
  return { delta: -0.06, line: factorLine(`工具未配置(${requiredTool})`, -0.06), toolSlot };
}

function getConditionFactors(save: GameSave): Array<{ label: string; delta: number }> {
  const condition = save.heroine.growth.condition;
  const factors: Array<{ label: string; delta: number }> = [
    { label: '专注', delta: (condition.focus - 60) / 450 },
    { label: '疲劳', delta: -condition.fatigue / 360 },
    { label: '灵力状态', delta: (condition.spiritualPower - 55) / 650 },
  ];
  if (condition.stamina < 45) factors.push({ label: '体力不足', delta: -0.08 });
  if (condition.injury && condition.injury !== '无') factors.push({ label: '伤势', delta: -0.1 });
  if (condition.danPoison > 0) factors.push({ label: '丹毒', delta: -condition.danPoison / 500 });
  if (condition.mindDemon && condition.mindDemon !== '无') factors.push({ label: '心魔', delta: -0.12 });
  return factors;
}

function getMaterialDelta(materialItems: InventoryItem[]): { delta: number; factors: string[] } {
  const factors: string[] = [];
  const delta = materialItems.reduce((sum, item) => {
    const itemDelta = clamp(0.02 + getGradeBonus(item.grade) + getQualityBonus(item.quality), -0.04, 0.09);
    factors.push(factorLine(`材料:${item.name}/${item.grade}/${item.quality}`, itemDelta));
    return sum + itemDelta;
  }, 0);
  return { delta, factors };
}

function getSkillDelta(save: GameSave, operation: GrowthOperationDefinition): { delta: number; factors: string[] } {
  const factors: string[] = [];
  let delta = 0;
  const realmTier = getRealmTier(save);

  if (operation.section === 'arts') {
    const artId = getArtIdFromOperation(operation.id);
    if (!artId) return { delta, factors };
    const art = save.heroine.growth.arts[artId];
    const realmDelta = realmTier * 0.012;
    delta += realmDelta;
    factors.push(factorLine(`境界支撑(${save.heroine.growth.cultivationTrack.realm})`, realmDelta));

    if (operation.id.startsWith('learn_')) {
      const learnedDelta = art.learned ? 0.12 : 0;
      const proficiencyDelta = Math.min(art.proficiency, 60) / 600;
      delta += learnedDelta + proficiencyDelta;
      if (art.learned) factors.push(factorLine('已入门复习', learnedDelta));
      factors.push(factorLine(`${art.label}熟练度(${art.proficiency})`, proficiencyDelta));
      return { delta, factors };
    }

    const learnedDelta = art.learned ? getStageBonus(art.stage) : -0.22;
    const proficiencyDelta = Math.min(art.proficiency, 100) / 320;
    delta += learnedDelta + proficiencyDelta;
    factors.push(factorLine(art.learned ? `${art.label}阶段(${art.stage})` : `${art.label}未习得`, learnedDelta));
    factors.push(factorLine(`${art.label}熟练度(${art.proficiency})`, proficiencyDelta));
    return { delta, factors };
  }

  if (operation.section === 'life') {
    const fishing = save.heroine.growth.fishing;
    const proficiencyDelta = Math.min(fishing.proficiency, 100) / 360;
    const waterDelta = fishing.waterArea && fishing.waterArea !== '未选择水域' ? 0.06 : -0.04;
    const rodDelta = fishing.rodLabel && fishing.rodLabel !== '未配置' ? 0.04 : -0.06;
    delta += proficiencyDelta + waterDelta + rodDelta;
    factors.push(factorLine(`钓鱼熟练度(${fishing.proficiency})`, proficiencyDelta));
    factors.push(factorLine(`水域判断(${fishing.waterArea})`, waterDelta));
    factors.push(factorLine(`鱼竿(${fishing.rodLabel})`, rodDelta));
    return { delta, factors };
  }

  const track = save.heroine.growth.cultivationTrack;
  if (operation.id === 'cultivation_breakthrough') {
    const progressDelta = track.progress / 360;
    const readinessDelta = track.breakthroughReadiness / 280;
    const foundationDelta = (track.foundationStability - 50) / 420;
    delta += progressDelta + readinessDelta + foundationDelta;
    factors.push(factorLine(`修为进度(${track.progress})`, progressDelta));
    factors.push(factorLine(`突破准备(${track.breakthroughReadiness})`, readinessDelta));
    factors.push(factorLine(`根基稳定(${track.foundationStability})`, foundationDelta));
    return { delta, factors };
  }

  if (operation.id === 'cultivation_heal') {
    const medicine = save.heroine.growth.arts.medicine;
    const medicineDelta = (medicine.learned ? 0.08 : 0) + Math.min(medicine.proficiency, 100) / 500;
    delta += medicineDelta;
    factors.push(factorLine(`医术支撑(${medicine.stage}/${medicine.proficiency})`, medicineDelta));
    return { delta, factors };
  }

  const realmDelta = realmTier * 0.01;
  const foundationDelta = (track.foundationStability - 50) / 800;
  delta += realmDelta + foundationDelta;
  factors.push(factorLine(`境界支撑(${track.realm})`, realmDelta));
  factors.push(factorLine(`根基稳定(${track.foundationStability})`, foundationDelta));
  return { delta, factors };
}

function calculateSuccessPreview(
  save: GameSave,
  operation: GrowthOperationDefinition,
  selection: GrowthOperationSelection = {},
): GrowthOperationPreview {
  const costInspection = inspectCost(save, operation, selection);
  const factors = [factorLine('基础成功率', operation.baseSuccessRate)];
  let rate = operation.baseSuccessRate;

  for (const conditionFactor of getConditionFactors(save)) {
    rate += conditionFactor.delta;
    factors.push(factorLine(conditionFactor.label, conditionFactor.delta));
  }

  const material = getMaterialDelta(costInspection.materialItems);
  rate += material.delta;
  factors.push(...material.factors);

  const tool = getRequiredToolDelta(save, operation, selection);
  rate += tool.delta;
  if (tool.line) factors.push(tool.line);

  const skill = getSkillDelta(save, operation);
  rate += skill.delta;
  factors.push(...skill.factors);

  const activeBoosts = save.heroine.growth.activeBoosts.filter(boost => boost.remainingUses > 0);
  const boostDelta = activeBoosts.reduce((sum, boost) => sum + boost.successRateDelta, 0);
  if (boostDelta) {
    rate += boostDelta;
    factors.push(factorLine(`生效加成(${activeBoosts.map(boost => boost.label).join('、')})`, boostDelta));
  }

  if (!costInspection.canRun) {
    const missingPenalty = Math.min(0.28, costInspection.blockingReasons.length * 0.08);
    rate -= missingPenalty;
    factors.push(factorLine('缺少运行条件', -missingPenalty));
  }

  const maxRate = operation.riskLevel === 'none' ? 1 : 0.96;
  const successRate = roundRate(clamp(rate, 0.03, maxRate));
  const missingPercent = Math.max(0, Math.ceil((1 - successRate) * 100));
  const paidMakeupGrade = getOperationMakeupGrade(save, operation, costInspection.materialItems);
  const gradePrice = resolveGradePrice(paidMakeupGrade);
  const paidMakeupRiskMultiplier = getRiskMultiplier(operation.riskLevel);
  const paidMakeupUnitPrice = Math.round(gradePrice.unitPrice * paidMakeupRiskMultiplier);
  const paidMakeupCost = missingPercent * paidMakeupUnitPrice;
  const missingMaterialPurchases = createMaterialPurchasePreviews(costInspection.missingMaterialCategories, paidMakeupGrade);
  const materialPurchaseCost = missingMaterialPurchases.reduce((sum, item) => sum + item.totalPrice, 0);
  factors.push(`补满计价 ${gradePrice.label} ${gradePrice.unitPrice}/1% × 风险${paidMakeupRiskMultiplier}`);
  if (materialPurchaseCost) {
    factors.push(`缺材购买 ${missingMaterialPurchases.map(item => `${item.category}/${item.grade}/${item.totalPrice}`).join('、')}`);
  }

  return {
    operationId: operation.id,
    label: operation.label,
    successRate,
    successPercent: percent(successRate),
    missingPercent,
    paidMakeupCost,
    paidMakeupGrade: gradePrice.label,
    paidMakeupUnitPrice,
    paidMakeupRiskMultiplier,
    materialPurchaseCost,
    materialPurchaseGrade: gradePrice.label,
    missingMaterialPurchases,
    canRun: costInspection.canRun,
    canMakeupToFull: costInspection.canRun && missingPercent > 0,
    canPurchaseMissingMaterials: missingMaterialPurchases.length > 0 && costInspection.nonPurchasableBlockingReasons.length === 0,
    factors,
    blockingReasons: costInspection.blockingReasons,
    nonPurchasableBlockingReasons: costInspection.nonPurchasableBlockingReasons,
    consumedPreview: costInspection.consumedPreview,
    costSlots: costInspection.costSlots,
    toolSlot: tool.toolSlot || costInspection.toolSlot,
  };
}

export function previewGrowthOperation(
  save: GameSave,
  operationId: string,
  selection: GrowthOperationSelection = {},
): GrowthOperationPreview {
  const operation = getGrowthOperations().find(item => item.id === operationId);
  if (!operation) throw Error('未知玩法操作。');
  return calculateSuccessPreview(save, operation, selection);
}

export function previewGrowthOperations(
  save: GameSave,
  selections: Record<string, GrowthOperationSelection> = {},
): Record<string, GrowthOperationPreview> {
  return getGrowthOperations().reduce<Record<string, GrowthOperationPreview>>((result, operation) => {
    result[operation.id] = calculateSuccessPreview(save, operation, selections[operation.id] || {});
    return result;
  }, {});
}

function rollOutcome(successRate: number, riskLevel: GrowthOperationDefinition['riskLevel']): { outcome: GrowthOutcomeKind; roll: number } {
  const roll = Math.random();
  if (roll <= successRate) return { outcome: 'success', roll };
  if (roll <= successRate + 0.16) return { outcome: 'partial', roll };
  if (riskLevel === 'high' && roll >= 0.94) return { outcome: 'accident', roll };
  return { outcome: 'failure', roll };
}

function applyResourceCost(
  save: GameSave,
  operation: GrowthOperationDefinition,
  selection: GrowthOperationSelection = {},
): { save: GameSave; consumed: Record<string, number> } {
  const resources = { ...save.heroine.cultivation.resources };
  const consumed: Record<string, number> = {};
  for (const [key, amount] of Object.entries(operation.cost.resources || {})) {
    if ((resources[key] || 0) < amount) throw Error(`${key}不足。`);
    resources[key] = (resources[key] || 0) - amount;
    consumed[key] = amount;
  }

  let inventory = normalizeInventoryState(save.inventory);
  for (const rawCategory of operation.cost.inventoryCategories || []) {
    const category = normalizeInventoryCategory(rawCategory);
    const item = getCostItemForCategory(inventory.items, category, selection);
    if (!item) throw Error(`${category}不足。`);
    inventory = {
      ...inventory,
      items: inventory.items
        .map(current => (current.id === item.id ? { ...current, count: current.count - 1 } : current))
        .filter(current => current.count > 0),
    };
    consumed[item.name || category] = (consumed[item.name || category] || 0) + 1;
  }

  return {
    save: {
      ...save,
      inventory,
      heroine: {
        ...save.heroine,
        cultivation: {
          ...save.heroine.cultivation,
          resources,
        },
      },
    },
    consumed,
  };
}

function applyPaidMakeupCost(save: GameSave, operation: GrowthOperationDefinition, cost: number): GameSave {
  if (cost <= 0) return save;
  if (save.money.balance < cost) throw Error('现实资金不足，无法补满本轮成功率。');
  const timestamp = nowIso();
  return {
    ...save,
    money: {
      ...save.money,
      balance: save.money.balance - cost,
      spentTotal: save.money.spentTotal + cost,
      ledger: [
        {
          id: createId('money'),
          kind: 'payment' as const,
          label: `成功率补足:${operation.label}`,
          amount: cost,
          createdAtIso: timestamp,
        },
        ...save.money.ledger,
      ].slice(0, 80),
    },
  };
}

function purchaseMissingMaterials(save: GameSave, operation: GrowthOperationDefinition, preview: GrowthOperationPreview): GameSave {
  if (!preview.missingMaterialPurchases.length) return save;
  if (!preview.canPurchaseMissingMaterials) throw Error(preview.nonPurchasableBlockingReasons.join('；') || '当前缺口不能直接补材。');
  if (save.money.balance < preview.materialPurchaseCost) throw Error('现实资金不足，无法购买本轮缺少材料。');
  const timestamp = nowIso();
  const purchasedItems: ParsedAcquisitionItem[] = preview.missingMaterialPurchases.map(item => ({
    category: item.category,
    name: item.itemName,
    count: item.count,
    unit: item.unit,
    grade: item.grade,
    quality: '普通',
    source: '现实资金补材',
  }));
  return {
    ...save,
    money: {
      ...save.money,
      balance: save.money.balance - preview.materialPurchaseCost,
      spentTotal: save.money.spentTotal + preview.materialPurchaseCost,
      ledger: [
        {
          id: createId('money'),
          kind: 'payment' as const,
          label: `材料补购:${operation.label}`,
          amount: preview.materialPurchaseCost,
          createdAtIso: timestamp,
        },
        ...save.money.ledger,
      ].slice(0, 80),
    },
    inventory: applyParsedAcquisitionPacket(save.inventory, {
      schema: 'fairy_inventory_parse_v1',
      items: purchasedItems,
    }),
  };
}

function createMaterialPurchaseSummary(preview: GrowthOperationPreview): Record<string, number> {
  return preview.missingMaterialPurchases.reduce<Record<string, number>>((result, item) => {
    result[item.itemName] = (result[item.itemName] || 0) + item.count;
    return result;
  }, {});
}

function consumeActiveBoostUses(save: GameSave): GameSave {
  return {
    ...save,
    heroine: {
      ...save.heroine,
      growth: {
        ...save.heroine.growth,
        activeBoosts: save.heroine.growth.activeBoosts
          .map(boost => (boost.remainingUses > 0 ? { ...boost, remainingUses: boost.remainingUses - 1 } : boost))
          .filter(boost => boost.remainingUses > 0),
      },
    },
  };
}

