  if (/秘境|副本| realm/i.test(text)) return uiAssets.world.secretRealm;
  if (/NPC|npc|角色|人物/.test(text)) return uiAssets.world.npc;
  if (/遭遇|事件|encounter/i.test(text)) return uiAssets.world.encounter;
  if (/资源|矿点|resource/i.test(text)) return uiAssets.world.resourcePoint;
  if (/任务|种子|quest/i.test(text)) return uiAssets.world.questSeed;
  if (/交易|市场|market/i.test(text)) return uiAssets.world.marketTrade;
  if (/客栈|休息|inn/i.test(text)) return uiAssets.world.innRest;
  if (/炼丹/.test(text)) return uiAssets.world.alchemyRoom;
