import type { HeroinePublicSnapshot, OnlineRealmRuntimeState, OnlineRealmRoundState } from './types';
import { WORLD_WORKSHOP_API_BASE, WORLD_WORKSHOP_AUTH_TOKEN_KEY } from './worldWorkshop';

export interface CreateOnlineRealmRoomPayload {
  title: string;
  visibility: 'public' | 'password' | 'unlisted';
  password?: string;
  worldModuleIds: string[];
  secretRealmModuleId?: string;
  heroineName: string;
  heroineSnapshot: HeroinePublicSnapshot;
  playerSnapshot: string;
}

export interface JoinOnlineRealmPayload {
  password?: string;
  heroineName: string;
  heroineSnapshot: HeroinePublicSnapshot;
  playerSnapshot: string;
}

export interface SubmitOnlineRealmActionPayload {
  publicOperation: string;
  factPacketPreview?: string;
}

function getHostStorage(): Storage | null {
  if (typeof window === 'undefined') return null;
  try {
    return window.parent?.localStorage || window.localStorage;
  } catch {
    return null;
  }
}

function getAuthToken(): string | null {
  try {
    return getHostStorage()?.getItem(WORLD_WORKSHOP_AUTH_TOKEN_KEY) || null;
  } catch {
    return null;
  }
}

async function onlineRealmRequest<T>(
  path: string,
  opts: RequestInit = {},
  endpointBase = WORLD_WORKSHOP_API_BASE,
): Promise<T> {
  const token = getAuthToken();
  const headers: Record<string, string> = {
    ...((opts.headers as Record<string, string> | undefined) || {}),
  };

  if (token) headers.Authorization = `Bearer ${token}`;
  if (!(opts.body instanceof FormData)) headers['Content-Type'] = 'application/json';

  const response = await fetch(`${endpointBase}${path}`, {
    ...opts,
    headers,
  });

  if (!response.ok) {
    const data = await response.json().catch(() => ({ error: `HTTP ${response.status}` }));
    throw new Error(data.error || `联机秘境请求失败：${response.status}`);
  }

  return response.json() as Promise<T>;
}

export function createInitialOnlineRealmState(): OnlineRealmRuntimeState {
  return {
    endpointBase: WORLD_WORKSHOP_API_BASE,
    collaborationMode: 'idle',
    linkedSnapshotIds: [],
    pendingPublicOperations: [],
    collaborationLog: [],
    activeRoomId: '',
    activeRealmInstanceId: '',
    roomStatus: 'idle',
    members: [],
    finalizedRoundIds: [],
  };
}

export function normalizeOnlineRealmState(raw: unknown): OnlineRealmRuntimeState {
  const fallback = createInitialOnlineRealmState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<OnlineRealmRuntimeState>;
  return {
    endpointBase: typeof candidate.endpointBase === 'string' ? candidate.endpointBase : fallback.endpointBase,
    collaborationMode: candidate.collaborationMode || 'idle',
    linkedSnapshotIds: Array.isArray(candidate.linkedSnapshotIds) ? candidate.linkedSnapshotIds : [],
    pendingPublicOperations: Array.isArray(candidate.pendingPublicOperations) ? candidate.pendingPublicOperations : [],
    collaborationLog: Array.isArray(candidate.collaborationLog) ? candidate.collaborationLog : [],
    activeRoomId: typeof candidate.activeRoomId === 'string' ? candidate.activeRoomId : '',
    activeRealmInstanceId:
      typeof candidate.activeRealmInstanceId === 'string' ? candidate.activeRealmInstanceId : '',
    roomStatus: candidate.roomStatus || 'idle',
    members: Array.isArray(candidate.members) ? candidate.members : [],
    activeRound: candidate.activeRound,
    finalizedRoundIds: Array.isArray(candidate.finalizedRoundIds) ? candidate.finalizedRoundIds : [],
    lastSyncedAtIso: typeof candidate.lastSyncedAtIso === 'string' ? candidate.lastSyncedAtIso : undefined,
    lastError: typeof candidate.lastError === 'string' ? candidate.lastError : undefined,
  };
}

export async function createOnlineRealmRoom(
  payload: CreateOnlineRealmRoomPayload,
  endpointBase = WORLD_WORKSHOP_API_BASE,
): Promise<OnlineRealmRuntimeState> {
  return onlineRealmRequest('/api/cultivation-realm/rooms', {
    method: 'POST',
    body: JSON.stringify(payload),
  }, endpointBase);
}

export async function joinOnlineRealmRoom(
  roomId: string,
  payload: JoinOnlineRealmPayload,
  endpointBase = WORLD_WORKSHOP_API_BASE,
): Promise<OnlineRealmRuntimeState> {
  return onlineRealmRequest(`/api/cultivation-realm/rooms/${encodeURIComponent(roomId)}/join`, {
    method: 'POST',
    body: JSON.stringify(payload),
  }, endpointBase);
}

export async function fetchOnlineRealmState(
  roomId: string,
  endpointBase = WORLD_WORKSHOP_API_BASE,
): Promise<OnlineRealmRuntimeState> {
  return onlineRealmRequest(`/api/cultivation-realm/rooms/${encodeURIComponent(roomId)}`, {}, endpointBase);
}

export async function submitOnlineRealmAction(
  roundId: string,
  payload: SubmitOnlineRealmActionPayload,
  endpointBase = WORLD_WORKSHOP_API_BASE,
): Promise<{ ok: true }> {
  return onlineRealmRequest(`/api/cultivation-realm/rounds/${encodeURIComponent(roundId)}/action`, {
    method: 'POST',
    body: JSON.stringify(payload),
  }, endpointBase);
}

export async function leaveOnlineRealmRoom(
  roomId: string,
  endpointBase = WORLD_WORKSHOP_API_BASE,
): Promise<{ ok: true }> {
  return onlineRealmRequest(`/api/cultivation-realm/rooms/${encodeURIComponent(roomId)}/leave`, {
    method: 'POST',
  }, endpointBase);
}

export function buildOnlineRealmRoundScanText(round: OnlineRealmRoundState): string {
  const operations = round.publicOperations.length
    ? round.publicOperations.map(item => `  - ${item}`).join('\n')
    : '  - 暂无公开操作';

  return `<online_realm_idx310>\n秘境房间: ${round.roomId}\n回合: ${round.roundNo}\n状态: ${round.status}\n玩家操作:\n${operations}\n</online_realm_idx310>`;
}

export function activateSnapshotCollaboration(
  state: OnlineRealmRuntimeState,
  snapshotIds: string[],
  note = '快照同行协作已开启。',
): OnlineRealmRuntimeState {
  const linkedSnapshotIds = Array.from(new Set([...state.linkedSnapshotIds, ...snapshotIds.filter(Boolean)]));
  return {
    ...state,
    collaborationMode: linkedSnapshotIds.length ? 'snapshot_link' : 'idle',
    linkedSnapshotIds,
    roomStatus: linkedSnapshotIds.length ? 'exploring' : 'idle',
    collaborationLog: [note, ...state.collaborationLog].slice(0, 40),
    lastSyncedAtIso: new Date().toISOString(),
  };
}

export function activateLiveCollaboration(
  state: OnlineRealmRuntimeState,
  snapshotIds: string[] = state.linkedSnapshotIds,
  note = '无房间联动正文已开启。',
): OnlineRealmRuntimeState {
  const linkedSnapshotIds = Array.from(new Set([...state.linkedSnapshotIds, ...snapshotIds.filter(Boolean)]));
  return {
    ...state,
    collaborationMode: 'live_link',
    linkedSnapshotIds,
    roomStatus: 'exploring',
    activeRoomId: '',
    activeRealmInstanceId: '',
    collaborationLog: [note, ...state.collaborationLog].slice(0, 40),
    lastSyncedAtIso: new Date().toISOString(),
  };
}

export function deactivateSnapshotCollaboration(state: OnlineRealmRuntimeState, snapshotId?: string): OnlineRealmRuntimeState {
  const linkedSnapshotIds = snapshotId ? state.linkedSnapshotIds.filter(id => id !== snapshotId) : [];
  return {
    ...state,
    collaborationMode: linkedSnapshotIds.length ? state.collaborationMode : 'idle',
    linkedSnapshotIds,
    roomStatus: linkedSnapshotIds.length ? state.roomStatus : 'idle',
    collaborationLog: [`快照同行协作${snapshotId ? `移除 ${snapshotId}` : '已关闭'}。`, ...state.collaborationLog].slice(0, 40),
    lastSyncedAtIso: new Date().toISOString(),
  };
}

export function recordCooperativePublicOperation(
  state: OnlineRealmRuntimeState,
  publicOperation: string,
): OnlineRealmRuntimeState {
  if (state.collaborationMode === 'idle' && !state.linkedSnapshotIds.length) return state;
  return {
    ...state,
    pendingPublicOperations: [publicOperation, ...state.pendingPublicOperations].slice(0, 12),
    collaborationLog: [`协作正文操作: ${publicOperation}`, ...state.collaborationLog].slice(0, 40),
    lastSyncedAtIso: new Date().toISOString(),
  };
}

export function buildCooperativeNarrationScanText(state: OnlineRealmRuntimeState): string {
  if (state.collaborationMode === 'idle' && !state.linkedSnapshotIds.length && !state.pendingPublicOperations.length) {
    return '';
  }
  const snapshots = state.linkedSnapshotIds.length
    ? state.linkedSnapshotIds.map(id => `  - ${id}`).join('\n')
    : '  - 无';
  const operations = state.pendingPublicOperations.length
    ? state.pendingPublicOperations.map(item => `  - ${item}`).join('\n')
    : '  - 仅使用当前本地玩家操作';
  return [
    '<online_realm_idx310>',
    '协作正文模式:',
    `  模式: ${state.collaborationMode}`,
    '  规则:',
    '    - 不创建房间，不让服务器主持剧情。',
    '    - 本地正文生成时，把同行快照视作当前场景可行动角色。',
    '    - 奖励按本地结算或奖励包确认，不直接覆盖其他玩家存档。',
    '    - 若存在多名同行，正文应让她们自然协作、争执、互相补位，而不是轮流报菜名。',
    '  同行快照:',
    snapshots,
    '  近期协作操作:',
    operations,
    '</online_realm_idx310>',
  ].join('\n');
}
