import type { EmbeddedContextBlock, GameSave, InventoryItem, LearnedMethodState, WorldWorkshopModuleEntry } from './types';

function unique(values: string[]): string[] {
  return Array.from(new Set(values.map(item => item.trim()).filter(Boolean)));
}

function tokenize(text: string): string[] {
  const direct = text.match(/[\u4e00-\u9fa5A-Za-z0-9_]{2,}/g) || [];
  const phrases = text
    .split(/[^\u4e00-\u9fa5A-Za-z0-9_]+/)
    .map(item => item.trim())
    .filter(item => item.length >= 2);
  return unique([...direct, ...phrases]).slice(0, 80);
}

function textIncludesAny(text: string, keywords: string[]): boolean {
  return keywords.some(keyword => keyword.length >= 2 && text.includes(keyword));
}

function summarizeWorldEntry(entry: WorldWorkshopModuleEntry): string {
  return `${entry.label}（${entry.kind}${entry.sourceModuleId ? ` / ${entry.sourceModuleId}` : ''}）`;
}

function summarizeItem(item: InventoryItem): string {
  return `${item.category}:${item.name} x${item.count}${item.unit} / ${item.grade}`;
}

function summarizeMethod(method: LearnedMethodState): string {
  return `${method.kind}:${method.name} / ${method.grade} / ${method.progressLabel}`;
}

export function buildKeywordScanBlock(save: GameSave, publicOperation: string): EmbeddedContextBlock | null {
  const recentText = save.messages
    .slice(-6)
    .map(message => message.text)
    .join('\n');
  const scanSource = [
    publicOperation,
    save.heroine.display.sceneLabel,
    save.heroine.display.actionLabel,
    save.heroine.display.appearanceLabel,
    recentText,
  ].join('\n');
  const keywords = tokenize(scanSource);
  if (!keywords.length) return null;

  const selectedIds = new Set(save.worldWorkshop.selectedModuleIds);
  const worldHits = save.worldWorkshop.entryCache
    .filter(entry => selectedIds.has(entry.sourceModuleId || ''))
    .filter(entry => {
      const haystack = `${entry.label}\n${entry.kind}\n${entry.tags.join('\n')}\n${entry.yamlText}`;
      return textIncludesAny(haystack, keywords);
    })
    .slice(0, 6);
  const itemHits = save.inventory.items
    .filter(item => textIncludesAny(`${item.name}\n${item.category}\n${item.tags.join('\n')}\n${item.description}`, keywords))
    .slice(0, 8);
  const methodHits = save.inventory.methods
    .filter(method => textIncludesAny(`${method.name}\n${method.kind}\n${method.tags.join('\n')}\n${method.description}`, keywords))
    .slice(0, 6);
  const profileHits = save.mingyueMemory.dynamicProfiles
    .filter(profile => textIncludesAny(`${profile.characterName}\n${profile.dynamicContent}`, keywords))
    .slice(0, 4);
  const operationHits = save.operationLog
    .filter(entry => textIncludesAny(`${entry.label}\n${entry.detail}\n${entry.publicOperation || ''}`, keywords))
    .slice(0, 6);

  if (!worldHits.length && !itemHits.length && !methodHits.length && !profileHits.length && !operationHits.length) return null;

  return {
    id: 'keyword_scan',
    kind: 'keyword_scan',
    slot: 'runtime_context',
    tagName: 'keyword_scan',
    index: 330,
    label: '关键词扫描插入',
    priority: 860,
    matchReason: '按本轮操作、当前场景和最近正文命中可用上下文',
    source: 'save',
    yamlText: [
      '关键词扫描插入:',
      '  原则:',
      '    - 只补充本轮可能相关的世界模块、物品、功法、角色记忆和近期操作。',
      '    - 不越过本轮结算记录，不改判成功率、奖励、消耗和已保存状态。',
      '    - 若命中内容与本轮操作无关，正文应忽略，不强行展开。',
      `  命中关键词: [${keywords.slice(0, 20).join(', ')}]`,
      '  世界模块命中:',
      ...(worldHits.length ? worldHits.map(entry => `    - ${summarizeWorldEntry(entry)}`) : ['    - 无']),
      '  背包物品命中:',
      ...(itemHits.length ? itemHits.map(item => `    - ${summarizeItem(item)}`) : ['    - 无']),
      '  功法术法命中:',
      ...(methodHits.length ? methodHits.map(method => `    - ${summarizeMethod(method)}`) : ['    - 无']),
      '  角色记忆命中:',
      ...(profileHits.length ? profileHits.map(profile => `    - ${profile.characterName}`) : ['    - 无']),
      '  近期操作命中:',
      ...(operationHits.length ? operationHits.map(entry => `    - ${entry.label}: ${entry.detail}`) : ['    - 无']),
    ].join('\n'),
  };
}
