import type { EmbeddedPromptAssembly, GameSave, HundredArtId } from './types';
import { equipInventoryItem } from './equipmentWardrobe';
import { HUNDRED_ART_IDS, getArtLabel } from './growthGameplay';
import { previewGrowthOperation, resolveGrowthOperation } from './gameplayResolution';
import { recordAssistantStoryOutput } from './narration';
import { buildEmbeddedPromptAssembly, wrapPublicOperationForPrompt } from './promptComposer';
import { createInitialGameSave, normalizeGameSave } from './save';

interface GameplayLogicCheckItem {
  label: string;
  ok: boolean;
  detail: string;
}

export interface GameplayLogicCheckResult {
  ok: boolean;
  report: string;
  checks: GameplayLogicCheckItem[];
}

const ART_RULE_TAGS: Record<HundredArtId, string> = {
  alchemy: 'hundred_art_alchemy_rule_idx121',
  forging: 'hundred_art_forging_rule_idx122',
  formation: 'hundred_art_formation_rule_idx123',
  talisman: 'hundred_art_talisman_rule_idx124',
  medicine: 'hundred_art_medicine_rule_idx125',
  beast_taming: 'hundred_art_beast_taming_rule_idx126',
  puppet: 'hundred_art_puppet_rule_idx127',
  herbology: 'hundred_art_herbology_rule_idx128',
};

const RUNTIME_RULE_TAG = 'gameplay_art_runtime_rule_idx120';
const FISHING_RULE_TAG = 'fishing_runtime_rule_idx129';
const ROUND_RECORD_TAG = 'round_record_idx60';

function cloneSave(save: GameSave): GameSave {
  return JSON.parse(JSON.stringify(save)) as GameSave;
}

function createCheckSave(currentSave: GameSave): GameSave {
  const fixture = normalizeGameSave(createInitialGameSave());
  return {
    ...fixture,
    worldbook: cloneSave(currentSave).worldbook,
    worldWorkshop: cloneSave(currentSave).worldWorkshop,
    onlineRealm: cloneSave(currentSave).onlineRealm,
  };
}

function blockTag(block: EmbeddedPromptAssembly['blocks'][number]): string {
  return block.wrapTag || `${block.tagName}_idx${block.index}`;
}

function blockTags(assembly: EmbeddedPromptAssembly): string[] {
  return assembly.blocks.map(blockTag);
}

function hasTag(assembly: EmbeddedPromptAssembly, tag: string): boolean {
  return blockTags(assembly).includes(tag);
}

function hasWrappedTag(assembly: EmbeddedPromptAssembly, tag: string): boolean {
  return assembly.injectionText.includes(`<${tag}>`) && assembly.injectionText.includes(`</${tag}>`);
}

function hasAnyGameplayTag(assembly: EmbeddedPromptAssembly): boolean {
  const tags = new Set(blockTags(assembly));
  return [RUNTIME_RULE_TAG, FISHING_RULE_TAG, ...Object.values(ART_RULE_TAGS)].some(tag => tags.has(tag));
}

function rewardCount(assemblyResult: ReturnType<typeof resolveGrowthOperation>): number {
  return Object.keys(assemblyResult.factPacket.frontendResult?.rewards || {}).length;
}

function countItem(save: GameSave, itemName: string): number {
  return save.inventory.items.filter(item => item.name === itemName).reduce((sum, item) => sum + item.count, 0);
}

function addCheck(checks: GameplayLogicCheckItem[], label: string, ok: boolean, detail: string): void {
  checks.push({ label, ok, detail });
}

function formatPercent(value: number): string {
  return `${Math.round(value * 100)}%`;
}

function createAssembly(save: GameSave, result: ReturnType<typeof resolveGrowthOperation>): EmbeddedPromptAssembly {
  return buildEmbeddedPromptAssembly(save, {
    task: 'story',
    publicOperation: result.publicOperation,
    factPacket: result.factPacket,
  });
}

function formatReport(checks: GameplayLogicCheckItem[], tagGroups: Record<string, string[]>): string {
  const failed = checks.filter(item => !item.ok);
  return [
    '玩法脚本逻辑自检',
    `总结果: ${failed.length ? '未通过' : '通过'}`,
    `通过: ${checks.length - failed.length}/${checks.length}`,
    '',
    '检查项:',
    ...checks.map(item => `${item.ok ? '[OK]' : '[FAIL]'} ${item.label} - ${item.detail}`),
    '',
    '命中块:',
    ...Object.entries(tagGroups).map(([label, tags]) => `${label}: ${tags.join('、') || '无'}`),
  ].join('\n');
}

export function runGameplayLogicCheck(currentSave: GameSave): GameplayLogicCheckResult {
  const checks: GameplayLogicCheckItem[] = [];
  const tagGroups: Record<string, string[]> = {};

  try {
    for (const artId of HUNDRED_ART_IDS) {
      const operationId = `practice_${artId}`;
      const artLabel = getArtLabel(artId);
      const artSave = createCheckSave(currentSave);
      const preview = previewGrowthOperation(artSave, operationId);
      const result = resolveGrowthOperation(artSave, operationId, {
        purchaseMissingMaterials: true,
        usePaidMakeup: true,
      });
      const assembly = createAssembly(result.save, result);
      const tags = blockTags(assembly);
      tagGroups[`百艺:${artLabel}`] = tags.filter(tag => tag === RUNTIME_RULE_TAG || tag === ART_RULE_TAGS[artId] || tag === ROUND_RECORD_TAG);

      addCheck(
        checks,
        `${artLabel}预览可补材`,
        preview.canPurchaseMissingMaterials,
        `自然成功率 ${formatPercent(preview.successRate)}，缺材补购 ${preview.materialPurchaseCost}`,
      );
      addCheck(
        checks,
        `${artLabel}结算成功`,
        result.factPacket.frontendResult?.outcome === 'success',
        `最终成功率 ${formatPercent(result.factPacket.frontendResult?.successRate || 0)}`,
      );
      addCheck(
        checks,
        `${artLabel}补材和补满生效`,
        Boolean(result.factPacket.frontendResult?.materialPurchased && result.factPacket.frontendResult?.paidSupplement),
        `补材 ${result.factPacket.frontendResult?.materialPurchaseCost || 0}，补满 ${result.factPacket.frontendResult?.paidMakeupCost || 0}`,
      );
      addCheck(checks, `${artLabel}奖励已登记`, rewardCount(result) > 0, `奖励 ${JSON.stringify(result.factPacket.frontendResult?.rewards || {})}`);
      addCheck(
        checks,
        `${artLabel}注入块命中`,
        hasTag(assembly, RUNTIME_RULE_TAG) && hasTag(assembly, ART_RULE_TAGS[artId]) && hasTag(assembly, ROUND_RECORD_TAG),
        tagGroups[`百艺:${artLabel}`].join('、'),
      );
      addCheck(
        checks,
        `${artLabel}注入文本有标签包裹`,
        [RUNTIME_RULE_TAG, ART_RULE_TAGS[artId], ROUND_RECORD_TAG].every(tag => hasWrappedTag(assembly, tag)),
        'runtime_context、world_info_after、round_record 均进入 injects',
      );
    }

    const fishingSave = createCheckSave(currentSave);
    const fishingPreview = previewGrowthOperation(fishingSave, 'fishing_cast');
    const fishingResult = resolveGrowthOperation(fishingSave, 'fishing_cast', { usePaidMakeup: true });
    const fishingAssembly = createAssembly(fishingResult.save, fishingResult);
    tagGroups.钓鱼 = blockTags(fishingAssembly).filter(tag => tag === RUNTIME_RULE_TAG || tag === FISHING_RULE_TAG || tag === ROUND_RECORD_TAG);
    addCheck(checks, '钓鱼预览可执行', fishingPreview.canRun, `自然成功率 ${formatPercent(fishingPreview.successRate)}`);
    addCheck(checks, '钓鱼结算成功', fishingResult.factPacket.frontendResult?.outcome === 'success', `奖励 ${JSON.stringify(fishingResult.factPacket.frontendResult?.rewards || {})}`);
    addCheck(
      checks,
      '钓鱼消耗和奖励入库',
      Object.keys(fishingResult.factPacket.frontendResult?.consumed || {}).some(key => key.includes('鱼饵')) &&
        Object.keys(fishingResult.factPacket.frontendResult?.rewards || {}).some(key => key.includes('青灵鲤')),
      `消耗 ${JSON.stringify(fishingResult.factPacket.frontendResult?.consumed || {})}`,
    );
    addCheck(
      checks,
      '钓鱼注入块命中',
      hasTag(fishingAssembly, RUNTIME_RULE_TAG) && hasTag(fishingAssembly, FISHING_RULE_TAG) && hasTag(fishingAssembly, ROUND_RECORD_TAG),
      tagGroups.钓鱼.join('、'),
    );
    const constrainedAssembly = buildEmbeddedPromptAssembly(fishingResult.save, {
      task: 'story',
      publicOperation: fishingResult.publicOperation,
      factPacket: fishingResult.factPacket,
      maxBlocks: 1,
    });
    addCheck(
      checks,
      '关键提示块不被数量上限裁掉',
      hasTag(constrainedAssembly, 'response_rule_idx20') && hasTag(constrainedAssembly, ROUND_RECORD_TAG),
      blockTags(constrainedAssembly).join('、'),
    );
    addCheck(
      checks,
      '钓鱼不误注入百艺规则',
      !Object.values(ART_RULE_TAGS).some(tag => hasTag(fishingAssembly, tag)),
      '只应命中钓鱼规则，不带炼丹/炼器等百艺细则',
    );

    const beforeDuplicateFish = countItem(fishingResult.save, '青灵鲤');
    const parsedFishSave = recordAssistantStoryOutput(
      fishingResult.save,
      [
        '她把鱼篓往你这边一推，嘴上说只是运气。',
        '<gain>',
        '鱼获|青灵鲤|1|尾|黄级下品|新鲜|重复正文',
        '鱼获|银鳞鱼|1|尾|黄级下品|新鲜|额外正文',
        '</gain>',
      ].join('\n'),
      fishingResult.factPacket,
    );
    addCheck(
      checks,
      '正文隐藏解析过滤已登记奖励',
      countItem(parsedFishSave, '青灵鲤') === beforeDuplicateFish,
      `青灵鲤 ${beforeDuplicateFish} -> ${countItem(parsedFishSave, '青灵鲤')}`,
    );
    addCheck(
      checks,
      '正文隐藏解析保留额外获得',
      countItem(parsedFishSave, '银鳞鱼') >= 1,
      `银鳞鱼 ${countItem(parsedFishSave, '银鳞鱼')}`,
    );

    const equipmentResult = equipInventoryItem(fishingResult.save, 'item_工具_普通鱼竿_凡物_普通_根', '鱼竿');
    const parsedEquipmentSave = recordAssistantStoryOutput(
      equipmentResult.save,
      ['她低头看了看手里的鱼竿。', '<gain>', '装|鱼竿|玄铁鱼竿', '</gain>'].join('\n'),
      equipmentResult.factPacket,
    );
    addCheck(
      checks,
      '装备正文不覆盖前端槽位',
      parsedEquipmentSave.inventory.equipped.鱼竿 === equipmentResult.save.inventory.equipped.鱼竿,
      `鱼竿 ${equipmentResult.save.inventory.equipped.鱼竿} -> ${parsedEquipmentSave.inventory.equipped.鱼竿}`,
    );

    const accessorySave = createCheckSave(currentSave);
    accessorySave.inventory.items = [
      ...accessorySave.inventory.items,
      {
        id: 'check_玉铃',
        name: '白玉铃',
        category: '饰品',
        count: 1,
        unit: '枚',
        grade: '黄级下品',
        quality: '普通',
        description: '自检饰品。',
        tags: ['自检'],
        source: '自检',
        updatedAtIso: new Date().toISOString(),
      },
    ];
    const onceEquipped = equipInventoryItem(accessorySave, 'check_玉铃', '饰品一').save;
    let blockedSecondSlot = false;
    try {
      equipInventoryItem(onceEquipped, 'check_玉铃', '饰品二');
    } catch {
      blockedSecondSlot = true;
    }
    addCheck(
      checks,
      '同名装备数量不足时禁止多槽占用',
      blockedSecondSlot,
      blockedSecondSlot ? '已阻止 1 件饰品同时装备到两个槽位' : '未阻止重复装备',
    );

    const plainAfterActionAssembly = buildEmbeddedPromptAssembly(fishingResult.save, {
      task: 'story',
      publicOperation: '玩家操作：让她看一眼天色。',
    });
    const wrappedPlainInput = wrapPublicOperationForPrompt(plainAfterActionAssembly.publicOperation);
    tagGroups.普通操作 = blockTags(plainAfterActionAssembly).filter(tag => tag === RUNTIME_RULE_TAG || tag === FISHING_RULE_TAG || Object.values(ART_RULE_TAGS).includes(tag as string));
    addCheck(
      checks,
      '普通操作不串上一轮玩法规则',
      !hasAnyGameplayTag(plainAfterActionAssembly),
      tagGroups.普通操作.join('、') || '未命中玩法规则，符合预期',
    );
    addCheck(
      checks,
      '公开输入只保留玩家操作标签',
      wrappedPlainInput.startsWith('<player_action>') && wrappedPlainInput.endsWith('</player_action>'),
      wrappedPlainInput.replace(/\n/g, '\\n'),
    );
  } catch (error) {
    addCheck(checks, '自检执行异常', false, error instanceof Error ? error.message : String(error));
  }

  const ok = checks.every(item => item.ok);
  return {
    ok,
    checks,
    report: formatReport(checks, tagGroups),
  };
}
