import type { EmbeddedContextBlock } from './types';

function fixedWorldBlock(
  id: string,
  wrapTag: string,
  index: number,
  label: string,
  yamlText: string,
  priority: number,
): EmbeddedContextBlock {
  return {
    id,
    kind: 'worldbook_placeholder',
    slot: 'world_info_before',
    tagName: wrapTag.replace(/_id\d+$/, ''),
    wrapTag,
    index,
    label,
    yamlText,
    priority,
    matchReason: '固定世界观每轮注入',
    source: 'built_in',
  };
}

