import type {
  ActionFactPacket,
  ActionSectionId,
  GameSave,
  InventoryCategory,
  InventoryItem,
  ResolvedGameplayAction,
} from './types';
import { createId, nowIso, recordOperation } from './save';

export interface EquipmentSlotDefinition {
  slot: string;
  label: string;
  accepts: InventoryCategory[];
  summary: string;
  wardrobe?: boolean;
}

export const EQUIPMENT_SLOT_DEFINITIONS: EquipmentSlotDefinition[] = [
  { slot: '主武', label: '主武', accepts: ['武器'], summary: '主要武器，影响战斗、护身和修炼演出。' },
  { slot: '副器', label: '副器', accepts: ['武器', '法宝', '工具'], summary: '副手器物，适合符笔、短刃、辅助法器。' },
  { slot: '头部', label: '头部', accepts: ['防具', '饰品'], summary: '发冠、护额、头部防具。' },
  { slot: '身体', label: '身体', accepts: ['防具'], summary: '衣甲、护身衣、防具主体。' },
  { slot: '腰带', label: '腰带', accepts: ['防具', '饰品'], summary: '腰封、储物带、束带。' },
  { slot: '鞋履', label: '鞋履', accepts: ['防具'], summary: '鞋履、靴子、身法辅助装备。' },
  { slot: '饰品一', label: '饰品一', accepts: ['饰品'], summary: '玉佩、发簪、手镯等饰物。' },
  { slot: '饰品二', label: '饰品二', accepts: ['饰品'], summary: '第二饰品位。' },
  { slot: '法宝', label: '法宝', accepts: ['法宝'], summary: '战斗或护身法宝。' },
  { slot: '心法', label: '心法', accepts: ['心法'], summary: '当前运转心法。' },
  { slot: '主修功法', label: '主修功法', accepts: ['功法'], summary: '主修路线。' },
  { slot: '辅修功法', label: '辅修功法', accepts: ['功法'], summary: '辅修路线。' },
  { slot: '鱼竿', label: '鱼竿', accepts: ['鱼竿'], summary: '钓鱼工具。' },
  { slot: '鱼饵', label: '鱼饵', accepts: ['鱼饵'], summary: '当前钓饵。' },
  { slot: '时装', label: '时装', accepts: ['时装', '杂物', '其他'], summary: '外观套装，后续绑定正比例立绘。', wardrobe: true },
  { slot: '发型', label: '发型', accepts: ['时装', '饰品'], summary: '发型外观位。', wardrobe: true },
  { slot: '背饰', label: '背饰', accepts: ['时装', '饰品', '法宝'], summary: '披帛、背饰、装饰法器。', wardrobe: true },
  { slot: '妆容', label: '妆容', accepts: ['时装', '杂物'], summary: '妆容与细节外观。', wardrobe: true },
  { slot: '特效', label: '特效', accepts: ['时装', '法宝', '其他'], summary: '光效、气息、灵纹外观。', wardrobe: true },
];

function findSlot(slot: string): EquipmentSlotDefinition | undefined {
  return EQUIPMENT_SLOT_DEFINITIONS.find(item => item.slot === slot || item.label === slot);
}

function inferSlot(item: InventoryItem, preferredSlot?: string): EquipmentSlotDefinition {
  if (preferredSlot) {
    const slot = findSlot(preferredSlot);
    if (!slot) throw new Error(`未知装备槽位：${preferredSlot}`);
    return slot;
  }
  const tagText = `${item.category} ${item.name} ${item.tags.join(' ')}`;
  if (/时装|衣裙|仙裙|外观|套装/.test(tagText)) return findSlot('时装')!;
  if (/发型|发冠|簪/.test(tagText)) return findSlot('发型')!;
  if (/背饰|披风|披帛/.test(tagText)) return findSlot('背饰')!;
  if (/鱼竿|钓竿/.test(tagText)) return findSlot('鱼竿')!;
  if (/鱼饵|钓饵/.test(tagText)) return findSlot('鱼饵')!;
  if (/剑|刀|枪|弓|刃/.test(tagText) && item.category === '武器') return findSlot('主武')!;
  if (/衣|甲|袍|裙/.test(tagText) && item.category === '防具') return findSlot('身体')!;
  if (/坠|佩|戒|镯|簪/.test(tagText) && item.category === '饰品') return findSlot('饰品一')!;
  return EQUIPMENT_SLOT_DEFINITIONS.find(slot => slot.accepts.includes(item.category)) || findSlot('随身物') || findSlot('时装')!;
}

function assertSlotAcceptsItem(slot: EquipmentSlotDefinition, item: InventoryItem): void {
  if (slot.accepts.includes(item.category)) return;
  if (slot.wardrobe && item.tags.some(tag => /时装|外观|套装|服装/.test(tag))) return;
  throw new Error(`${item.name} 属于 ${item.category}，不能放入 ${slot.label}。`);
}

function countEquippedName(equipped: Record<string, string>, itemName: string, excludeSlot = ''): number {
  return Object.entries(equipped).filter(([slot, name]) => slot !== excludeSlot && name === itemName).length;
}

function syncEquippedItemFlags(
  items: InventoryItem[],
  equipped: Record<string, string>,
  timestamp: string,
): InventoryItem[] {
  const equippedNames = new Set(Object.values(equipped).filter(Boolean));
  return items.map(item => {
    const equippedFlag = equippedNames.has(item.name);
    return item.equipped === equippedFlag ? item : { ...item, equipped: equippedFlag, updatedAtIso: timestamp };
  });
}

function buildFactPacket(
  actionId: string,
  section: ActionSectionId,
  publicOperation: string,
  slot: string,
  itemName: string,
  save: GameSave,
  wardrobe: boolean,
): ActionFactPacket {
  return {
    actionId,
    section,
    publicOperation,
    resultSummary: `${slot} 已切换为 ${itemName}。`,
    stateDelta: {
      槽位: slot,
      当前物品: itemName,
      当前外观: save.heroine.display.appearanceLabel,
    },
    frontendResult: {
      outcome: 'success',
      rewards: {},
      notes: [
        wardrobe ? '时装外观已经由界面切换，正文只描写她对换装的反应。' : '装备位已经由界面切换，正文只描写她试用装备的反应。',
        '本轮没有新增获得物，不要写入 <gain>。',
      ],
    },
    performanceHint: {
      expression: wardrobe ? '别扭' : '认真',
      action: wardrobe ? `换上${itemName}` : `装备${itemName}`,
      portrait: save.heroine.display.formalPoseId,
      chibi: wardrobe ? 'dressUp' : 'equip',
      scene: save.heroine.display.sceneLabel,
    },
    debugOnly: true,
  };
}

export function equipInventoryItem(save: GameSave, itemId: string, preferredSlot?: string): ResolvedGameplayAction {
  const item = save.inventory.items.find(entry => entry.id === itemId);
  if (!item) throw new Error('找不到要装备的物品。');
  if (item.count <= 0) throw new Error('该物品数量为 0，不能装备。');
  if (item.locked) throw new Error('该物品已锁定，不能直接装备。');
  const slot = inferSlot(item, preferredSlot);
  assertSlotAcceptsItem(slot, item);
  const timestamp = nowIso();
  const previousName = save.inventory.equipped[slot.slot] || '';
  if (previousName !== item.name && countEquippedName(save.inventory.equipped, item.name, slot.slot) >= item.count) {
    throw new Error(`${item.name} 数量不足，不能同时装备到更多槽位。`);
  }
  const nextEquipped = {
    ...save.inventory.equipped,
    [slot.slot]: item.name,
  };
  const nextSave: GameSave = {
    ...save,
    inventory: {
      ...save.inventory,
      equipped: nextEquipped,
      items: syncEquippedItemFlags(save.inventory.items, nextEquipped, timestamp),
    },
    heroine: {
      ...save.heroine,
      display: {
        ...save.heroine.display,
        actionLabel: slot.wardrobe ? `换上${item.name}` : `装备${item.name}`,
        appearanceLabel: slot.wardrobe ? item.name : save.heroine.display.appearanceLabel,
      },
    },
  };
  const publicOperation = `玩家操作：让她将${item.name}装备到${slot.label}。`;
  const factPacket = buildFactPacket(
    `equip_${item.id}_${slot.slot}`,
    slot.wardrobe ? 'wardrobe' : 'equipment',
    publicOperation,
    slot.label,
    item.name,
    nextSave,
    Boolean(slot.wardrobe),
  );
  return {
    save: recordOperation(nextSave, {
      actionType: slot.wardrobe ? 'WARDROBE_ACTION' : 'EQUIPMENT_ACTION',
      label: slot.wardrobe ? '时装切换' : '装备切换',
      detail: `${slot.label}: ${item.name}`,
      section: slot.wardrobe ? '时装' : '装备',
      publicOperation,
      factPacketPreview: JSON.stringify(factPacket, null, 2),
    }),
    publicOperation,
    factPacket,
  };
}

export function applyWardrobeItem(save: GameSave, itemId: string, preferredSlot = '时装'): ResolvedGameplayAction {
  return equipInventoryItem(save, itemId, preferredSlot);
}

export function unequipSlot(save: GameSave, slotName: string): ResolvedGameplayAction {
  const slot = findSlot(slotName);
  if (!slot) throw new Error(`未知装备槽位：${slotName}`);
  const previousName = save.inventory.equipped[slot.slot] || '';
  if (!previousName) throw new Error(`${slot.label} 当前没有可卸下的物品。`);
  const timestamp = nowIso();
  const nextEquipped = {
    ...save.inventory.equipped,
    [slot.slot]: '',
  };
  const nextSave: GameSave = {
    ...save,
    inventory: {
      ...save.inventory,
      equipped: nextEquipped,
      items: syncEquippedItemFlags(save.inventory.items, nextEquipped, timestamp),
    },
    heroine: {
      ...save.heroine,
      display: {
        ...save.heroine.display,
        actionLabel: `卸下${previousName}`,
        appearanceLabel: slot.wardrobe ? '默认服装' : save.heroine.display.appearanceLabel,
      },
    },
  };
  const publicOperation = `玩家操作：让她卸下${slot.label}上的${previousName}。`;
  const factPacket = buildFactPacket(
    `unequip_${slot.slot}_${createId('slot')}`,
    slot.wardrobe ? 'wardrobe' : 'equipment',
    publicOperation,
    slot.label,
    '无',
    nextSave,
    Boolean(slot.wardrobe),
  );
  return {
    save: recordOperation(nextSave, {
      actionType: slot.wardrobe ? 'WARDROBE_ACTION' : 'EQUIPMENT_ACTION',
      label: slot.wardrobe ? '卸下时装' : '卸下装备',
      detail: `${slot.label}: ${previousName}`,
      section: slot.wardrobe ? '时装' : '装备',
      publicOperation,
      factPacketPreview: JSON.stringify(factPacket, null, 2),
    }),
    publicOperation,
    factPacket,
  };
}

export function buildEquipmentWardrobePromptYaml(save: GameSave): string {
  const equippedLines = EQUIPMENT_SLOT_DEFINITIONS.map(slot => `    ${slot.label}: ${save.inventory.equipped[slot.slot] || '空'}`);
  return [
    '装备与时装规则:',
    '  装备原则: 装备位由界面保存，正文只参考当前装备和外观，不直接改写槽位。',
    '  时装原则: 时装用于立绘/外观切换，后续素材到位后由文件名绑定正比例立绘。',
    '  正文反馈: 装备、换衣、试穿、卸下都要写她的动作、表情和态度，但不要重复生成获得物。',
    '  当前槽位:',
    ...equippedLines,
  ].join('\n');
}
